class _QuietWindowsLogger:
    """Keep routine Windows plugin progress out of the terminal.

    Successful syncs, member refreshes and command acknowledgements remain
    available at DEBUG level; warnings and errors stay visible for diagnosis.
    """

    def __init__(self, wrapped):
        self._wrapped = wrapped

    def info(self, *args, **kwargs):
        return self._wrapped.debug(*args, **kwargs)

    def __getattr__(self, name):
        return getattr(self._wrapped, name)


logger = _QuietWindowsLogger(logger)


def _schema_default_value(node):
    if not isinstance(node, dict):
        return None
    if "default" in node:
        return node["default"]

    node_type = node.get("type")
    if node_type == "object":
        items = node.get("items")
        if not isinstance(items, dict):
            return {}
        defaults = {}
        for key, item in items.items():
            value = _schema_default_value(item)
            if value is not None:
                defaults[key] = value
        return defaults
    if node_type == "list":
        return []
    if node_type == "bool":
        return False
    if node_type in {"int", "float"}:
        return 0
    if node_type in {"string", "text"}:
        return ""
    return None


def _load_schema_default_config() -> dict:
    schema_path = Path(__file__).with_name("_conf_schema.json")
    try:
        with schema_path.open("r", encoding="utf-8") as schema_file:
            schema = json.load(schema_file)
        if not isinstance(schema, dict):
            return {}
        defaults = {}
        for key, node in schema.items():
            value = _schema_default_value(node)
            if value is not None:
                defaults[key] = value
        return defaults
    except Exception as exc:
        logger.warning(f"读取默认配置模板失败: {exc}")
        return {}


def _install_aiocqhttp_resultstore_guard() -> None:
    """Ignore late reverse-WebSocket replies after an API wait timed out.

    aiocqhttp removes a timed-out future from ``ResultStore`` in ``fetch``.
    A delayed NapCat reply can nevertheless arrive afterwards and older
    aiocqhttp releases call ``set_result`` on a cancelled future, raising
    ``asyncio.InvalidStateError`` inside Quart's WebSocket handler.  The
    plugin cannot upgrade the host's bundled aiocqhttp on every deployment,
    so install this small compatibility guard at runtime instead.
    """
    try:
        from aiocqhttp.api_impl import ResultStore

        if getattr(ResultStore, "_joker_safe_add", False):
            return

        @classmethod
        def safe_add(cls, result):
            if not isinstance(result, dict):
                return
            echo = result.get("echo")
            if not isinstance(echo, dict) or not isinstance(echo.get("seq"), int):
                return
            future = cls._futures.get(echo["seq"])
            if future is None or future.done():
                return
            try:
                future.set_result(result)
            except asyncio.InvalidStateError:
                # A timeout/cancellation can win between the state check and
                # set_result on a different event-loop callback.
                return

        ResultStore.add = safe_add
        ResultStore._joker_safe_add = True
    except Exception:
        # aiocqhttp is optional during static checks and unit tests.
        logger.debug("aiocqhttp ResultStore 兼容保护安装失败", exc_info=True)


_install_aiocqhttp_resultstore_guard()

