def _resolve_group_feature_category(value: str):
    """Resolve a group feature key, Chinese label, alias, or *_enabled key."""
    normalized = str(value or "").strip()
    if not normalized:
        return None
    direct_key = normalized[:-8] if normalized.endswith("_enabled") else normalized
    category = FEATURE_BY_KEY.get(direct_key) or FEATURE_BY_KEY.get(direct_key.lower())
    if category is not None:
        return category
    alias_key = feature_alias_map().get(normalized)
    if alias_key:
        alias_key = alias_key[:-8] if alias_key.endswith("_enabled") else alias_key
        return FEATURE_BY_KEY.get(alias_key)
    return FEATURE_BY_COMMAND.get(normalized)


def _compact_reply_text(text: str) -> str:
    """Normalize bot replies before they reach QQ and the Windows console.

    Keep the command wording intact for compatibility with the previous
    Windows plugin replies. Only layout noise is normalized here: line ending,
    repeated blank lines, indentation from multi-line literals and trailing
    spaces.
    """
    if not isinstance(text, str):
        return text

    normalized = textwrap.dedent(text).replace("\r\n", "\n").replace("\r", "\n")
    lines = []
    previous_blank = False
    for raw_line in normalized.split("\n"):
        line = raw_line.rstrip()
        if not line.strip():
            if lines and not previous_blank:
                lines.append("")
            previous_blank = True
            continue
        # Keep hierarchy readable, but prevent large template indentation from
        # wasting message width on mobile clients.
        line = re.sub(r"^[ \t]{3,}", "  ", line)
        lines.append(line)
        previous_blank = False
    compact = "\n".join(lines).strip()
    return compact


@register("astrbot_plugin_joker", "Joker", "SCUM 查询与 QQ 群管插件", "1.11.414")
class MyPlugin(Star):
    _MEMBER_REFRESH_WARNING_COOLDOWN_SECONDS = 300
    _GROUP_BOT_ACTIVITY_TTL_SECONDS = 120
    # NapCat may return a just-kicked member from its short-lived member-list
    # cache. Keep confirmed departures out of the next refresh briefly; a
    # real rejoin event clears the quarantine immediately.
    _MEMBER_REMOVAL_QUARANTINE_SECONDS = 300
    # Keep the audit queue lossless during transient disk/fsync slowdowns.
    # ``asyncio.Queue(maxsize=0)`` is unbounded; the enqueue path emits a
    # warning when sustained backlog suggests a storage bottleneck.
    _MESSAGE_CACHE_QUEUE_MAXSIZE = 0
    _MESSAGE_CACHE_QUEUE_WARN_SIZE = 1000
    _MESSAGE_CACHE_MAINTENANCE_INTERVAL_SECONDS = 900
    # Failed local writes are replayed from the durable ``.pending`` spool.
    # A short interval heals transient disk/config races without adding work
    # to the inbound message handler.
    _MESSAGE_CACHE_PENDING_RETRY_INTERVAL_SECONDS = 30
    # Image/emoji archival must follow the same lossless policy as the text
    # journal.  A bounded queue used to drop the newest media during bursts,
    # leaving a message row without its image even though the text was kept.
    _MESSAGE_IMAGE_QUEUE_MAXSIZE = 0
    _MESSAGE_IMAGE_QUEUE_WARN_SIZE = 4000
    _MESSAGE_IMAGE_WORKERS = 3
    _RECENT_MESSAGE_RECALL_LIMIT = 50
    _RECENT_MESSAGE_RECALL_WINDOW_SECONDS = 110
    # CMD events are append-only diagnostics.  A busy group can write many
    # events in one second, so wake the portal once per short burst instead
    # of scheduling an exchange for every line.  Configuration and auth
    # changes continue to use ``_request_portal_sync`` immediately.
    _PORTAL_CONSOLE_SYNC_DEBOUNCE_SECONDS = 3.0
    # The immediate endpoint sends only the just-written batch.  A short
    # reconciliation window also replays retained local history in 100-row
    # chunks, so a brief portal outage cannot leave the webpage with only the
    # first message while Windows already counts later messages.
    _MESSAGE_CACHE_RECONCILE_INTERVAL_SECONDS = 30.0

    # These defaults are also exposed in _conf_schema.json.  Keeping them in
    # one place prevents a settings-page change from silently changing the
    # fallback text used by the event gate.
    _EXPIRED_AUTH_PROMPT_TEXT = "授权已过期，请联系管理员购买或续费授权。"
    _POWER_ON_PROMPT_TEXT = "群管尚未开机，请先发送 /开机。"
    _POWER_ON_SUCCESS_TEXT = "✅️ 已开机\n群管功能已启用，可以正常使用所有群管命令"
    _POWER_OFF_SUCCESS_TEXT = "❌️ 已关机\n群管功能已禁用，所有群管命令将不再响应"
    _POWER_OFF_ALREADY_TEXT = "群管已关机，无需重复操作。"
    _CONSOLE_SEND_LOGGED_EXTRA = "_joker_console_send_logged"
    _CONSOLE_PENDING_SEND_EXTRA = "_joker_console_pending_send"
    _CONSOLE_SEND_PRELOGGED_EXTRA = "_joker_console_send_prelogged"

    @staticmethod
    def _bounded_int(value: object, default: int, minimum: int, maximum: int) -> int:
        """读取插件整数设置并限制安全范围。"""
        try:
            return max(minimum, min(int(value), maximum))
        except (TypeError, ValueError):
            return default

    def _load_reply_runtime_settings(self, get_nested) -> None:
        """统一加载自动回复设置，供启动和设置热重载共用。"""
        self.qqadmin_enable_reply = bool(get_nested(
            "qqadmin", "reply", "enable_reply", default=False
        ))
        self.qqadmin_default_reply_cooldown = self._bounded_int(
            get_nested("qqadmin", "reply", "default_reply_cooldown", default=0),
            0,
            0,
            86400,
        )
        self.qqadmin_enable_keyword_reply = bool(get_nested(
            "qqadmin", "reply", "enable_keyword_reply", default=True
        ))
        self.qqadmin_enable_exact_match = bool(get_nested(
            "qqadmin", "reply", "enable_exact_match", default=False
        ))
        self.qqadmin_max_reply_length = self._bounded_int(
            get_nested("qqadmin", "reply", "max_reply_length", default=500),
            500,
            1,
            10000,
        )
        self.qqadmin_cache_reply_images = bool(get_nested(
            "qqadmin", "reply", "cache_reply_images", default=True
        ))
        self.qqadmin_reply_image_max_mb = self._bounded_int(
            get_nested("qqadmin", "reply", "reply_image_max_mb", default=20),
            20,
            1,
            100,
        )
        self.qqadmin_reply_image_download_concurrency = self._bounded_int(
            get_nested("qqadmin", "reply", "reply_image_download_concurrency", default=4),
            4,
            1,
            8,
        )
        self.qqadmin_reply_image_retry_interval = self._bounded_int(
            get_nested("qqadmin", "reply", "reply_image_retry_interval", default=30),
            30,
            30,
            86400,
        )

