    async def _query_online(self, event: AstrMessageEvent) -> None:
        access_error = self._get_scum_group_access_error(event)
        if access_error:
            yield self._yield_scum_group_access_error(event, access_error)
            return
        if not self._is_authorized(event):
            yield self._yield_plain(event,"该群组未授权，请先激活卡密。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            yield self._yield_plain(event,"SCUM 在线查询仅支持在群聊中使用。")
            return
        server_id = self._get_scum_bound_server_id(event)
        if not server_id:
            yield self._yield_plain(event,"该群组尚未绑定服务器ID，请先使用 /绑定id <服务器ID> 绑定服务器。")
            return
        result = await self._query_scum_via_linux(event, "detail", server_id)
        yield self._yield_plain(event,result)

    async def _query_scum_via_linux(
        self,
        event: AstrMessageEvent,
        operation: str,
        argument: object = "",
    ) -> str:
        """Run all SCUM queries through the configured Linux portal relay."""
        remote_mode = bool(getattr(self, "web_sync_enabled", False))
        client = getattr(self, "_portal_sync_client", None)
        if not remote_mode:
            return "SCUM 查询中转未启用，请检查网页同步配置。"
        if client is None:
            return "Linux SCUM 查询服务未初始化，请检查网页同步配置。"
        if not bool(getattr(client, "configured", False)):
            return "Linux SCUM 查询服务未配置，请先在网页后台完成同步配置。"
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            return "SCUM 查询中转仅支持群聊指令。"
        query_method = getattr(client, "query_scum", None)
        if not callable(query_method):
            return "SCUM 查询组件未更新，请更新插件并重载。"
        try:
            response = await query_method(group_id, operation, argument)
        except Exception as exc:
            code = str(getattr(exc, "code", "") or "scum_query_failed")
            messages = {
                "scum_query_failed": "Linux 查询 SCUM 服务失败，请检查网页服务器网络和依赖。",
                "windows_executor_offline": "网页端 SCUM 查询服务不可用，请检查 Linux 网页服务。",
                "sync_authentication": "网页同步授权失败，请核对同步令牌和客户端绑定。",
                "card_pepper_mismatch": "网页与 Windows 的 Card Pepper 不一致，请重新同步配置。",
                "group_not_synced": "网页还没有收到本群最新配置，请等待 Windows 同步完成后再查询。",
            }
            logger.warning(
                "Linux SCUM query failed operation=%s code=%s detail=%s",
                operation,
                code,
                str(getattr(exc, "detail", "") or "-")[:240],
            )
            detail = str(getattr(exc, "detail", "") or "").strip()
            # Do not expose exception text or internal error codes in group
            # replies.  The full detail is already written to the Windows log.
            return messages.get(code, "Linux 查询 SCUM 失败，请稍后重试。")
        if not isinstance(response, dict):
            return "Linux 查询 SCUM 返回格式无效，请稍后重试。"
        result = response.get("result")
        return str(result or "Linux 查询 SCUM 未返回结果。")

    async def _query_keyword(self, event: AstrMessageEvent, keyword: str = "") -> None:
        access_error = self._get_scum_group_access_error(event)
        if access_error:
            yield self._yield_scum_group_access_error(event, access_error)
            return
        if not self._is_authorized(event):
            yield self._yield_plain(event,"该群组未授权，请先激活卡密。")
            return
        if not keyword or keyword.strip() == "":
            yield self._yield_plain(
                event,
                f"请输入服务器关键词，例如：/{self._get_scum_group_config(event)['keyword_command']} 建家",
            )
            return
        result = await self._query_scum_via_linux(event, "search", keyword.strip())
        yield self._yield_plain(event,result)

