    @filter.command("设置过期回复间隔")
    async def set_expired_auth_reply_interval(self, event: AstrMessageEvent, seconds: str = "") -> None:
        """Set the per-group throttle for retained expired authorization prompts."""
        if not self._is_slash_prefix_allowed(event):
            event.stop_event()
            return
        if not self._is_owner(event):
            event.stop_event()
            yield self._yield_plain(event, "只有主人才能设置过期回复间隔。")
            return

        seconds = (seconds or "").strip()
        if not seconds:
            current = int(getattr(self, "auth_expired_command_reply_interval", 3600))
            current_text = "每次指令都回复" if current == 0 else f"{current} 秒"
            yield self._yield_plain(
                event,
                f"当前授权过期回复间隔：{current_text}\n用法：/设置过期回复间隔 <秒>（0=不限制）",
            )
            return
        try:
            interval = int(seconds)
        except ValueError:
            yield self._yield_plain(event, "回复间隔必须是非负整数秒。")
            return
        if interval < 0:
            yield self._yield_plain(event, "回复间隔不能小于 0。")
            return

        auth_config = self.config.setdefault("auth", {})
        if isinstance(auth_config, dict) and isinstance(auth_config.get("items"), dict):
            auth_config = auth_config["items"]
        if not isinstance(auth_config, dict):
            yield self._yield_plain(event, "保存失败：授权配置格式无效。")
            return

        old_interval = getattr(self, "auth_expired_command_reply_interval", 3600)
        missing = object()
        old_config_value = auth_config.get("auth_expired_command_reply_interval", missing)
        self.auth_expired_command_reply_interval = interval
        auth_config["auth_expired_command_reply_interval"] = interval

        try:
            from astrbot.core.utils.astrbot_path import get_astrbot_data_path

            config_path = os.path.join(
                get_astrbot_data_path(), "config", "astrbot_plugin_joker_config.json"
            )
            self._write_json_atomic(config_path, self.config)
        except Exception as exc:
            self.auth_expired_command_reply_interval = old_interval
            if old_config_value is missing:
                auth_config.pop("auth_expired_command_reply_interval", None)
            else:
                auth_config["auth_expired_command_reply_interval"] = old_config_value
            logger.error(f"保存授权过期回复间隔失败: {exc}")
            logger.warning("保存授权过期回复间隔失败: %s", exc, exc_info=True)
            yield self._yield_plain(event, "保存失败，请重试。")
            return

        interval_text = "每次指令都回复" if interval == 0 else f"{interval} 秒"
        yield self._yield_plain(event, f"授权过期回复间隔已设置为：{interval_text}")

    @filter.command("清理过期授权", alias={"删除过期授权"})
    async def cleanup_expired_auth(self, event: AstrMessageEvent, days: str = "") -> None:
        """手动清理已过期的授权记录
        用法: /清理过期授权 [天数]
        - 不填天数：删除所有已过期群组
        - 填天数：删除过期超过该天数的群组
        """
        if not self._is_slash_prefix_allowed(event) or not self.enable_auth:
            event.stop_event()
            return
        if not self._is_owner(event):
            event.stop_event()
            yield self._yield_plain(event, "只有主人才能清理过期授权。")
            return
        # 解析 days 参数
        days_int = 0
        if days and days.strip():
            try:
                days_int = int(days.strip())
                if days_int < 0:
                    yield self._yield_plain(event, "天数不能为负数。")
                    return
            except ValueError:
                yield self._yield_plain(event, "天数必须是整数。")
                return

        try:
            cleanup = self._cleanup_expired_authorizations(days_int)
            deleted = cleanup["deleted"]
            kept = cleanup["kept"]
            failed = cleanup["failed"]

            if not deleted:
                failure_hint = (
                    f"\n有 {len(failed)} 个群的配置删除失败，已保留授权记录等待重试。"
                    if failed else ""
                )
                if days_int > 0:
                    yield self._yield_plain(event, f"未发现过期超过 {days_int} 天且可清理的群组\n当前保留授权 {len(kept)} 个{failure_hint}")
                else:
                    yield self._yield_plain(event, f"未发现可清理的已过期群组\n当前保留授权 {len(kept)} 个{failure_hint}")
                return

            # 构建删除详情
            lines = [f"已清理 {len(deleted)} 个过期群组："]
            for gid, info in deleted.items():
                expire = int(info.get("expire", 0))
                expire_str = time.strftime("%Y-%m-%d %H:%M", time.localtime(expire)) if expire > 0 else "未知"
                lines.append(f"  群 {gid}（过期于 {expire_str}）")
            lines.append(f"\n保留授权 {len(kept)} 个")
            if failed:
                lines.append(f"另有 {len(failed)} 个群配置删除失败，授权记录已保留等待重试")
            yield self._yield_plain(event, "\n".join(lines))
        except Exception as e:
            logger.error(f"清理过期授权失败: {e}", exc_info=True)
            logger.warning("清理过期授权失败: %s", e, exc_info=True)
            yield self._yield_plain(event, "清理失败，请重试。")

    @filter.command("查看过期授权", alias={"过期授权列表"})
    async def view_expired_auth(self, event: AstrMessageEvent, days: str = "") -> None:
        """查看已过期的授权记录（不删除）
        用法: /查看过期授权 [天数]
        - 不填天数：查看所有已过期群组
        - 填天数：查看过期超过该天数的群组
        """
        if not self._is_slash_prefix_allowed(event) or not self.enable_auth:
            event.stop_event()
            return
        if not self._is_owner(event):
            event.stop_event()
            yield self._yield_plain(event, "只有主人才能查看过期授权。")
            return
        days_int = 0
        if days and days.strip():
            try:
                days_int = int(days.strip())
                if days_int < 0:
                    yield self._yield_plain(event, "天数不能是负数")
                    return
            except ValueError:
                yield self._yield_plain(event, "天数得是整数")
                return

        try:
            expired = list_expired_authorizations(days_int)
            if not expired:
                if days_int > 0:
                    yield self._yield_plain(event, f"没有过期超过{days_int}天的群")
                else:
                    yield self._yield_plain(event, "没有过期的群")
                return

            lines = [f"{len(expired)} 个过期群："]
            now = int(time.time())
            for gid, info in expired.items():
                expire = int(info.get("expire", 0))
                expired_days = (now - expire) // 86400
                expire_str = time.strftime("%Y-%m-%d %H:%M", time.localtime(expire)) if expire > 0 else "未知"
                lines.append(f"  群 {gid}（过期{expired_days}天，{expire_str}）")
            lines.append(f"\n用 /清理过期授权 删掉")
            yield self._yield_plain(event, "\n".join(lines))
        except Exception as e:
            logger.error(f"查看过期授权失败: {e}", exc_info=True)
            logger.warning("查看授权失败: %s", e, exc_info=True)
            yield self._yield_plain(event, "查看失败，请重试。")

