    async def _activate_license(self, event: AstrMessageEvent, key: str = "") -> None:
        if not key or not key.strip():
            yield self._yield_plain(event,"请提供卡密\n用法：/激活卡密 <卡密>")
            return
        key = key.strip().upper()
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            yield self._yield_plain(event,"请在群聊中使用")
            return
        auth_key = self.auth_key
        if not auth_key:
            yield self._yield_plain(event,"系统未配置授权密钥")
            return
        
        # Support both regular cards (created without a group binding) and
        # cards deliberately generated for this exact group.  The verifier
        # still falls back to the regular-card signature for compatibility.
        result = verify_license_key(key, auth_key, group_id)
        if not result["valid"]:
            yield self._yield_plain(event,f"{result['error']}")
            return
        
        user_id = self._get_sender_id_from_event(event)
        activation = activate_unused_license_key(
            key, group_id, user_id, result["days"]
        )
        activation_status = activation.get("status")
        if activation_status == "used":
            yield self._yield_plain(event, "该卡密已被使用")
            return
        if activation_status == "deleted":
            yield self._yield_plain(event, "该卡密不存在、已被删除或已撤销，无法激活")
            return
        if activation_status == "already_permanent":
            yield self._yield_plain(event, "该群已是永久授权，无需激活")
            return
        if activation_status in {"invalid", "data_invalid", "save_failed"}:
            logger.error("卡密激活未提交: status=%s group=%s", activation_status, group_id)
            yield self._yield_plain(event, "卡密激活未保存，请稍后重试或联系管理员")
            return

        now = int(activation["activated_at"])
        days = int(activation["days"])
        new_expire = int(activation["expire"])
        activated_time_str = time.strftime('%Y-%m-%d %H:%M', time.localtime(now))
        is_permanent = days == -1
        if new_expire == -1:
            expire_time_str = "永不过期"
        else:
            expire_time_str = time.strftime('%Y-%m-%d %H:%M', time.localtime(new_expire))

        if activation_status == "upgraded":
            activation_message = (
                f"已升级为永久授权\n"
                f"群号：{group_id}\n"
                f"激活：{activated_time_str}\n"
                f"到期：永不过期\n"
                f"✅️ 已自动开机，可正常使用"
            )
        elif activation_status == "extended":
            activation_message = (
                f"授权已延长\n"
                f"群号：{group_id}\n"
                f"增加：{days} 天\n"
                f"激活：{activated_time_str}\n"
                f"到期：{expire_time_str}"
            )
        elif activation_status == "reactivated":
            activation_message = (
                f"已重新激活\n"
                f"群号：{group_id}\n"
                f"天数：{days} 天\n"
                f"激活：{activated_time_str}\n"
                f"到期：{expire_time_str}\n"
                f"✅️ 已自动开机，可正常使用"
            )
        elif is_permanent:
            activation_message = (
                f"激活成功（永久授权）\n"
                f"群号：{group_id}\n"
                f"激活：{activated_time_str}\n"
                f"到期：永不过期\n"
                f"✅️ 已自动开机，可正常使用"
            )
        else:
            activation_message = (
                f"激活成功\n"
                f"群号：{group_id}\n"
                f"天数：{days} 天\n"
                f"激活：{activated_time_str}\n"
                f"到期：{expire_time_str}\n"
                f"✅️ 已自动开机，可正常使用"
            )

        # 激活时自动开机
        from .qqadmin.group_config import update_group_data
        def _auto_power_on(features):
            if features is None:
                features = {}
            features["power_status"] = "on"
            return features
        update_group_data(group_id, "features", _auto_power_on)
        self._request_portal_sync()

        # The outbound gate permits the confirmation only after both states commit.
        yield self._yield_plain(event, activation_message)

        # 激活成功后发送功能引导
        async for result in self._send_activation_help(event):
            yield result

    async def _activate_game_license(self, event: AstrMessageEvent, key: str = "") -> None:
        """Validate the issued game card and then verify the selected plugin WS."""
        if not key or not str(key).strip():
            yield self._yield_plain(event, "请提供游戏卡密\n用法：/激活游戏卡密 <卡密>")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            yield self._yield_plain(event, "请在群聊中使用")
            return
        normalized_key = str(key).strip().upper()
        if not is_supported_game_license_key(normalized_key):
            yield self._yield_plain(event, "游戏卡密格式无效，请联系主人获取正确卡密")
            return
        info = get_game_authorization_info(group_id)
        stored_key = str(info.get("key", "") or "").strip().upper()
        if not stored_key or stored_key != normalized_key:
            yield self._yield_plain(event, "游戏卡密与本群不匹配，请联系主人核对群号")
            return
        if str(info.get("state", "missing")) != "active":
            yield self._yield_plain(event, "游戏卡密已过期，请联系主人续期")
            return

        result = await self._game_websocket_connection_tester(group_id=group_id)
        if isinstance(result, dict) and result.get("success"):
            profile_id = str(result.get("profile_id", "") or "全局配置")
            yield self._yield_plain(
                event,
                f"游戏卡密验证成功\nWebSocket 已连通：{profile_id}\n现在可以使用游戏指令。",
            )
            return
        code = str(result.get("code", "game_connection_failed")) if isinstance(result, dict) else "game_connection_failed"
        message = str(result.get("message", "未收到插件 WebSocket 的确认")) if isinstance(result, dict) else "未收到插件 WebSocket 的确认"
        yield self._yield_plain(
            event,
            f"游戏卡密有效，但 WebSocket 未连通\n原因：{message[:180]}\n请联系管理员检查后台对应服务器连接配置（{code}）。",
        )

    async def _send_activation_help(self, event: AstrMessageEvent) -> None:
        """激活成功后发送功能使用引导"""
        group_id = self._get_group_id_from_event(event)
        try:
            sections = self._group_help_sections(event, group_id)
        except Exception:
            sections = []
        help_text = self._format_compact_feature_menu(sections)
        yield self._yield_plain(event,help_text)


    def _game_auth_target_and_days(
        self, event: AstrMessageEvent, first: str = "", second: str = ""
    ) -> tuple[str, str]:
        """Resolve group/day arguments for game-license owner commands."""
        current_group = self._get_group_id_from_event(event)
        first = str(first or "").strip()
        second = str(second or "").strip()
        if current_group and current_group != "None" and (
            not first or not first.isdigit() or len(first) < 5
        ):
            return str(current_group), first or second
        return first, second

    @staticmethod
    def _format_game_authorization(info: dict, group_id: str) -> str:
        state = str(info.get("status", info.get("state", "missing")) or "missing")
        expire = int(info.get("expire", 0) or 0)
        if expire == -1:
            expire_text = "永不过期"
        elif expire > 0:
            expire_text = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(expire))
        else:
            expire_text = "无记录"
        labels = {
            "active": "有效",
            "expired": "已过期（保留 7 天）",
            "issued": "已生成",
            "extended": "已续期",
            "existing": "已存在",
            "missing": "未生成",
            "already_permanent": "永久授权",
        }
        return f"游戏授权：{labels.get(state, state)}\n群：{group_id}\n到期：{expire_text}"

    async def _generate_game_keys(
        self, event: AstrMessageEvent, first: str = "", second: str = ""
    ) -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event, "这命令只有主人能用")
            return
        group_id, days_text = self._game_auth_target_and_days(event, first, second)
        if not group_id or not group_id.isdigit() or not 5 <= len(group_id) <= 20:
            yield self._yield_plain(event, "请提供群号；群内可直接用 /生成游戏卡密 <天数>")
            return
        days_text = days_text.strip()
        if days_text == "-1":
            days = -1
        elif days_text.isdigit():
            days = int(days_text)
        else:
            days = int(self.default_auth_days)
        if days == 0 or days < -1:
            yield self._yield_plain(event, "天数需大于 0，-1 为永久")
            return
        result = issue_game_authorization(
            group_id, days, str(self.auth_key or ""), self._get_sender_id_from_event(event)
        )
        status = result.get("status")
        if status == "missing_auth_key":
            yield self._yield_plain(event, "系统未配置授权密钥，无法生成游戏卡密")
            return
        if status == "existing":
            yield self._yield_plain(
                event,
                self._format_game_authorization(result, group_id)
                + "\n卡密只生成一次；请使用 /添加游戏授权时间 续期。",
            )
            return
        if status != "issued":
            yield self._yield_plain(event, "游戏授权生成失败，请稍后重试")
            return
        card = str(result.get("key", ""))
        message = self._format_game_authorization(result, group_id) + f"\n卡密：{card}"
        sender_id = self._get_sender_id_from_event(event)
        if await self._send_private_text(event, sender_id, message):
            yield self._yield_plain(event, "游戏卡密已私聊发送；后续只能添加授权时间")
        else:
            yield self._yield_plain(event, "游戏卡密已生成但私聊发送失败，请开启机器人私聊后重试")
        self._request_portal_sync()

    async def _extend_game_authorization(
        self, event: AstrMessageEvent, first: str = "", second: str = ""
    ) -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event, "这命令只有主人能用")
            return
        group_id, days_text = self._game_auth_target_and_days(event, first, second)
        if not group_id or not group_id.isdigit() or not 5 <= len(group_id) <= 20:
            yield self._yield_plain(event, "请提供群号；群内可直接用 /添加游戏授权时间 <天数>")
            return
        if not days_text.strip().isdigit() or int(days_text) <= 0:
            yield self._yield_plain(event, "用法：/添加游戏授权时间 <天数>")
            return
        result = add_game_authorization_time(group_id, int(days_text))
        if result.get("status") == "missing":
            yield self._yield_plain(event, "该群尚未生成游戏卡密，请先生成一次")
            return
        if result.get("status") == "already_permanent":
            yield self._yield_plain(event, "该群游戏授权已是永久，无需续期")
            return
        if result.get("status") != "extended":
            yield self._yield_plain(event, "游戏授权续期失败，请稍后重试")
            return
        yield self._yield_plain(event, self._format_game_authorization(result, group_id))
        self._request_portal_sync()

    async def _query_game_authorization(self, event: AstrMessageEvent) -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event, "这命令只有主人能用")
            return
        rows = list_game_authorizations()
        if not rows:
            yield self._yield_plain(event, "暂无游戏授权")
            return
        lines = ["游戏授权列表"]
        for group_id, info in sorted(rows.items()):
            lines.append(self._format_game_authorization(info, group_id))
        yield self._yield_plain(event, "\n\n".join(lines))

    async def _generate_keys(self, event: AstrMessageEvent, days: str = "", count: str = "1") -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event,"这命令只有主人能用")
            return
        days_str = days.strip() if days else ""
        if days_str == "-1":
            days_int = -1
        elif days_str.isdigit():
            days_int = int(days_str)
        else:
            yield self._yield_plain(event,"请提供有效天数\n用法：/生成卡密 <天数> [数量]（-1为永久）")
            return
        if days_int == 0 or days_int < -1:
            yield self._yield_plain(event, "天数需大于0，-1为永久")
            return
        try:
            count_int = int(count.strip()) if count and count.strip().isdigit() else 1
        except ValueError:
            count_int = 1
        if count_int < 1:
            count_int = 1
        if count_int > 100:
            yield self._yield_plain(event,"单次最多生成 100 个")
            return
        auth_key = self.auth_key
        if not auth_key:
            yield self._yield_plain(event,"系统未配置授权密钥")
            return
        group_id = ""
        auth_data = load_auth_data()
        existing_keys = set(auth_data.get("unused_keys", [])) | set(
            auth_data.get("used_keys", {}).keys()
        )
        keys = []
        index = 0
        while len(keys) < count_int and index < count_int * 200:
            key = generate_license_key(auth_key, days_int, group_id, index)
            index += 1
            if key in existing_keys or key in keys:
                continue
            keys.append(key)
            existing_keys.add(key)
        if len(keys) != count_int:
            yield self._yield_plain(event, "卡密生成冲突，请稍后重试")
            return
        auth_data["unused_keys"].extend(keys)
        save_auth_data(auth_data)
        keys_str = "\n".join(keys)
        days_label = "永久"if days_int == -1 else f"{days_int} 天"
        result = f"已生成 {count_int} 个 {days_label}卡密：\n\n{keys_str}\n\n已保存到未使用列表"
        sender_id = self._get_sender_id_from_event(event)
        if await self._send_private_text(event, sender_id, result):
            yield self._yield_plain(event,"卡密已私聊发送给您，请查收。")
        elif callable(getattr(event, "is_private_chat", None)) and event.is_private_chat():
            # A private command is already private, so returning the cards is
            # safe when the platform cannot create a second private session.
            yield self._yield_plain(event, result)
        else:
            logger.error("发送卡密私聊失败：未找到可用的好友消息会话")
            yield self._yield_plain(event, "卡密已生成但私聊发送失败，请先开启机器人好友消息后重试。")

    async def _query_license_keys(self, event: AstrMessageEvent) -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event,"这命令只有主人能用")
            return
        auth_data = load_auth_data()
        unused_keys = auth_data.get("unused_keys", [])
        used_keys = auth_data.get("used_keys", {})
        result_lines = ["卡密列表"]
        if unused_keys:
            result_lines.append(f"\n未使用（{len(unused_keys)} 个）：")
            for key in unused_keys[:20]:
                result_lines.append(f"  {key}")
            if len(unused_keys) > 20:
                result_lines.append(f"  ...还有 {len(unused_keys) - 20} 个")
        if used_keys:
            result_lines.append(f"\n已使用（{len(used_keys)} 个）：")
            for key, info in list(used_keys.items())[:20]:
                activated_at = info.get("activated_at", 0)
                group_id = info.get("group_id", "未知")
                user_id = info.get("user_id", "未知")
                activated_time = time.strftime('%Y-%m-%d %H:%M', time.localtime(activated_at)) if activated_at > 0 else "未知"
                actual_group_info = auth_data.get("groups", {}).get(group_id, {})
                actual_expire = int(actual_group_info.get("expire", 0)) if actual_group_info else 0
                if actual_expire == -1:
                    expire_time = "永不过期"
                    expire_status = ""
                elif actual_expire > 0:
                    expire_time = time.strftime('%Y-%m-%d %H:%M', time.localtime(actual_expire))
                    is_expired = actual_expire < int(time.time())
                    expire_status = "（已过期）"if is_expired else ""
                else:
                    expire_time = "未知"
                    expire_status = ""
                result_lines.append(f"  {key}")
                result_lines.append(f"    群：{group_id}  人：{user_id}")
                result_lines.append(f"    激活：{activated_time}  到期：{expire_time}{expire_status}")
            if len(used_keys) > 20:
                result_lines.append(f"  ...还有 {len(used_keys) - 20} 个")
        if not unused_keys and not used_keys:
            result_lines.append("\n暂无卡密")
        yield self._yield_plain(event,"\n".join(result_lines))

    async def _delete_all_keys(self, event: AstrMessageEvent) -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event,"这命令只有主人能用")
            return
        unused_count = len(get_unused_keys())
        used_count = len(get_used_keys())
        revoked_groups = delete_all_keys()
        self._request_portal_sync()
        result = f"已删除所有卡密\n未使用：{unused_count} 个\n已使用：{used_count} 个"
        if revoked_groups:
            result += f"\n已撤销 {len(revoked_groups)} 个由卡密授权的群：{'、'.join(revoked_groups)}"
        yield self._yield_plain(event, result)

    async def _delete_used_keys(self, event: AstrMessageEvent) -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event,"这命令只有主人能用")
            return
        used_count = len(get_used_keys())
        revoked_groups = delete_used_keys()
        self._request_portal_sync()
        result = f"已删除所有已使用卡密，共 {used_count} 个"
        if revoked_groups:
            result += f"\n已撤销 {len(revoked_groups)} 个由卡密授权的群：{'、'.join(revoked_groups)}"
        yield self._yield_plain(event, result)

    async def _send_private_text(
        self,
        event: AstrMessageEvent,
        user_id: str,
        text: str,
    ) -> bool:
        """Send text to a user through AstrBot's platform-aware session API."""
        normalized_user_id = str(user_id or "").strip()
        normalized_text = str(text or "").strip()
        if not normalized_user_id or not normalized_text:
            logger.warning(
                "私聊提示未发送：收件人或消息为空 user=%s",
                normalized_user_id or "-",
            )
            return False

        def send_succeeded(result: object) -> bool:
            # AstrBot adapters usually return ``None`` on success, while
            # OneBot-compatible adapters may return a status/retcode object.
            # Treat explicit API failures as unavailable so the caller can
            # use the group fallback instead of silently losing the prompt.
            if result is False:
                return False
            if isinstance(result, dict):
                status = str(result.get("status", "") or "").strip().lower()
                if status in {"failed", "error"}:
                    return False
                retcode = result.get("retcode")
                if retcode not in (None, 0, "0"):
                    return False
            return True

        def report_private_send() -> None:
            try:
                print_private_action("发送", normalized_user_id, message=normalized_text)
            except Exception:
                pass

        # Keep compatibility with deployments that provide this convenience
        # method, but use the public session API used by current AstrBot.
        legacy_sender = getattr(self.context, "send_private_message", None)
        if callable(legacy_sender):
            try:
                result = legacy_sender(normalized_user_id, normalized_text)
                if inspect.isawaitable(result):
                    result = await result
                if send_succeeded(result):
                    report_private_send()
                    return True
            except Exception as exc:
                logger.debug("兼容私聊接口发送失败：%s", type(exc).__name__)

        sender = getattr(event, "get_platform_id", None)
        platform_id = sender() if callable(sender) else ""
        if not platform_id:
            platform_meta = getattr(event, "platform_meta", None)
            platform_id = getattr(platform_meta, "id", "")
        # Prefer the connected OneBot client as a final direct path. Some
        # AstrBot versions reject MessageSession(FRIEND_MESSAGE) even though
        # OneBot can still deliver a private message through send_private_msg.
        try:
            client = (
                getattr(event, "bot", None)
                if callable(getattr(getattr(event, "bot", None), "call_action", None))
                else None
            )
            if client is None:
                platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                client = platform.get_client() if platform else None
            call_action = getattr(client, "call_action", None)
            if callable(call_action):
                result = await call_action(
                    action="send_private_msg",
                    user_id=int(normalized_user_id),
                    message=normalized_text,
                )
                if send_succeeded(result):
                    logger.debug("OneBot 直发私聊成功 user=%s", normalized_user_id)
                    report_private_send()
                    return True
        except Exception as exc:
            logger.debug(
                "OneBot 直发私聊失败 user=%s error_type=%s",
                normalized_user_id,
                type(exc).__name__,
            )

        if not platform_id or not callable(getattr(self.context, "send_message", None)):
            return False
        try:
            from astrbot.core.message.components import Plain
            from astrbot.core.message.message_event_result import MessageChain
            from astrbot.core.platform.message_session import MessageSession
            from astrbot.core.platform.message_type import MessageType

            session = MessageSession(
                str(platform_id),
                MessageType.FRIEND_MESSAGE,
                normalized_user_id,
            )
            result = self.context.send_message(
                session,
                MessageChain([Plain(normalized_text)]),
            )
            if inspect.isawaitable(result):
                result = await result
            succeeded = send_succeeded(result)
            if succeeded:
                report_private_send()
            return succeeded
        except Exception as exc:
            logger.warning(
                "私聊消息发送失败 platform=%s user=%s error_type=%s",
                str(platform_id),
                normalized_user_id,
                type(exc).__name__,
            )
            return False

    async def _prompt_steamid_submission(
        self,
        event: AstrMessageEvent,
        group_id: str,
        user_id: str,
        timeout: int = 300,
        steam_id: str = "",
    ) -> bool:
        """Prompt either admission verification or ordinary binding privately."""
        minutes = max(1, int(timeout) // 60)
        try:
            from .qqadmin.audit import get_pending_verification

            pending = get_pending_verification(str(group_id), str(user_id)) or {}
        except Exception:
            pending = {}
        admission = bool(
            pending.get("steamid_stage", False)
            or str(pending.get("approval_mode", "") or "") == "steamid"
        )

        def mark_admission_prompt_sent() -> None:
            if not admission:
                return
            sent_at = int(time.time())
            from .qqadmin.group_config import update_group_data

            update_group_data(
                group_id,
                "audit_pending",
                lambda records: [
                    dict(
                        record,
                        steamid_prompt_sent=True,
                        steamid_prompt_sent_at=sent_at,
                        prompt_sent_at=sent_at,
                    )
                    if str(record.get("user_id", "")) == str(user_id)
                    else record
                    for record in (records or [])
                ],
            )

        prompt_key = (
            f"{str(group_id or '').strip()}:{str(user_id or '').strip()}:"
            f"{'admission' if admission else 'binding'}"
        )
        now = time.time()
        previous = float(self._steamid_prompt_claims.get(prompt_key, 0) or 0)
        if previous and now - previous < 600:
            mark_admission_prompt_sent()
            logger.debug(
                "SteamID 私聊提示已发送，跳过重复提示 group=%s user=%s flow=%s",
                group_id,
                user_id,
                "admission" if admission else "binding",
            )
            return True
        self._steamid_prompt_claims[prompt_key] = now
        if len(self._steamid_prompt_claims) > 512:
            cutoff = now - 600
            self._steamid_prompt_claims = {
                key: sent_at
                for key, sent_at in self._steamid_prompt_claims.items()
                if float(sent_at or 0) >= cutoff
            }
        if admission:
            private_text = (
                "入群验证\n"
                f"你已进入群 {group_id}，请在 {minutes} 分钟内私聊机器人发送你的 17 位 SteamID64。\n"
                "这里只用于核对入群资格；请只发送 17 位数字，不要发送命令，也不要发到群里。"
            )
        else:
            submitted = str(steam_id or "").strip()
            example_id = submitted if re.fullmatch(r"[0-9]{17}", submitted) else "<17位SteamID64>"
            private_text = (
                "SteamID 绑定\n"
                "群内不允许直接发送 SteamID。请私聊机器人发送完整命令：\n"
                f"/绑定SteamID {group_id} {example_id}"
            )
        if await self._send_private_text(event, user_id, private_text):
            mark_admission_prompt_sent()
            logger.info(
                "SteamID 私聊提示发送成功 group=%s user=%s",
                group_id,
                user_id,
            )
            return True

        self._steamid_prompt_claims.pop(prompt_key, None)
        logger.warning(
            "SteamID 私聊提示发送失败，未在群内公开提示 group=%s user=%s",
            group_id,
            user_id,
        )
        return False

    def _cancel_undelivered_verification(
        self, group_id: str, user_id: str, mode: str, reason: str
    ) -> None:
        """Cancel an audit whose prompt could not be delivered.

        The user never received a question in this case. Remove the pending
        challenge so a failed delivery cannot later demand a second answer or
        turn into an automatic kick; this method performs no QQ member action.
        """
        group_key = str(group_id or "").strip()
        user_key = str(user_id or "").strip()
        if group_key and user_key:
            try:
                from .qqadmin.audit import (
                    get_pending_verification,
                    remove_pending_request,
                    remove_challenge,
                )

                pending = get_pending_verification(group_key, user_key) or {}
                remove_pending_request(group_key, user_key)
                challenge_id = pending.get("challenge_id")
                if challenge_id:
                    remove_challenge(group_key, challenge_id)
                self._update_invite_status_if_enabled(group_key, user_key, "joined")
            except Exception as exc:
                logger.debug(
                    "清理未投递验证记录失败 group=%s user=%s error=%s",
                    group_key,
                    user_key,
                    type(exc).__name__,
                )
            suppressed = getattr(self, "_undelivered_verification_welcome", None)
            if not isinstance(suppressed, dict):
                suppressed = {}
                self._undelivered_verification_welcome = suppressed
            now = time.monotonic()
            for key, created_at in list(suppressed.items()):
                if now - float(created_at or 0) > 900:
                    suppressed.pop(key, None)
            suppressed[f"{group_key}:{user_key}"] = now
        logger.warning(
            "验证提示投递失败，保持审核记录且未踢人未欢迎 group=%s user=%s mode=%s reason=%s",
            group_id,
            user_id,
            mode,
            reason,
        )

    def _consume_undelivered_verification_welcome_suppression(
        self, group_id: str, user_id: str
    ) -> bool:
        suppressed = getattr(self, "_undelivered_verification_welcome", None)
        if not isinstance(suppressed, dict):
            return False
        key = f"{str(group_id or '').strip()}:{str(user_id or '').strip()}"
        created_at = suppressed.pop(key, None)
        if created_at is None:
            return False
        return time.monotonic() - float(created_at or 0) <= 900

    async def _deliver_group_portal_card(
        self,
        event: AstrMessageEvent,
        group_id: str,
        card: str,
        expire: int,
        activated_at: int = 0,
    ) -> bool:
        """Send a manually-issued group card to the owner without exposing it in chat.

        A group card proves ownership when a customer binds the group on the
        web portal.  It must not be printed in the group where the owner ran
        ``/添加授权``: every member could otherwise take the group-management
        access.  Repeating a manual authorization safely re-sends the existing
        current card when private messages were previously unavailable.
        """
        normalized_card = str(card or "").strip().upper()
        if not normalized_card.startswith("JK"):
            return False
        if expire == -1:
            expire_text = "永久授权"
        elif expire > 0:
            expire_text = time.strftime("%Y-%m-%d %H:%M", time.localtime(expire))
        else:
            expire_text = "以网页同步后的授权状态为准"
        activated_text = (
            time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(int(activated_at)))
            if int(activated_at or 0) > 0
            else "未知"
        )
        message = (
            f"群 {group_id} 授权信息\n"
            f"卡密：{normalized_card}\n"
            f"授权时间：{activated_text}\n"
            f"到期时间：{expire_text}\n"
            "续期、解绑或网页配置问题请联系机器人主人。"
        )
        sender_id = self._get_sender_id_from_event(event)
        return await self._send_private_text(event, sender_id, message)

    async def _authorize_group_with_portal_card(
        self, event: AstrMessageEvent, group_id: str, days: int, operator_id: str
    ) -> dict:
        """Grant/extend a group while keeping a usable portal card attached."""
        auth_key = str(getattr(self, "auth_key", "") or "").strip()
        if not auth_key:
            return {"status": "missing_auth_key"}
        result = authorize_group_with_card(group_id, days, auth_key, operator_id)
        if result.get("status") not in {
            "authorized",
            "extended",
            "reactivated",
            "upgraded",
            "already_permanent",
        }:
            return result
        try:
            from .qqadmin.group_config import (
                clone_global_config_to_group,
                get_group_config,
                load_group_config,
            )

            # Re-authorizing or extending a group must not reconstruct it
            # from global defaults.  The per-group JSON is the authoritative
            # record for choices such as "recall disabled" and customer-made
            # reply rules.  Only a truly new group receives the initial
            # global template.
            if load_group_config(group_id):
                get_group_config(group_id, self.config)
            else:
                clone_global_config_to_group(group_id, self.config)
        except Exception as exc:
            # The authorization and card were already written atomically.  Keep
            # them valid and let a later configuration sync repair the optional
            # initial configuration instead of falsely reporting a failed
            # authorization.
            logger.warning("群 %s 授权后的分群配置准备失败: %s", group_id, type(exc).__name__)
            result["config_clone_failed"] = True
        self._request_portal_sync()
        result["card_sent_private"] = await self._deliver_group_portal_card(
            event,
            group_id,
            str(result.get("key", "")),
            int(result.get("expire", 0) or 0),
            int(result.get("activated_at", 0) or 0),
        )
        return result

    @staticmethod
    def _format_portal_authorization_result(
        group_id: str, result: dict, *, current_group: bool = False
    ) -> str:
        """Return the compact owner-facing authorization summary."""
        expire = int(result.get("expire", 0) or 0)
        days = result.get("days", 0)
        activated_at = int(result.get("activated_at", 0) or 0)
        activated_text = (
            time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(activated_at))
            if activated_at > 0
            else "未知"
        )
        if expire == -1:
            expire_text = "永不过期"
            days_text = "永久"
        elif expire > 0:
            expire_text = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(expire))
            days_text = f"累计 {days} 天" if result.get("status") == "extended" else f"{days} 天"
        else:
            expire_text = "以本地授权记录为准"
            days_text = str(days)
        target = "本群" if current_group else f"群 {group_id}"
        lines = [
            f"✅ {target}已授权",
            f"授权时间：{activated_text}",
            f"授权时长：{days_text}",
            f"到期时间：{expire_text}",
            "卡密：已私聊发送给主人。",
            "续期、解绑或网页配置问题请联系机器人主人。",
        ]
        if not result.get("card_sent_private"):
            lines[4] = "卡密：已保存但私聊发送失败，请开启机器人私聊后重试。"
        return "\n".join(lines)

    async def _authorize_group(self, event: AstrMessageEvent, group_id: str = "", days: str = "") -> None:
        """精确授权模式：/群组授权 <群号> [天数]
        必须明确传群号，不在群里默认本群。用于主人给指定群授权。
        """
        if not self._is_owner(event):
            yield self._yield_plain(event,"这命令只有主人能用")
            return
        if not group_id or not group_id.strip():
            yield self._yield_plain(event,
                "请提供群号\n"
                "用法：/群组授权 <群号> [天数]"
            )
            return
        group_id = group_id.strip()
        if not group_id.isdigit() or not 5 <= len(group_id) <= 20:
            yield self._yield_plain(event, "群号必须是 5-20 位数字，未创建授权或卡密。")
            return
        # 解析天数，允许 -1（永不过期）
        days_str = days.strip()
        if days_str == "-1":
            days_int = -1
        elif days_str.isdigit():
            days_int = int(days_str)
        else:
            days_int = self.default_auth_days
        if days_int == 0 or days_int < -1:
            yield self._yield_plain(event, "天数需大于0，-1为永久")
            return
        operator_id = self._get_sender_id_from_event(event)
        result = await self._authorize_group_with_portal_card(
            event, group_id, days_int, operator_id
        )
        if result.get("status") in {
            "authorized", "extended", "reactivated", "upgraded", "already_permanent"
        }:
            logger.debug("群组 %s 已授权并绑定网页卡密", group_id)
            yield self._yield_plain(
                event,
                self._format_portal_authorization_result(group_id, result),
            )
            return
        if result.get("status") == "missing_auth_key":
            yield self._yield_plain(event, "系统未配置授权密钥，无法生成可用于网页登记的群专属卡密。")
        elif result.get("status") == "save_failed":
            yield self._yield_plain(event, "授权卡密保存失败，未完成授权，请稍后重试。")
        else:
            yield self._yield_plain(event, "授权失败，授权数据格式异常或卡密生成冲突，请稍后重试。")

    async def _authorize_current_group(self, event: AstrMessageEvent, days: str = "") -> None:
        """便捷授权模式：/添加授权 [天数]（默认按配置天数）
        只能在群聊中使用，授权本群。
        """
        if not self._is_owner(event):
            yield self._yield_plain(event, "这命令只有主人能用")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            yield self._yield_plain(event,
                "请在群聊中使用\n"
                "用法：/添加授权 [天数]"
            )
            return
        # 解析天数，允许 -1（永不过期）
        days_str = days.strip()
        if days_str == "-1":
            days_int = -1
        elif days_str.lstrip('-').isdigit() and not days_str.startswith('-'):
            days_int = int(days_str)
        elif days_str.startswith('-') and days_str != "-1":
            yield self._yield_plain(event,
                f"❌ 不支持负数授权\n"
                f"减少时间请用 /减少时间 {days_str.lstrip('-')}\n"
                f"用法：/添加授权 [天数]（正数或-1永久）"
            )
            return
        else:
            days_int = self.default_auth_days
        if days_int == 0 or days_int < -1:
            yield self._yield_plain(event, "天数需大于0，-1为永久")
            return
        operator_id = self._get_sender_id_from_event(event)
        result = await self._authorize_group_with_portal_card(
            event, group_id, days_int, operator_id
        )
        if result.get("status") in {
            "authorized", "extended", "reactivated", "upgraded", "already_permanent"
        }:
            logger.debug("本群 %s 已授权并绑定网页卡密", group_id)
            yield self._yield_plain(
                event,
                self._format_portal_authorization_result(
                    group_id, result, current_group=True
                ),
            )
            return
        if result.get("status") == "missing_auth_key":
            yield self._yield_plain(event, "系统未配置授权密钥，无法生成可用于网页登记的群专属卡密。")
        elif result.get("status") == "save_failed":
            yield self._yield_plain(event, "授权卡密保存失败，未完成授权，请稍后重试。")
        else:
            yield self._yield_plain(event, "授权失败，授权数据格式异常或卡密生成冲突，请稍后重试。")

    async def _reissue_group_portal_card(
        self, event: AstrMessageEvent, group_id: str = ""
    ) -> None:
        """Migrate an existing manual group grant to a web-claimable card."""
        if not self._is_owner(event):
            yield self._yield_plain(event, "这命令只有主人能用")
            return
        target_group_id = str(group_id or "").strip()
        if not target_group_id:
            target_group_id = self._get_group_id_from_event(event)
        if not target_group_id or target_group_id == "None":
            yield self._yield_plain(
                event,
                "请在目标群使用，或提供群号\n用法：/补发网页卡密 [群号]",
            )
            return
        if not target_group_id.isdigit() or not 5 <= len(target_group_id) <= 20:
            yield self._yield_plain(event, "群号必须是 5-20 位数字，未补发卡密。")
            return
        auth_key = str(getattr(self, "auth_key", "") or "").strip()
        if not auth_key:
            yield self._yield_plain(event, "系统未配置授权密钥，无法补发可用于网页登记的群专属卡密。")
            return
        operator_id = self._get_sender_id_from_event(event)
        result = ensure_group_authorization_card(
            target_group_id, auth_key, operator_id
        )
        if result.get("status") not in {"issued", "existing"}:
            error_messages = {
                "missing": "该群没有授权记录，请先使用 /添加授权 [天数]。",
                "save_failed": "群专属卡密保存失败，未完成补发，请稍后重试。",
                "data_invalid": "授权数据格式异常，无法补发卡密，请先检查本地授权文件。",
            }
            yield self._yield_plain(
                event,
                error_messages.get(
                    result.get("status"),
                    "补发群专属卡密失败，请稍后重试。",
                ),
            )
            return
        self._request_portal_sync()
        card_sent = await self._deliver_group_portal_card(
            event,
            target_group_id,
            str(result.get("key", "")),
            int(result.get("expire", 0) or 0),
            int(result.get("activated_at", 0) or 0),
        )
        state = get_group_auth_state(target_group_id)
        lines = [
            f"✅ 群 {target_group_id} 的网页登记卡密已{'补发' if result.get('created') else '确认'}。",
            "卡密已私聊发送给主人；Windows 插件同步后，客户即可在网页登记该群。"
            if card_sent
            else "卡密已保存，但私聊发送失败；请开启机器人私聊后重复本命令获取。",
        ]
        if state != "active":
            lines.append("该群当前授权已过期，仍需先用 /添加授权 [天数] 续期后才能编辑网页配置。")
        yield self._yield_plain(event, "\n".join(lines))

    async def _deauthorize_group(self, event: AstrMessageEvent, group_id: str = "") -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event,"这命令只有主人能用")
            return
        if not group_id or not group_id.strip():
            # 未提供群号，尝试获取当前群聊
            current_group_id = self._get_group_id_from_event(event)
            if not current_group_id or current_group_id == "None":
                yield self._yield_plain(event,
                    "请在群聊中使用或提供群号\n"
                    "用法：/取消授权 [群号]"
                )
                return
            group_id = current_group_id
        group_id = group_id.strip()
        if not get_group_auth_info(group_id):
            yield self._yield_plain(event,"❌ 该群未授权")
            return
        if not remove_group_config(group_id):
            yield self._yield_plain(event, f"群 {group_id} 的配置删除失败，授权记录未取消，请重试。")
            return
        if deauthorize_group(group_id):
            self._request_portal_sync()
            logger.debug(f"取消授权 {group_id}：已删除群配置并取消授权")
            yield self._yield_plain(event,f"群 {group_id} 的授权已取消，群配置已删除并关机")
        else:
            # The group configuration was still removed, which changes the
            # remote snapshot even though the auth-record delete needs retry.
            self._request_portal_sync()
            yield self._yield_plain(event, f"群 {group_id} 的配置已删除并关机，但授权记录删除失败，请重试。")

    async def _add_auth_time(self, event: AstrMessageEvent, group_id: str = "", days: str = "") -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event,"这命令只有主人能用")
            return

        from_group_id = self._get_group_id_from_event(event)

        # 解析参数：支持 /增加时间 <天数> 或 /增加时间 <群组ID> <天数>
        if group_id:
            group_id = group_id.strip()
            # 如果 days 已提供，group_id 一定是群号，无需猜测
            if not days or not days.strip():
                # days 为空，需判断 group_id 是群号还是天数
                if group_id == "-1":
                    days = group_id
                    group_id = from_group_id or ""
                elif group_id.isdigit():
                    auth_info = get_group_auth_info(group_id)
                    # 存在授权记录  一定是群号；否则长度>=9且群内上下文为空  倾向群号
                    looks_like_group = bool(auth_info) or (len(group_id) >= 9 and not from_group_id)
                    if not looks_like_group:
                        days = group_id
                        group_id = from_group_id or ""

        if not group_id or not group_id.strip():
            yield self._yield_plain(event,"请在群聊中使用或提供群号\n用法：/增加时间 [群号] <天数>")
            return
        # 解析天数，允许 -1（永不过期）
        days_str = days.strip()
        if days_str == "-1":
            days_int = -1
        elif days_str.isdigit():
            days_int = int(days_str)
        else:
            days_int = self.default_auth_days
        if days_int == 0 or days_int < -1:
            yield self._yield_plain(event, "天数需大于0，-1为永久")
            return
        group_id = group_id.strip()
        existing_info = get_group_auth_info(group_id)
        current_card = str(existing_info.get("key", "")).strip().upper()
        current_used = get_used_keys().get(current_card)
        has_current_portal_card = (
            current_card.startswith("JK")
            and isinstance(current_used, dict)
            and str(current_used.get("group_id", "")) == group_id
        )
        # Do not let the legacy renewal command perpetuate a MANUAL_ record.
        # A renewal of such a group is the natural point to attach the card the
        # web portal needs, while card-backed groups retain their existing card.
        if (existing_info and not has_current_portal_card) or (
            not existing_info and days_int == -1
        ):
            operator_id = self._get_sender_id_from_event(event)
            result = await self._authorize_group_with_portal_card(
                event, group_id, days_int, operator_id
            )
            if result.get("status") in {
                "authorized", "extended", "reactivated", "upgraded", "already_permanent"
            }:
                yield self._yield_plain(
                    event,
                    self._format_portal_authorization_result(group_id, result),
                )
                return
            if result.get("status") == "missing_auth_key":
                yield self._yield_plain(event, "系统未配置授权密钥，无法为旧手动授权生成网页卡密。")
            else:
                yield self._yield_plain(event, "续期卡密保存失败，未修改授权时间，请稍后重试。")
            return
        added = add_auth_time(group_id, days_int)
        if added:
            self._request_portal_sync()
            info = get_group_auth_info(group_id)
            expire = int(info.get("expire", 0))
            activated_at = int(info.get("activated_at", 0) or 0)
            current_card = str(info.get("key", "") or "").strip().upper()
            if expire == -1:
                days_display = "已设为永久"
            else:
                days_display = f"增加 {days_int} 天"
            card_sent = await self._deliver_group_portal_card(
                event, group_id, current_card, expire, activated_at
            )
            yield self._yield_plain(
                event,
                self._format_portal_authorization_result(
                    group_id,
                    {
                        "status": "extended",
                        "key": current_card,
                        "expire": expire,
                        "days": info.get("days", days_display),
                        "activated_at": activated_at,
                        "card_sent_private": card_sent,
                    },
                ),
            )
        else:
            yield self._yield_plain(event,"❌ 该群未授权")

    async def _reduce_auth_time(self, event: AstrMessageEvent, group_id: str = "", days: str = "") -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event,"这命令只有主人能用")
            return

        from_group_id = self._get_group_id_from_event(event)

        # 解析参数：支持 /减少时间 <天数> 或 /减少时间 <群组ID> <天数>
        if group_id:
            group_id = group_id.strip()
            # 如果 days 已提供，group_id 一定是群号，无需猜测
            if not days or not days.strip():
                # days 为空，需判断 group_id 是群号还是天数
                if group_id.isdigit():
                    auth_info = get_group_auth_info(group_id)
                    looks_like_group = bool(auth_info) or (len(group_id) >= 9 and not from_group_id)
                    if not looks_like_group:
                        days = group_id
                        group_id = from_group_id or ""

        if not group_id or not group_id.strip():
            yield self._yield_plain(event,"请在群聊中使用或提供群号\n用法：/减少时间 [群号] <天数>")
            return
        # 解析天数（减少时间不支持 -1，必须为正数）
        days_str = days.strip()
        if days_str.isdigit():
            days_int = int(days_str)
        else:
            days_int = self.default_auth_days
        if days_int <= 0:
            yield self._yield_plain(event, "天数需大于0")
            return
        group_id = group_id.strip()
        # 先检查授权状态，区分"未授权"和"永不过期"
        info = get_group_auth_info(group_id)
        if not info:
            yield self._yield_plain(event, "❌ 该群未授权")
            return
        if int(info.get("expire", 0)) == -1:
            yield self._yield_plain(event, "永久授权无法减少时间，取消请用 /取消授权")
            return
        if reduce_auth_time(group_id, days_int):
            self._request_portal_sync()
            info = get_group_auth_info(group_id)
            expire = int(info.get("expire", 0))
            status = "已过期"if expire < time.time() else "正常"
            yield self._yield_plain(event,
                f"群 {group_id} 减少 {days_int} 天\n"
                f"到期：{time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(expire))}\n"
                f"状态：{status}"
            )
        else:
            yield self._yield_plain(event,"❌ 该群未授权")

    async def _view_authorizations(self, event: AstrMessageEvent) -> None:
        if not self._is_owner(event):
            yield self._yield_plain(event,"这命令只有主人能用")
            return
        groups = list_all_authorizations()
        if not groups:
            yield self._yield_plain(event,"暂无授权群组")
            return
        now = int(time.time())
        result_lines = ["授权列表"]
        for group_id, info in groups.items():
            expire = int(info.get("expire", 0))
            activated_at = info.get("activated_at", 0)
            key = str(info.get("key", "")).strip()
            if key.startswith("MANUAL_"):
                key_display = "手动授权（无卡密）"
            elif key.startswith("JK"):
                key_display = key
            else:
                key_display = "无可验证卡密"
            days = info.get("days", 0)
            user_id = info.get("user_id", "未知")
            # 永不过期
            if expire == -1:
                is_expired = False
                status = "永不过期"
                expire_time = "永不过期"
                days_display = "永久"
            else:
                is_expired = expire < now
                remaining_seconds = expire - now
                if is_expired:
                    expired_days = abs(remaining_seconds) // 86400
                    status = f"已过期 {expired_days} 天"
                else:
                    remaining_days = remaining_seconds // 86400
                    remaining_hours = (remaining_seconds % 86400) // 3600
                    status = f"剩余 {remaining_days} 天 {remaining_hours} 小时"
                expire_time = time.strftime('%Y-%m-%d %H:%M', time.localtime(expire)) if expire > 0 else "未知"
                days_display = f"{days} 天"
            activated_time = time.strftime('%Y-%m-%d %H:%M', time.localtime(activated_at)) if activated_at > 0 else "未知"
            result_lines.append(f"\n群 {group_id}")
            result_lines.append(f"  卡密：{key_display}")
            result_lines.append(f"  天数：{days_display}")
            result_lines.append(f"  激活：{activated_time}")
            result_lines.append(f"  到期：{expire_time}")
            result_lines.append(f"  状态：{'✅️'if not is_expired else '❌️'} {status}")
            result_lines.append(f"  操作人：{user_id}")
        yield self._yield_plain(event,"\n".join(result_lines))

    @staticmethod
    def _format_nested_command_help(title: str, sections: list[tuple[str, list[tuple[str, list[str]]]]], footer: str = "") -> str:
        """Render command help as a stable first-level/second-level tree."""
        lines = [title]
        for first_level, children in sections:
            lines.append(f"\n一级：{first_level}")
            for second_level, commands in children:
                lines.append(f"  二级：{second_level}")
                for command in commands:
                    if str(command).strip():
                        lines.append(f"    {command}")
        if footer:
            lines.append(f"\n{footer}")
        return "\n".join(lines)

    @staticmethod
    def _format_command_category_index(
        title: str,
        sections: list[tuple[str, list[tuple[str, list[str]]]]],
        *,
        category_command: str = "群管功能",
        footer: str = "",
    ) -> str:
        """Render one compact layer of the help tree.

        The full command rows belong to a feature detail page.  Keeping the
        index to names and counts prevents mobile QQ clients from truncating
        the useful part of ``/群管功能`` replies.
        """
        lines = [title, "一级：功能分类"]
        for category, children in sections:
            count = sum(len(commands) for _, commands in children)
            lines.append(f"  二级：{category}（{count} 项）")
            lines.append(f"    查看：/{category_command} {category}")
        if footer:
            lines.append(f"\n{footer}")
        return "\n".join(lines)

    @staticmethod
    def _format_feature_category_help(
        title: str,
        category: str,
        children: list[tuple[str, list[str]]],
        *,
        category_command: str = "群管功能",
        footer: str = "",
    ) -> str:
        """Render executable usage rows for one category."""
        lines = [title, f"一级：{category}"]
        for feature, commands in children:
            visible_commands = [str(command).strip() for command in commands if str(command).strip()]
            if not visible_commands:
                continue
            lines.append(f"  {feature}")
            lines.extend(f"    {command}" for command in visible_commands)
        if footer:
            lines.append(f"\n{footer}")
        return "\n".join(lines)

    @staticmethod
    def _compact_command_token(value: object) -> str:
        """Extract the first real command from a configured help row."""
        match = re.search(r"(?<!\w)(/[^\s、，：:|]+|#[^\s、，：:|]+)", str(value or ""))
        if not match:
            return ""
        token = match.group(1).rstrip("。.,，；;）)")
        return token if len(token) > 1 else ""

    @classmethod
    def _format_compact_feature_menu(
        cls,
        sections: list[tuple[str, list[tuple[str, list[str]]]]] | None = None,
    ) -> str:
        """Render only commands that are actually enabled for this group."""
        commands: list[str] = []
        seen: set[str] = set()
        for _category, children in sections or ():
            for _feature, rows in children:
                for row in rows:
                    command = cls._compact_command_token(row)
                    if command and command not in seen:
                        seen.add(command)
                        commands.append(command)
                        break
        if not commands:
            commands = ["/帮助"]
        lines = ["功能菜单", "────────────"]
        for index in range(0, len(commands), 2):
            left = commands[index]
            right = commands[index + 1] if index + 1 < len(commands) else ""
            lines.append(f"{left:<16}{right}")
        return "\n".join(lines)

    @staticmethod
    def _format_group_admin_feature_menu(
        sections: list[tuple[str, list[tuple[str, list[str]]]]] | None = None,
        *,
        category_command: str = "群管功能",
        audience: str = "member",
    ) -> str:
        """Render the first-level group-management feature names only."""
        _ = sections, audience
        feature_names = (
            "入群审核",
            "入群欢迎",
            "黑名单系统",
            "禁言系统",
            "踢出系统",
            "撤回系统",
            "群消息记录",
            "关键词过滤",
            "分群管理员",
            "自动回复",
            "用户专属回复",
            "定时消息",
            "文转图",
            "群设置",
            "黑名单记录",
        )
        return "\n".join([str(category_command), "────────────", *feature_names])

    @staticmethod
    def _command_help_args(event: AstrMessageEvent, aliases: set[str]) -> list[str]:
        """Return arguments after a help command, preserving configured names."""
        message = str(getattr(event, "message_str", "") or "").strip()
        if message.startswith("/"):
            message = message[1:].lstrip()
        parts = message.split()
        if not parts or parts[0] not in aliases:
            return []
        return parts[1:]

    def _get_group_help_settings(self, group_id: str | None) -> dict[str, object]:
        """Read the per-group command and audience for the feature directory."""
        defaults = {
            "command": "群管功能",
            "aliases": ("群管功能",),
            "permission": "member",
        }
        if not group_id:
            return defaults
        try:
            from .qqadmin.group_config import get_group_feature_detail

            detail = get_group_feature_detail(group_id, "group_config", self.config)
        except Exception:
            detail = {}
        if not isinstance(detail, dict):
            detail = {}
        value = detail.get("help_command", defaults["command"])
        aliases = self._command_aliases(value, "群管功能")
        return {
            "command": str(aliases[0] if aliases else "群管功能"),
            "aliases": aliases or ("群管功能",),
            "permission": str(detail.get("help_permission", "member") or "member"),
        }

    async def _group_help_permission_allowed(
        self, event: AstrMessageEvent, permission: object
    ) -> bool:
        """Check who may open the configured command directory."""
        required = str(permission or "member").strip().lower()
        if required == "member" or self._is_owner(event):
            return True
        if required == "owner":
            return await self._is_group_owner_async(event)
        return await self._is_admin_or_owner_async(event)

    def _match_group_help_dynamic_command(
        self, event: AstrMessageEvent, command_text: object
    ) -> bool:
        """Match the configured group-help token before static dispatch."""
        text = str(command_text or "").strip().lstrip("/")
        if not text:
            return False
        command = text.split(maxsplit=1)[0].casefold()
        settings = self._get_group_help_settings(self._get_group_id_from_event(event))
        aliases = settings.get("aliases", ("群管功能",))
        return command in {
            str(alias or "").strip().lstrip("/").casefold()
            for alias in aliases
        }

    @staticmethod
    def _help_usage_line(value: object, permission: object = "member") -> str:
        """Keep help rows to executable syntax and the allowed audience."""
        text = str(value or "").strip()
        if "｜用户：" in text:
            return text
        if "：" in text:
            text = text.split("：", 1)[0].strip()
        text = text.replace(" - ", " ").replace("–", " ")
        text = re.sub(r"\s+", " ", text).strip()
        return f"{text}｜用户：{permission_label(permission)}" if text else ""

