    def _group_help_detail_handler(self, name: str):
        normalized_name = str(name or "").strip()
        handlers = {
            "入群审核": self._show_audit_help,
            "审核": self._show_audit_help,
            "黑名单": self._show_blacklist_help,
            "黑名单系统": self._show_blacklist_help,
            "禁言": self._show_mute_help,
            "禁言系统": self._show_mute_help,
            "踢出": self._show_kick_help,
            "踢出系统": self._show_kick_help,
            "撤回": self._show_recall_help,
            "撤回系统": self._show_recall_help,
            "群消息记录": self._show_recall_help,
            "黑名单记录": self._show_blacklist_help,
            "入群欢迎": self._show_welcome_help,
            "欢迎": self._show_welcome_help,
            "自动回复": self._show_reply_help,
            "自定义回复": self._show_reply_help,
            "关键词过滤": self._show_keyword_filter_help,
            "用户专属回复": self._show_player_reply_help,
            "专属回复": self._show_player_reply_help,
            "签到": self._show_signin_help,
            "签到状态": self._show_signin_status_help,
            "签到日历": self._show_signin_calendar_help,
            "签到排行": self._show_signin_ranking_help,
            "排行榜": self._show_ranking_help,
            "我的信息": self._show_user_info_help,
            "群统计": self._show_group_stats_help,
            "定时消息": self._show_timed_msg_help,
            "定时任务": self._show_timed_msg_help,
            "分群管理员": self._show_sub_admin_help,
            "文转图": self._show_text_to_image_help,
            "图转文": self._show_text_to_image_help,
            "娱乐": self._show_entertainment_help,
            "游戏指令": self._show_game_commands_help,
            "群设置": self._show_group_config_help,
            "SCUM": self.show_scum_help,
            "服务器绑定": self.show_scum_help,
            "查询": self.show_scum_help,
            "查询设置": self.show_scum_help,
            "独立方案": self._show_stats_help,
            "积分与数据": self._show_stats_help,
            "邀请统计": self._show_stats_help,
            "抽奖": self._show_lottery_help,
            "互动": self._show_entertainment_help,
        }
        handler = handlers.get(normalized_name)
        if handler is not None:
            return handler

        # The shared catalogue is the extension point for new features.  This
        # fallback keeps feature labels, aliases, and help handlers in sync
        # without requiring another hand-maintained dispatch entry.
        category = FEATURE_BY_COMMAND.get(normalized_name) or FEATURE_BY_KEY.get(
            normalized_name
        )
        if category is None:
            category = FEATURE_BY_COMMAND.get(normalized_name.casefold())
        if category is not None:
            candidate = getattr(self, category.help_handler, None)
            if callable(candidate):
                return candidate
        return None

    @filter.command("帮助", alias={"菜单", "命令"})
    async def show_help(self, event: AstrMessageEvent) -> None:
        logger.debug(f"show_help 被调用: {event.message_str}")
        if not self.enable_help:
            logger.debug(f"show_help 被拒绝: enable_help={self.enable_help}")
            return
        
        group_id = self._get_group_id_from_event(event)
        help_args = self._command_help_args(event, {"帮助", "菜单", "命令"})
        if help_args:
            detail_handler = self._group_help_detail_handler(help_args[-1])
            if detail_handler is not None:
                async for result in detail_handler(event):
                    yield result
                event.stop_event()
                return
            yield self._yield_plain(
                event,
                "未找到该功能。请使用 /功能 查看目录，或发送 /功能 功能名 查看详情。",
            )
            event.stop_event()
            return
        # 检查斜杠前缀权限（管理员和主人不受限制）
        if not self.allow_slash_prefix and not self._is_whitelist_group(event):
            if group_id:
                group_setting = get_group_setting(group_id, "allow_slash_prefix", None)
                if group_setting is not None and group_setting is False:
                    # 群设置禁止斜杠前缀，检查是否是管理员/主人
                    if not self._is_owner(event):
                        logger.debug(f"show_help 被拒绝: 群设置禁止斜杠前缀且用户非管理员")
                        return

        # Do not keep a second hand-written command tree here.  It became
        # stale whenever a group changed a command name in the portal and it
        # also advertised disabled features.  Reuse the same effective
        # sections as the group-management menu so /菜单 always reflects the
        # current Windows configuration and every listed command can be sent
        # directly.
        try:
            sections = self._group_help_sections(event, group_id)
            help_text = self._format_compact_feature_menu(sections)
        except Exception:
            logger.warning("生成当前群菜单失败", exc_info=True)
            help_text = "功能菜单\n────────────\n/群管功能\n/scum帮助"
        logger.debug("show_help 发送当前分群菜单")
        yield self._yield_plain(event, help_text)

    @filter.command("scum帮助", alias={"SCUM帮助"})
    async def show_scum_help(self, event: AstrMessageEvent) -> None:
        logger.debug(f"show_scum_help 被调用: {event.message_str}")
        if not self.enable_help:
            event.stop_event()
            return
        # 检查斜杠前缀权限（管理员和主人不受限制）
        if not self.allow_slash_prefix and not self._is_whitelist_group(event):
            group_id = self._get_group_id_from_event(event)
            if group_id:
                group_setting = get_group_setting(group_id, "allow_slash_prefix", None)
                if group_setting is not None and group_setting is False:
                    # 群设置禁止斜杠前缀，检查是否是主人
                    if not self._is_owner(event):
                        logger.debug(f"show_scum_help 被拒绝: 群设置禁止斜杠前缀且非主人")
                        event.stop_event()
                        return
        group_id = self._get_group_id_from_event(event)
        scum_config = self._get_scum_group_config(event)
        signin_commands = self._get_signin_command_settings(
            group_id
        )
        if not self._is_scum_query_enabled(event):
            yield self._yield_plain(event, "SCUM 查询未开启。")
            event.stop_event()
            return

        def command_alias(settings: dict, key: str, default: str) -> str:
            aliases = settings.get(f"{key}_aliases") or self._command_aliases(
                settings.get(key), default
            )
            return "/" + str(aliases[0] if aliases else default).lstrip("/")

        keyword_command = command_alias(scum_config, "keyword_command", "查询")
        online_command = command_alias(scum_config, "online_command", "查询在线")
        bind_command = command_alias(signin_commands, "bind", "绑定SteamID")
        unbind_command = command_alias(signin_commands, "unbind", "解绑SteamID")

        # Keep this page as a direct command list.  Do not include the old
        # first-level/second-level tree or compatibility aliases: the portal
        # configuration is the source of truth for the command shown here.
        help_lines = [
            "SCUM 查询",
            "/绑定id 或 /id绑定 服务器ID",
            "/解绑",
            online_command,
            f"{keyword_command} 关键词",
            f"{bind_command} 17位SteamID",
            f"{unbind_command} QQ号或SteamID（管理员）",
        ]
        yield self._yield_plain(event, "\n".join(help_lines))
        event.stop_event()

    def _get_signin_reward_config(self, group_id: str) -> dict:
        """Build the data-layer reward policy from global and group settings."""
        global_stats = self.config.get("qqadmin", {}).get("stats", {})
        if isinstance(global_stats, dict) and isinstance(global_stats.get("items"), dict):
            global_stats = global_stats["items"]
        if not isinstance(global_stats, dict):
            global_stats = {}

        try:
            group_stats = get_group_feature_detail(group_id, "stats", self.config)
        except Exception:
            group_stats = {}
        if not isinstance(group_stats, dict):
            group_stats = {}

        settings = (
            ("base_reward", "signin_base_reward", 10),
            ("reward_3_days", "signin_reward_3_days", 30),
            ("reward_7_days", "signin_reward_7_days", 100),
            ("reward_14_days", "signin_reward_14_days", 200),
            ("reward_30_days", "signin_reward_30_days", 500),
        )

        def _unwrap(value, default):
            if isinstance(value, dict) and "default" in value:
                value = value["default"]
            return default if value is None else value

        return {
            api_key: _unwrap(
                group_stats.get(setting_key),
                _unwrap(global_stats.get(setting_key), default),
            )
            for api_key, setting_key, default in settings
        }

    def _get_signin_policy(self, group_id: str, profile_selector: str = "") -> dict:
        """Return the portal-editable sign-in policy with safe local defaults."""
        global_stats = self.config.get("qqadmin", {}).get("stats", {})
        if isinstance(global_stats, dict) and isinstance(global_stats.get("items"), dict):
            global_stats = global_stats["items"]
        if not isinstance(global_stats, dict):
            global_stats = {}
        try:
            group_stats = get_group_feature_detail(group_id, "stats", self.config)
        except Exception:
            group_stats = {}
        if not isinstance(group_stats, dict):
            group_stats = {}
        merged = dict(global_stats)
        merged.update(group_stats)
        policy = signin_policy(merged)
        return select_signin_profile(policy, profile_selector)

    async def _mute_unverified_steam_member(
        self, event: AstrMessageEvent, group_id: str, user_id: str, policy: dict
    ) -> bool:
        """Mute one unbound member when the group requires SteamID validation."""
        if not bool(policy.get("steamid_verification_required", False)):
            return False
        if not group_id or not user_id or not str(user_id).isdigit():
            return False
        if user_id == self._get_event_self_id(event):
            return False
        message = self._get_event_message_text(event).strip()
        if not message or message.startswith("/"):
            return False
        if self._is_server_binding_command(message):
            return False
        # The binding command itself is the escape hatch that lets an
        # unverified member complete the requirement.  Support both the
        # configured aliases and the legacy Chinese spellings, with or
        # without a leading slash.
        try:
            bind_aliases = self._get_signin_command_settings(group_id).get(
                "bind_aliases", ("绑定SteamID",)
            )
        except Exception:
            bind_aliases = ("绑定SteamID", "绑定steam", "绑定Steam", "绑定steamid")
        command_text = message.lstrip("/").strip().casefold()
        if any(
            command_text == str(alias).strip().casefold()
            or command_text.startswith(str(alias).strip().casefold() + " ")
            for alias in bind_aliases
            if str(alias).strip()
        ) or re.match(r"^绑定(?:\s*(?:steam\s*id|steam|id))?(?:\s|$)", command_text):
            return False
        # A member answering an active admission/SteamID challenge must be
        # allowed to complete it before the normal-chat enforcement runs.
        try:
            from .qqadmin.audit import get_pending_verification

            pending = get_pending_verification(group_id, user_id) or {}
            if pending and (
                str(pending.get("status", "pending")).lower() == "pending"
                or pending.get("steamid_stage")
            ):
                return False
        except Exception:
            logger.debug(
                "读取 SteamID 验证待处理状态失败 group=%s user=%s",
                group_id,
                user_id,
                exc_info=True,
            )
        try:
            if await self._is_admin_or_owner_async(event):
                return False
        except Exception:
            # A permission lookup failure must not silently grant a bypass.
            logger.debug(
                "读取 SteamID 强制验证权限失败 group=%s user=%s",
                group_id,
                user_id,
                exc_info=True,
            )
        binding = get_steam_binding(group_id, user_id=user_id) or {}
        if normalize_steam_id(binding.get("steam_id", "")):
            return False
        try:
            from .qqadmin.mute import is_muted

            if is_muted(group_id, user_id):
                return True
        except Exception:
            logger.debug(
                "读取 SteamID 验证禁言状态失败 group=%s user=%s",
                group_id,
                user_id,
                exc_info=True,
            )
        try:
            duration = max(
                1,
                min(int(policy.get("unverified_mute_duration", 300) or 300), 2_592_000),
            )
        except (TypeError, ValueError, OverflowError):
            duration = 300
        try:
            client = getattr(event, "bot", None)
            if client is None:
                platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                client = platform.get_client() if platform else None
            if client is None:
                raise RuntimeError("platform_unavailable")
            result = None
            typed_method = getattr(client, "set_group_ban", None)
            if callable(typed_method):
                try:
                    result = await typed_method(
                        group_id=int(group_id), user_id=int(user_id), duration=duration
                    )
                except TypeError:
                    result = None
            if result is None:
                call_action = getattr(client, "call_action", None)
                if not callable(call_action):
                    raise RuntimeError("set_group_ban_unavailable")
                result = await call_action(
                    action="set_group_ban",
                    group_id=int(group_id),
                    user_id=int(user_id),
                    duration=duration,
                )
            if not self._api_result_succeeded(result):
                raise RuntimeError(
                    self._onebot_failure_detail(result) or "平台拒绝禁言"
                )
            from .qqadmin.mute import mute_user
            from .qqadmin.audit import add_operation_log

            mute_user(
                group_id,
                user_id,
                duration,
                "未完成 SteamID 验证",
                "system",
                "manual",
            )
            add_operation_log(
                group_id,
                "system",
                "Windows机器人",
                "SteamID验证禁言",
                user_id,
                "",
                f"未绑定 SteamID，禁言 {duration} 秒",
            )
            notice = str(policy.get("unverified_mute_message", "") or "").strip()
            if notice:
                sender = getattr(getattr(event, "message_obj", None), "sender", None)
                user_name = (
                    str(getattr(sender, "card", "") or getattr(sender, "nickname", "") or user_id)
                    if sender is not None
                    else user_id
                )
                try:
                    notice = notice.format(
                        user_id=user_id,
                        user_name=user_name,
                        duration=duration,
                        group_id=group_id,
                    )
                except Exception:
                    pass
                await self._send_group_msg(group_id, notice, context=self.context)
            logger.info(
                "未完成 SteamID 验证，已禁言发言成员 group=%s user=%s duration=%s",
                group_id,
                user_id,
                duration,
            )
            return True
        except Exception as exc:
            logger.warning(
                "未完成 SteamID 验证的自动禁言失败 group=%s user=%s error_type=%s detail=%s",
                group_id,
                user_id,
                type(exc).__name__,
                self._onebot_failure_detail(exc)[:180],
            )
            return False

    def _steamid_enforcement_candidate(
        self, event: AstrMessageEvent, group_id: str, user_id: str, policy: dict
    ) -> bool:
        """Perform only local checks before scheduling SteamID enforcement.

        This deliberately avoids the asynchronous member-role request.  That
        request is the source of the long delay observed before ordinary
        auto-replies; the full permission check remains inside the background
        worker where a bounded timeout can be applied.
        """
        if not bool(policy.get("steamid_verification_required", False)):
            return False
        if not group_id or not user_id or not str(user_id).isdigit():
            return False
        if user_id == self._get_event_self_id(event):
            return False
        message = self._get_event_message_text(event).strip()
        if not message or message.startswith("/"):
            return False
        try:
            bind_aliases = self._get_signin_command_settings(group_id).get(
                "bind_aliases", ("绑定SteamID",)
            )
        except Exception:
            bind_aliases = ("绑定SteamID", "绑定steam", "绑定Steam", "绑定steamid")
        command_text = message.lstrip("/").strip().casefold()
        if any(
            command_text == str(alias).strip().casefold()
            or command_text.startswith(str(alias).strip().casefold() + " ")
            for alias in bind_aliases
            if str(alias).strip()
        ) or re.match(r"^绑定(?:\s*(?:steam\s*id|steam|id))?(?:\s|$)", command_text):
            return False
        try:
            from .qqadmin.audit import get_pending_verification

            pending = get_pending_verification(group_id, user_id) or {}
            if pending and (
                str(pending.get("status", "pending")).lower() == "pending"
                or pending.get("steamid_stage")
            ):
                return False
        except Exception:
            pass
        if self._get_event_member_role(event, user_id) in {"admin", "owner"}:
            return False
        if self._cached_member_role(group_id, user_id) in {"admin", "owner"}:
            return False
        if self._is_owner(event):
            return False
        try:
            binding = get_steam_binding(group_id, user_id=user_id) or {}
            if normalize_steam_id(binding.get("steam_id", "")):
                return False
        except Exception:
            pass
        return True

    def _schedule_unverified_steam_enforcement(
        self, event: AstrMessageEvent, group_id: str, user_id: str, policy: dict
    ) -> None:
        """Run the slow QQ moderation request outside the message pipeline."""
        key = f"{group_id}:{user_id}"
        if key in self._steam_enforcement_task_keys:
            return
        self._steam_enforcement_task_keys.add(key)

        async def runner() -> None:
            try:
                await asyncio.wait_for(
                    self._mute_unverified_steam_member(event, group_id, user_id, policy),
                    timeout=4.0,
                )
            except asyncio.TimeoutError:
                logger.warning(
                    "SteamID验证禁言接口超时，已释放消息处理 group=%s user=%s",
                    group_id,
                    user_id,
                )
            except asyncio.CancelledError:
                raise
            except Exception:
                logger.debug(
                    "后台执行 SteamID 验证禁言失败 group=%s user=%s",
                    group_id,
                    user_id,
                    exc_info=True,
                )
            finally:
                self._steam_enforcement_task_keys.discard(key)

        task = asyncio.create_task(runner())
        self._steam_enforcement_tasks.add(task)
        task.add_done_callback(self._steam_enforcement_tasks.discard)

    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE, priority=11850)
    async def handle_unverified_steam_member(self, event: AstrMessageEvent) -> None:
        """Block ordinary chat from members without a required SteamID binding."""
        group_id = self._get_group_id_from_event(event)
        if (
            not group_id
            or not self._event_allows_primary_group_bot(event, group_id)
            or not self._can_send_group_message(group_id)
        ):
            return
        user_id = self._get_sender_id_from_event(event)
        policy = self._get_signin_policy(group_id)
        if not self._steamid_enforcement_candidate(event, group_id, user_id, policy):
            return
        if not self._claim_group_event_action(
            event,
            "steamid-enforcement",
            self._get_event_message_text(event),
            message_ttl=20.0,
            fallback_ttl=5.0,
        ):
            event.stop_event()
            return
        # Do not make every ordinary message wait for NapCat's moderation
        # endpoint.  The event is stopped immediately, while the actual mute,
        # audit record, and optional notice complete in the worker above.
        self._schedule_unverified_steam_enforcement(event, group_id, user_id, policy)
        event.stop_event()

    def _get_signin_command_settings(self, group_id: str) -> dict[str, object]:
        """Return the effective player-facing sign-in commands for one group."""
        if not group_id:
            return {
                "signin": "签到",
                "signin_aliases": ("签到",),
                "bind": "绑定SteamID",
                "bind_aliases": ("绑定SteamID",),
                "unbind": "解绑SteamID",
                "status": "签到状态",
                "calendar": "签到日历",
                "ranking": "签到排行",
            }
        policy = self._get_signin_policy(group_id)
        signin_aliases = self._command_aliases(policy.get("signin_command"), "签到")
        bind_aliases = self._command_aliases(policy.get("bind_command"), "绑定SteamID")
        return {
            "signin": signin_aliases[0],
            "signin_aliases": signin_aliases,
            "bind": bind_aliases[0],
            "bind_aliases": bind_aliases,
            "unbind": "解绑SteamID",
            "status": "签到状态",
            "calendar": "签到日历",
            "ranking": "签到排行",
        }

    def _get_signin_profile_help_lines(
        self,
        group_id: str | None,
        policy: dict | None = None,
        *,
        limit: int = 8,
    ) -> list[str]:
        """Return short, effective command rows for enabled sign-in profiles."""
        detail = policy if isinstance(policy, dict) else (
            self._get_signin_policy(group_id) if group_id else {}
        )
        raw_profiles = detail.get("signin_profiles", [])
        if not isinstance(raw_profiles, list):
            return []
        mode_names = {"basic": "普通", "steam": "SteamID"}
        schedule_names = {
            "daily": "每日",
            "weekly": "每周",
            "monthly": "每月",
            "streak": "连续",
            "custom": "自定义",
        }
        rows: list[str] = []
        for profile in raw_profiles:
            if not isinstance(profile, dict) or not profile.get("enabled", True):
                continue
            command_aliases = self._command_aliases(
                profile.get("command", profile.get("signin_command", "")), ""
            )
            if not command_aliases:
                continue
            command = command_aliases[0]
            name = str(profile.get("name", "") or "").strip()
            mode = str(
                profile.get("signin_mode", profile.get("mode", "basic")) or "basic"
            ).strip().lower()
            schedule = str(
                profile.get("schedule_mode", profile.get("schedule", "daily"))
                or "daily"
            ).strip().lower()
            command_text = "|".join(command_aliases)
            label = f"（{name}）" if name and name != command else ""
            rows.append(
                f"/{command_text}{label}：{mode_names.get(mode, '普通')}·"
                f"{schedule_names.get(schedule, '每日')}签到"
            )
        if len(rows) > limit:
            remaining = len(rows) - limit
            rows = rows[:limit] + [f"其余 {remaining} 个方案：网页配置中可查看"]
        return rows

    def _get_steam_database_path(self, group_id: str):
        """Resolve the selected local SQLite snapshot for one QQ group."""
        try:
            group_config = get_group_config(group_id, self.config)
        except Exception:
            group_config = {}
        return resolve_group_database_path(
            group_config,
            plugin_root=os.path.dirname(os.path.abspath(__file__)),
        )

    @staticmethod
    def _signin_database_descriptor(policy: object) -> dict:
        """Find the selected portal database descriptor without guessing."""

        detail = policy if isinstance(policy, dict) else {}
        raw_profiles = detail.get("database_profiles", [])
        if not isinstance(raw_profiles, (list, tuple)):
            raw_profiles = []
        selected_id = str(
            detail.get("database_profile", detail.get("active_database_profile", ""))
            or ""
        ).strip()
        first_enabled: dict | None = None
        for raw_profile in raw_profiles:
            if not isinstance(raw_profile, dict):
                continue
            enabled = raw_profile.get("enabled", True)
            if isinstance(enabled, str):
                enabled = enabled.strip().lower() not in {
                    "",
                    "0",
                    "false",
                    "off",
                    "no",
                }
            if not enabled:
                continue
            descriptor_id = str(
                raw_profile.get("id", raw_profile.get("profile_id", "")) or ""
            ).strip()
            if selected_id and descriptor_id == selected_id:
                return raw_profile if enabled else {}
            if first_enabled is None:
                first_enabled = raw_profile
        # The group configuration can arrive before the full descriptor list
        # is mirrored to Windows.  The selected profile ID is already enough
        # for the Linux read-only lookup endpoint, so do not discard it and
        # incorrectly fall back to a stale local snapshot.
        if selected_id:
            return {"id": selected_id, "profile_id": selected_id}
        return first_enabled or {}

    def _signin_database_local_path(self, policy: object) -> Path | None:
        """Resolve a configured snapshot path for an on-demand pull."""

        detail = policy if isinstance(policy, dict) else {}
        descriptor = self._signin_database_descriptor(detail)
        raw_path = str(
            descriptor.get("path", descriptor.get("database_path", ""))
            or detail.get("database_path", detail.get("sqlite_path", ""))
            or ""
        ).strip().replace("\\", "/")
        parts = [part for part in raw_path.split("/") if part not in {"", "."}]
        if (
            not parts
            or raw_path.startswith("/")
            or re.match(r"^[A-Za-z]:", raw_path)
            or any(part == ".." for part in parts)
            or any(":" in part or any(ord(char) < 32 for char in part) for part in parts)
        ):
            return None
        try:
            root = Path(__file__).resolve().parent
            target = (root / "/".join(parts)).resolve()
            target.relative_to(root)
            return target
        except (OSError, RuntimeError, ValueError):
            return None

    async def _ensure_signin_database_snapshot(
        self, group_id: str, policy: object
    ) -> tuple[Path | None, str]:
        """Pull one missing DB snapshot before an authoritative sign-in.

        The regular web-sync worker remains the normal path. This bounded
        fallback handles the short window immediately after a web save, when
        a user can issue a sign-in before the background snapshot task runs.
        """

        local_path = self._get_steam_database_path(group_id)
        if local_path is not None:
            return local_path, ""
        detail = policy if isinstance(policy, dict) else {}
        descriptor = self._signin_database_descriptor(detail)
        profile_id = str(
            descriptor.get("id", descriptor.get("profile_id", "")) or ""
        ).strip()
        try:
            revision = int(descriptor.get("snapshot_revision", 0) or 0)
        except (TypeError, ValueError, OverflowError):
            revision = 0
        snapshot_hash = str(descriptor.get("snapshot_sha256", "") or "").strip().lower()
        client = getattr(self, "_portal_sync_client", None)
        if not profile_id or revision <= 0 or not re.fullmatch(r"[0-9a-f]{64}", snapshot_hash):
            return None, "网页没有提供当前服务器数据库快照，请先在网页保存对应 FTP 数据库。"
        if client is None or not callable(getattr(client, "fetch_database_snapshot", None)):
            return None, "Windows 尚未连接网页同步中心，暂时没有可用的服务器数据库快照。"
        try:
            data, fetched_revision, fetched_hash = await client.fetch_database_snapshot(
                group_id,
                profile_id,
                expected_revision=revision,
                expected_sha256=snapshot_hash,
            )
            if fetched_revision != revision or fetched_hash != snapshot_hash:
                return None, "网页数据库快照版本校验不一致，请重新保存并同步当前服务器数据库。"
            from .qqadmin.web_sync import materialize_database_snapshot

            path_value = str(
                descriptor.get("path", descriptor.get("database_path", ""))
                or detail.get("database_path", detail.get("sqlite_path", ""))
                or ""
            )
            materialize_database_snapshot(path_value, data, fetched_hash)
        except Exception as exc:
            summary = ""
            summary_method = getattr(type(client), "_sync_error_summary", None)
            if callable(summary_method):
                try:
                    summary = str(summary_method(exc) or "").strip().lower()
                except Exception:
                    summary = ""
            if not summary:
                summary = "database_snapshot_sync_failed"
            error_message = "网页数据库快照同步失败。"
            message_method = getattr(type(client), "sync_error_message", None)
            if callable(message_method):
                try:
                    error_message = str(message_method(summary) or error_message)
                except Exception:
                    pass
            logger.warning(
                "签到前拉取服务器数据库失败 group=%s profile=%s code=%s",
                group_id,
                profile_id,
                summary,
            )
            return None, error_message
        resolved = self._get_steam_database_path(group_id)
        if resolved is None or not resolved.is_file():
            return None, "数据库快照已返回，但 Windows 未能写入当前服务器配置，请检查插件目录权限。"
        return resolved, ""

    @staticmethod
    def _signin_database_failure_reason(result: object) -> str:
        """Convert a database result into a short actionable user reason."""

        detail = result if isinstance(result, dict) else {}
        explicit = str(detail.get("database_diagnostic", "") or "").strip()
        if explicit:
            return explicit[:500]
        code = str(detail.get("code", "") or "").strip().lower()
        reason_code = str(detail.get("reason_code", "") or "").strip().lower()
        if code in {
            "database_mutation_failed",
            "database_ftp_not_configured",
            "database_mutation_conflict",
        }:
            live_message = str(detail.get("message", "") or "").strip()
            if live_message and live_message not in {
                "服务器数据库事务失败，请稍后重试。",
                "服务器数据库事务失败，请稍后重试",
                "服务器数据库事务未完成，本次签到未发放奖励。",
            }:
                return live_message[:500]
        messages = {
            "steam_database_unavailable": "当前签到方案没有可用的服务器数据库，请在网页绑定并启用对应 FTP SQLite 数据库。",
            "db_unavailable": "服务器数据库不可用或无法读取，请检查网页 FTP 配置和数据库文件。",
            "database_snapshot_upload_failed": "签到已写入 Windows 本地数据库，但回传网页/FTP 失败，系统会自动重试；请检查网页同步状态。",
            "invalid_database_snapshot": "当前服务器数据库路径无效或不在插件目录内，未能回传 FTP 数据库。",
            "invalid_database_snapshot_body": "当前服务器数据库文件不是有效 SQLite 文件，未能回传 FTP 数据库。",
            "database_snapshot_read_failed": "Windows 无法读取刚刚更新的服务器数据库文件，请检查文件权限。",
            "database_snapshot_conflict": "FTP 数据库已有更新版本，本次本地奖励已保留，等待重新同步后再回传。",
            "database_mutation_failed": "服务器数据库事务未完成；请检查 Linux 网页端 FTP 路径、账号权限和 SQLite 文件占用。",
            "database_mutation_conflict": "服务器数据库刚刚被其他人修改，本次签到未发放奖励，请稍后重试。",
            "database_ftp_not_configured": "当前服务器未配置可写入的 FTP SQLite 数据库。",
            "remote_mode_disabled": "网页端未启用远程数据库模式，无法执行服务器数据库签到。",
            "group_not_bound": "当前群尚未绑定网页账号，无法定位服务器数据库。",
            "invalid_database_snapshot_scope": "服务器数据库选择范围无效，请重新选择当前群绑定的数据库。",
            "database_snapshot_missing": "网页端没有可用的数据库快照，请先在服务器与数据库设置中保存并测试 FTP 数据库。",
            "not_found": "当前服务器数据库中没有找到该 SteamID，请确认绑定的是这台服务器的 17 位 SteamID。",
            "ambiguous": "当前服务器数据库中的 SteamID 记录不唯一，无法安全发放奖励。",
            "schema_error": "当前服务器数据库缺少签到或奖励字段，无法安全修改玩家数据。",
            "query_error": "写入当前服务器数据库失败，请查看 Windows CMD 中的数据库错误日志后重试。",
            "already_signed": "当前签到周期已经签到过，未重复发放奖励。",
            "steam_id_required": "尚未绑定 SteamID，未执行本次签到。",
        }
        if reason_code and reason_code in messages:
            return messages[reason_code]
        return messages.get(code, "服务器数据库未确认完成，未发放签到奖励。")

    def _get_steam_database_validator(self, group_id: str):
        """Return a read-only validator for the current group's player DB.

        FTP credentials intentionally remain in the portal.  Windows only
        receives a selected local SQLite path, so binding never opens a
        portal database session.  The bundled database remains the legacy
        fallback for groups that have not selected a downloaded snapshot.
        """
        database_path = self._get_steam_database_path(group_id)

        if database_path is None:
            def unavailable(_steam_id: str) -> dict:
                return {
                    "success": False,
                    "code": "db_unavailable",
                    "message": "服务器数据库暂不可用，暂时无法验证 SteamID，请稍后重试。",
                }

            return unavailable

        def validate(steam_id: str) -> dict:
            return lookup_user_list_steam_id(database_path, steam_id)

        return validate

    async def _validate_group_steam_id(self, group_id: str, steam_id: str) -> dict:
        """Validate a SteamID against the selected authoritative server DB.

        Verification is read-only.  The result carries the player's game name
        so admission can update the QQ group card without mutating the SCUM
        database itself.
        """
        policy = self._get_signin_policy(group_id)
        descriptor = self._signin_database_descriptor(policy)
        profile_id = str(
            descriptor.get("id", descriptor.get("profile_id", "")) or ""
        ).strip()
        portal_client = getattr(self, "_portal_sync_client", None)
        portal_validate = getattr(portal_client, "validate_database_steam_id", None)

        def local_snapshot_validation() -> dict:
            validator = self._get_steam_database_validator(group_id)
            if not callable(validator):
                return {
                    "success": False,
                    "code": "db_unavailable",
                    "message": "Windows 尚未保存当前服务器数据库快照。",
                    "validation_source": "windows_snapshot",
                }
            try:
                local_result = validator(steam_id)
            except Exception as exc:
                logger.warning(
                    "Windows 本地 SteamID 快照验证异常 group=%s error=%s",
                    group_id,
                    type(exc).__name__,
                )
                return {
                    "success": False,
                    "code": "db_unavailable",
                    "message": "Windows 本地服务器数据库快照无法读取。",
                    "validation_source": "windows_snapshot",
                    "detail": type(exc).__name__,
                }
            if isinstance(local_result, dict):
                normalized = dict(local_result)
                normalized.setdefault("validation_source", "windows_snapshot")
                return normalized
            return {
                "success": False,
                "code": "invalid_db_response",
                "message": "Windows 本地服务器数据库返回了无效结果。",
                "validation_source": "windows_snapshot",
            }

        # A selected FTP profile is the authoritative source.  Always query
        # it first so a newly joined player or a renamed player is visible
        # immediately.  The Windows snapshot is intentionally not a fallback:
        # it can be older than the game database and would make admission and
        # sign-in appear randomly inconsistent.
        if profile_id:
            if not callable(portal_validate):
                return {
                    "success": False,
                    "code": "db_unavailable",
                    "message": "当前服务器数据库已绑定，但最新 FTP 查询服务未连接；为避免使用旧快照，暂不验证。",
                    "validation_source": "ftp_latest",
                }
            try:
                result = await portal_validate(group_id, profile_id, steam_id)
                if isinstance(result, dict):
                    normalized_result = dict(result)
                    result_code = str(normalized_result.get("code", "") or "").strip().lower()
                    if result_code == "found" and normalized_result.get("success") is not True:
                        normalized_result["success"] = True
                    normalized_result.setdefault("validation_source", "ftp_latest")
                    return normalized_result
                return {
                    "success": False,
                    "code": "invalid_db_response",
                    "message": "服务器数据库返回了无效结果。",
                    "validation_source": "ftp_latest",
                }
            except Exception as exc:
                code = str(getattr(exc, "code", "") or "db_unavailable").strip().lower()
                detail = str(getattr(exc, "detail", "") or "").strip()[:300]
                logger.warning(
                    "入群 SteamID 数据库验证失败 group=%s profile=%s code=%s detail=%s error=%s",
                    group_id,
                    profile_id,
                    code,
                    detail or "-",
                    type(exc).__name__,
                )
                return {
                    "success": False,
                    "code": code,
                    "message": detail or "无法读取当前 FTP 数据库，未使用旧快照，请稍后重试。",
                    "detail": detail,
                    "validation_source": "ftp_latest",
                }

        # Legacy/offline mode has no selected FTP profile.  Only in that mode
        # may the local snapshot be used; its source is surfaced to callers so
        # the UI can distinguish it from an authoritative live lookup.
        local_result = local_snapshot_validation()
        if local_result.get("success") is True:
            return local_result
        if not profile_id:
            local_result.setdefault("message", "当前群尚未选择服务器数据库，无法校验 SteamID。")
        return local_result

    @staticmethod
    def _steam_player_name_from_validation(validation: dict) -> str:
        """Extract a safe display name from a read-only DB lookup result."""
        player = validation.get("player") if isinstance(validation, dict) else None
        candidates = [player] if isinstance(player, dict) else []
        candidates.append(validation if isinstance(validation, dict) else {})
        for source in candidates:
            for key in (
                "user_name",
                "nick_name",
                "player_name",
                "display_name",
                "nickname",
                "name",
            ):
                value = str(source.get(key, "") or "").strip()
                if value:
                    return value[:60]
        return ""

    async def _set_group_card_from_game_name(
        self, group_id: str, user_id: str, game_name: str, bot=None
    ) -> bool:
        """Set the QQ group card after a SteamID admission succeeds."""
        game_name = str(game_name or "").strip()[:60]
        if not game_name:
            return False
        try:
            detail = get_group_feature_detail(group_id, "group_config", self.config)
            name_prefix = str(
                detail.get("member_name_prefix", "") if isinstance(detail, dict) else ""
            ).strip()
            include_prefix_for_admins = (
                detail.get("member_name_prefix_include_admins", True)
                if isinstance(detail, dict)
                else True
            )
            if isinstance(include_prefix_for_admins, str):
                include_prefix_for_admins = include_prefix_for_admins.strip().lower() not in {
                    "", "0", "false", "off", "no", "否", "关闭"
                }
            else:
                include_prefix_for_admins = bool(include_prefix_for_admins)
            is_admin_member = self._cached_member_role(group_id, user_id) in {"admin", "owner"}
            if name_prefix and (include_prefix_for_admins or not is_admin_member):
                game_name = apply_member_name_prefix(name_prefix, game_name)
        except Exception:
            # A missing legacy group config must not block SteamID binding;
            # the unprefixed game name remains a valid fallback.
            pass
        try:
            client = bot if callable(getattr(bot, "call_action", None)) else None
            if client is None:
                platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                client = platform.get_client() if platform else None
            if client is None:
                return False
            result = self._normalize_action_result(await client.call_action(
                action="set_group_card",
                group_id=int(group_id),
                user_id=int(user_id),
                card=game_name,
            ))
            return self._api_result_succeeded(result)
        except Exception as exc:
            logger.warning(
                "设置 Steam 游戏名群名片失败 group=%s user=%s error=%s",
                group_id,
                user_id,
                type(exc).__name__,
            )
            return False

    def _steam_name_as_group_card_enabled(self, group_id: str) -> bool:
        """Return whether this group initializes QQ cards from Steam names.

        The setting is intentionally independent from the database player name:
        disabling it only stops the QQ ``set_group_card`` action.
        """
        try:
            detail = get_group_feature_detail(group_id, "group_config", self.config)
        except Exception:
            # Keep existing behaviour if an older local config has no field.
            return True
        if not isinstance(detail, dict):
            return True
        value = detail.get("steam_name_as_group_card", True)
        if isinstance(value, str):
            return value.strip().lower() not in {"", "0", "false", "off", "no"}
        return bool(value)

    def _queue_group_card_update(
        self, group_id: str, user_id: str, game_name: str
    ) -> None:
        """Retry a QQ card update once the approved member actually joins."""
        normalized_name = str(game_name or "").strip()[:60]
        if normalized_name:
            self._pending_group_card_updates[f"{group_id}:{user_id}"] = {
                "name": normalized_name,
                "expires_at": time.time() + 300,
            }

    def _switch_steamid_to_random_fallback(
        self,
        group_id: str,
        user_id: str,
        *,
        reason: str = "",
        allowed_modes: tuple[str, ...] = ("math", "id"),
    ) -> dict:
        """Use a human-verification challenge whenever SteamID cannot verify.

        SteamID success is a strong proof of a real game player and approves the
        request directly. Any failure must not label the applicant a bot: the
        request moves to an independent human-verification step instead.
        """
        from .qqadmin.audit import (
            create_id_challenge,
            create_math_challenge,
            switch_pending_approval_mode,
        )

        # Direct approval is excluded here because it would approve a failed
        # SteamID lookup without proving a person operates the QQ account.
        # SteamID lookup failures must remain automatic.  Manager approval
        # codes create a second manual gate and are deliberately excluded.
        modes = tuple(mode for mode in allowed_modes if mode in {"math", "id"})
        if not modes:
            return {"success": False, "message": "没有可用的备用真人验证方式"}
        mode = random.choice(modes)
        challenge_info = {}
        if mode == "math":
            challenge_info = create_math_challenge(group_id, user_id)
        elif mode == "id":
            challenge_info = create_id_challenge(group_id, user_id)
        result = switch_pending_approval_mode(
            group_id, user_id, mode, challenge_info
        )
        if result.get("success"):
            result["fallback_reason"] = str(reason or "steamid_validation_failed")
        return result

    async def _activate_steamid_request_fallback(
        self,
        event: AstrMessageEvent,
        group_id: str,
        user_id: str,
        flag: str,
        *,
        reason: str,
    ) -> bool:
        """Switch a failed pre-join SteamID check to a real-person gate.

        Applicants are not group members while a request is pending, so a
        math/ID challenge first approves the request and then shows the
        challenge in the group.  The pending audit record stays open until
        that automatic human-verification fallback is completed.
        """

        fallback = self._switch_steamid_to_random_fallback(
            group_id, user_id, reason=reason, allowed_modes=("math", "id")
        )
        if not fallback.get("success"):
            await self._send_plain(
                event,
                self._steamid_failure_message({"code": reason})
                + "\n备用数学/ID 人机验证创建失败，请联系管理员处理。",
            )
            return False

        fallback_mode = str(fallback.get("approval_mode", "") or "")
        # This path is automatic by design: a failed SteamID check may only
        # use the math/ID human gates.  Never render or execute an approval
        # code fallback, even if stale data or a hot-reloaded helper returns
        # an unexpected mode.
        if fallback_mode not in {"math", "id"}:
            logger.error(
                "SteamID 备用审核返回非法模式 group=%s user=%s mode=%s",
                group_id,
                user_id,
                fallback_mode or "<empty>",
            )
            await self._send_plain(
                event,
                self._steamid_failure_message({"code": reason})
                + "\n备用数学/ID 人机验证创建失败，请稍后重试。",
            )
            return False

        try:
            platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
            if not platform:
                raise RuntimeError("platform_unavailable")
            approved = await platform.get_client().call_action(
                action="set_group_add_request",
                flag=flag,
                sub_type="add",
                approve=True,
            )
            if not self._api_result_succeeded(approved):
                raise RuntimeError("qq_approval_rejected")
            # Let OneBot publish the group-join notice before mentioning
            # the applicant in the challenge message.
            await asyncio.sleep(0.5)
        except Exception as exc:
            logger.warning(
                "SteamID 备用真人验证入群批准失败 group=%s user=%s error=%s",
                group_id, user_id, type(exc).__name__,
            )
            await self._send_plain(
                event,
                "SteamID 未确认，备用数学/ID验证已创建，但入群审批失败，请稍后重试。",
            )
            return False

        from .qqadmin.audit import get_verification_timeout

        await self._send_plain(
            event,
            self._steamid_fallback_prompt(
                fallback, timeout=get_verification_timeout(group_id)
            ),
        )
        logger.info(
            "入群 SteamID 未确认，已切换真人验证 group=%s user=%s mode=%s code=%s",
            group_id, user_id, fallback_mode, reason,
        )
        return True

    @staticmethod
    def _steamid_failure_message(validation: dict, steam_id: str = "") -> str:
        """Turn a SteamID/database result into an actionable user message."""
        result = validation if isinstance(validation, dict) else {}
        code = str(result.get("code", "") or "unknown").strip().lower()
        submitted = str(steam_id or "").strip()
        if code == "invalid_steam_id":
            return "SteamID 格式错误：必须是 17 位 SteamID64 数字。"
        if code == "not_found":
            suffix = f"（{submitted}）" if submitted else ""
            return (
                f"数据库查询完成，但没有找到 SteamID{suffix}。"
                "请确认使用的是该服务器的 17 位 SteamID64，且玩家已经进入过服务器。"
            )
        if code == "steam_in_use":
            return (
                "数据库查询成功，但该 SteamID 已绑定其他 QQ。"
                "为防止冒用，系统没有覆盖原绑定；请管理员先删除旧绑定后再提交。"
            )
        if code == "user_already_bound":
            return (
                "数据库查询成功，但当前 QQ 已绑定其他 SteamID。"
                "为防止覆盖，系统没有修改原绑定；请管理员先删除旧绑定。"
            )
        if code == "already_bound":
            return "数据库查询成功，该 SteamID 已绑定当前 QQ，本次按重复提交处理。"
        if code in {"schema_error", "invalid_db_response"}:
            return "数据库已连接，但表结构不符合 SCUM 数据库格式，无法读取玩家记录。"
        if code == "ambiguous":
            return "数据库查询到多条相同 SteamID 记录，为避免绑定错误，本次未通过。"
        if code in {"database_snapshot_missing", "steam_database_unavailable"}:
            return "Windows 尚未取得当前服务器的 FTP 数据库快照，请先完成 FTP 下载并同步后重试。"
        if code in {"group_authorization_expired", "sync_authentication"}:
            return "网页同步授权已过期，Windows 暂时无法读取 FTP 数据库，请重新同步网页授权。"
        if code in {"db_unavailable", "ftp_unavailable"}:
            detail = str(result.get("message", "") or "").strip()
            if "快照" in detail or str(result.get("validation_source", "")).startswith("windows"):
                return "Windows 本地 FTP 数据库快照不可用，请确认数据库已下载且文件可读。"
            return "数据库暂时不可用：Linux/FTP 未能下载或打开数据库文件，请检查 FTP 地址、端口、路径和权限。"
        if code in {"query_error", "database_query_failed"}:
            detail = str(result.get("message", "") or "").strip()
            if "下载" in detail or "FTP" in detail.upper():
                return "FTP 数据库下载或读取失败，请检查远程数据库路径和文件是否被占用。"
            return "数据库连接成功但查询执行失败，请检查 user_list 表和 SteamID 字段。"
        detail = str(result.get("message", "") or "").strip()
        if detail:
            return f"SteamID 数据库验证失败：{detail}"
        return f"SteamID 数据库验证失败（{code}），请联系管理员检查数据库配置。"

    @staticmethod
    def _steamid_failure_label(reason: str) -> str:
        """Short reason used in the fallback challenge heading."""
        labels = {
            "invalid_steam_id": "SteamID 格式不正确",
            "not_found": "数据库查询完成，但未找到该 SteamID",
            "db_unavailable": "数据库暂时不可用",
            "database_snapshot_missing": "Windows 尚未取得 FTP 数据库快照",
            "query_error": "数据库查询执行失败",
            "schema_error": "数据库表结构不符合 SCUM 格式",
            "ambiguous": "数据库存在重复 SteamID 记录",
            "group_authorization_expired": "网页同步授权已过期",
        }
        return labels.get(str(reason or "").strip().lower(), "数据库暂时无法确认该 SteamID")

    @staticmethod
    def _steamid_fallback_prompt(result: dict, *, timeout: int = 300) -> str:
        """Render the selected fallback challenge without exposing answers."""
        mode = str(result.get("approval_mode", "") or "")
        info = result.get("challenge_info")
        info = info if isinstance(info, dict) else {}
        minutes = max(1, int(timeout) // 60)
        reason = str(result.get("fallback_reason", "") or "")
        intro = str(result.get("failure_message", "") or "").strip()
        if not intro:
            intro = MyPlugin._steamid_failure_label(reason)
        if mode == "math":
            return (
                f"{intro}，已随机切换为数学验证。\n"
                f"请计算：{info.get('question', '')}\n"
                f"请在 {minutes} 分钟内使用 /回答验证 <答案> 完成验证。"
            )
        if mode == "id":
            return (
                f"{intro}，已随机切换为 ID 验证。\n"
                f"验证 ID：{info.get('verify_id', '')}\n"
                f"请在 {minutes} 分钟内使用 /回答验证 <验证ID> 完成验证。"
            )
        if mode == "code":
            return (
                f"{intro}，已随机切换为管理员审批。\n"
                f"审批码：{result.get('approval_code', '')}\n"
                f"管理员请在 {minutes} 分钟内使用 /同意 <审批码>。"
            )
        return f"{intro}，请联系管理员完成入群审核。"

    def _steam_binding_requires_database(self, group_id: str) -> bool:
        """Return whether any enabled Steam sign-in path needs DB validation.

        WebSocket-only game sign-in does not need the local SQLite/FTP
        snapshot just to bind a 17-digit SteamID.  Database-backed schemes do
        need validation, including when they coexist with WebSocket schemes.
        """
        try:
            policy = self._get_signin_policy(group_id)
        except Exception:
            return True
        if str(policy.get("signin_mode", "basic")).strip().lower() == "steam":
            reward_mode = self._steam_reward_mode(policy)
            if reward_mode == "database" or bool(policy.get("database_sync", False)):
                return True
        for profile in policy.get("signin_profiles", []):
            if not isinstance(profile, dict) or not profile.get("enabled", True):
                continue
            if str(profile.get("signin_mode", profile.get("mode", "basic"))).strip().lower() != "steam":
                continue
            reward_mode = self._steam_reward_mode(profile)
            if reward_mode == "database" or bool(profile.get("database_sync", False)):
                return True
        return False

    def _get_steam_database_adapter(
        self,
        group_id: str,
        policy: dict | None = None,
        reward_config: dict | None = None,
    ):
        """Build the write callback used by Steam-mode sign-in.

        The callback closes over one resolved path, preventing a request from
        switching databases between validation and reward.  Currency names
        are allow-listed by the adapter as a second line of defence.
        """
        database_path = self._get_steam_database_path(group_id)
        if database_path is None:
            return None
        policy = policy if isinstance(policy, dict) else {}
        requested_currency = str(
            policy.get("currency_column", policy.get("database_currency", "amount"))
            or "amount"
        ).strip().casefold()
        currency = (
            requested_currency
            if requested_currency in ALLOWED_CURRENCY_COLUMNS
            else "amount"
        )
        schedule_mode = str(policy.get("schedule_mode", "daily") or "daily").strip().lower()
        if schedule_mode not in {"daily", "weekly", "monthly"}:
            schedule_mode = "daily"

        def write_reward(
            steam_id: str,
            reward: int,
            *,
            player_name: str = "",
            sign_date: str = "",
        ) -> dict:
            return apply_signin_reward(
                database_path,
                steam_id,
                reward,
                player_name=player_name,
                sign_date=sign_date,
                currency_column=currency,
                period_mode=schedule_mode,
                reward_config=reward_config,
            )

        # Keep the upload metadata on the callback instead of expanding the
        # public stats adapter contract.  The async command layer uses it to
        # publish the committed Windows snapshot back to the matching FTP
        # profile; legacy local databases simply have no profile metadata.
        database_profile = str(policy.get("database_profile", "") or "").strip()
        snapshot_revision = 0
        snapshot_sha256 = ""
        database_path_resolved = None
        try:
            database_path_resolved = Path(str(database_path)).resolve()
        except (OSError, RuntimeError, TypeError, ValueError):
            pass
        for descriptor in policy.get("database_profiles", []):
            if not isinstance(descriptor, dict):
                continue
            descriptor_id = str(
                descriptor.get("id", descriptor.get("profile_id", "")) or ""
            ).strip()
            descriptor_path = str(
                descriptor.get("path", descriptor.get("database_path", "")) or ""
            ).strip()
            if database_profile and descriptor_id != database_profile:
                continue
            if not database_profile and descriptor_path:
                try:
                    descriptor_candidate = Path(descriptor_path)
                    if not descriptor_candidate.is_absolute():
                        descriptor_candidate = Path(__file__).resolve().parent / descriptor_candidate
                    descriptor_candidate = descriptor_candidate.resolve()
                    if (
                        database_path_resolved is None
                        or descriptor_candidate != database_path_resolved
                    ):
                        continue
                except (OSError, RuntimeError, TypeError, ValueError):
                    continue
            database_profile = descriptor_id
            try:
                snapshot_revision = int(descriptor.get("snapshot_revision", 0) or 0)
            except (TypeError, ValueError, OverflowError):
                snapshot_revision = 0
            snapshot_sha256 = str(descriptor.get("snapshot_sha256", "") or "").strip().lower()
            break
        write_reward.database_path = str(database_path)
        write_reward.database_profile = database_profile
        write_reward.database_snapshot_revision = snapshot_revision
        write_reward.database_snapshot_sha256 = snapshot_sha256

        return write_reward

    async def _upload_database_reward_snapshot(
        self,
        group_id: str,
        database_adapter: object,
    ) -> dict:
        """Publish a committed database reward to the group's FTP source."""

        client = getattr(self, "_portal_sync_client", None)
        profile_id = str(getattr(database_adapter, "database_profile", "") or "").strip()
        database_path = str(getattr(database_adapter, "database_path", "") or "").strip()
        try:
            revision = int(getattr(database_adapter, "database_snapshot_revision", 0) or 0)
        except (TypeError, ValueError, OverflowError):
            revision = 0
        snapshot_sha256 = str(
            getattr(database_adapter, "database_snapshot_sha256", "") or ""
        ).strip().lower()
        if client is None or not profile_id or revision <= 0 or not snapshot_sha256:
            return {
                "success": True,
                "skipped": True,
                "reason": "当前群未配置可回传的 FTP 数据库",
            }
        try:
            result = await client.upload_database_snapshot(
                group_id,
                profile_id,
                database_path,
                revision,
                snapshot_sha256,
            )
        except Exception as exc:
            logger.exception(
                "数据库签到回传 FTP 失败 group=%s profile=%s",
                group_id,
                profile_id,
            )
            reason_code = str(getattr(exc, "code", "") or "").strip().lower()
            return {
                "success": False,
                "code": "database_snapshot_upload_failed",
                "message": "数据库已在 Windows 本地更新，但回传服务器数据库失败。",
                "reason_code": reason_code,
                "detail": type(exc).__name__,
            }
        return {"success": True, "skipped": False, **(result if isinstance(result, dict) else {})}

    def _get_steam_database_reset_adapter(
        self,
        group_id: str,
        policy: dict | None = None,
    ):
        """Build the path-scoped callback used by administrator reset flows."""
        database_path = self._get_steam_database_path(group_id)
        if database_path is None:
            return None
        policy = policy if isinstance(policy, dict) else {}
        requested_currency = str(
            policy.get("currency_column", policy.get("database_currency", "amount"))
            or "amount"
        ).strip().casefold()
        currency = requested_currency if requested_currency in ALLOWED_CURRENCY_COLUMNS else "amount"

        def reset_record(
            steam_id: str,
            sign_date: str,
            *,
            reward: object = None,
            remove_reward: bool = True,
            **_ignored,
        ) -> dict:
            return reset_signin_record(
                database_path,
                steam_id,
                sign_date,
                currency_column=currency,
                reward=reward,
                remove_reward=remove_reward,
            )

        return reset_record

    def _get_steam_database_status(
        self,
        group_id: str,
        steam_id: str,
        policy: dict | None = None,
    ) -> dict:
        """Read balance/sign-log status for a bound Steam player."""
        database_path = self._get_steam_database_path(group_id)
        if database_path is None:
            return {
                "success": False,
                "code": "db_unavailable",
                "message": "服务器数据库暂不可用。",
            }
        policy = policy if isinstance(policy, dict) else {}
        requested_currency = str(
            policy.get("currency_column", policy.get("database_currency", "amount"))
            or "amount"
        ).strip().casefold()
        currency = (
            requested_currency
            if requested_currency in ALLOWED_CURRENCY_COLUMNS
            else "amount"
        )
        return read_player_status(
            database_path,
            steam_id,
            currency_column=currency,
        )

    @staticmethod
    def _render_signin_template(template: object, values: dict[str, object]) -> str:
        """Render a small, forgiving variable set without format-string crashes."""
        text = str(template or "").strip()
        if not text:
            return ""
        for key, value in values.items():
            text = text.replace("{" + str(key) + "}", str(value))
        return text[:2000]

    def _group_reply_template(
        self,
        group_id: str,
        feature_key: str,
        field_key: str,
        values: dict[str, object] | None,
        default: str,
    ) -> str:
        """Read one group-owned reply template with a runtime-safe fallback."""
        template: object = default
        try:
            detail = get_group_feature_detail(group_id, feature_key, self.config)
            if isinstance(detail, dict) and str(detail.get(field_key, "") or "").strip():
                template = detail[field_key]
        except Exception:
            logger.debug(
                "读取群回复模板失败: group=%s feature=%s field=%s",
                group_id,
                feature_key,
                field_key,
                exc_info=True,
            )
        # Older group settings may still contain the old group-name wording.
        # Moderation confirmations intentionally identify the target member,
        # never the group, so fall back to the new safe default during rollout.
        requires_member_name = (
            (feature_key == "mute" and field_key in {"mute_success_message", "unmute_success_message"})
            or (feature_key == "blacklist" and field_key in {"blacklist_success_message", "unblacklist_success_message"})
        )
        if requires_member_name and not any(
            token in str(template or "") for token in ("{user_name}", "{member_name}")
        ):
            template = default
        return self._render_signin_template(template, values or {}) or default

    @staticmethod
    def _signin_database_is_authoritative(policy: object) -> bool:
        """Whether local JSON must never mask a database read failure."""
        return MyPlugin._signin_backend(policy) == "database"

    @staticmethod
    def _signin_backend(policy: object) -> str:
        """Select exactly one sign-in side-effect backend.

        ``database_sync`` is retained as a legacy alias for database mode,
        but it is intentionally ignored when a Steam profile explicitly uses
        WebSocket rewards.  This keeps database transactions and game command
        execution mutually exclusive and prevents a WebSocket sign-in from
        downloading or uploading an SQLite snapshot.
        """
        detail = policy if isinstance(policy, dict) else {}
        mode = str(detail.get("signin_mode", "basic") or "basic").strip().lower()
        if mode == "steam":
            reward_mode = MyPlugin._steam_reward_mode(detail)
            return "database" if reward_mode == "database" else "websocket"
        raw_sync = detail.get("database_sync", False)
        if isinstance(raw_sync, str):
            raw_sync = raw_sync.strip().lower() not in {
                "",
                "0",
                "false",
                "off",
                "no",
            }
        return "database" if bool(raw_sync) else "local"

    @staticmethod
    def _steam_reward_mode(policy: object) -> str:
        detail = policy if isinstance(policy, dict) else {}
        mode = str(
            detail.get("steam_reward_mode", detail.get("reward_mode", "database"))
            or "database"
        ).strip().lower()
        return mode if mode in {"database", "websocket"} else "database"

    async def _execute_steam_signin_reward(
        self,
        event: AstrMessageEvent,
        *,
        group_id: str,
        user_id: str,
        user_name: str,
        steam_id: str,
        reward: int,
        policy: dict,
    ) -> dict:
        """Execute a Steam sign-in reward using the configured game adapter.

        The adapter may be local or backed by the authenticated WebSocket
        worker.  The command is rendered from the current group's binding;
        callers cannot supply a different SteamID.
        """
        template = str(
            policy.get("steam_reward_command", "")
            or "#ChangeCurrencyBalance Normal {reward} {steam_id}"
        ).strip()
        operation = str(
            policy.get("steam_reward_operation", "execute_game_command")
            or "execute_game_command"
        ).strip().lower()
        try:
            rendered_commands = resolve_game_commands(
                template,
                steam_id,
                user_id=user_id,
                user_name=user_name,
                group_id=group_id,
                reward=reward,
            )
        except ValueError as exc:
            logger.warning(
                "Steam 签到奖励指令无效 group=%s user=%s error=%s",
                group_id,
                user_id,
                type(exc).__name__,
            )
            return {"success": False, "code": "reward_command_invalid"}
        result = await self._execute_configured_game_commands(
            event,
            rendered_commands,
            group_id=group_id,
            user_id=user_id,
            steam_id=steam_id,
            operation=operation,
            prefer_websocket=True,
        )
        if not isinstance(result, dict):
            return {
                "success": False,
                "code": "invalid_executor_response",
                "message": "游戏执行端未返回可确认的执行结果。",
            }
        result = dict(result)
        result.setdefault("command", " | ".join(rendered_commands))
        return result

    @staticmethod
    def _database_monthly_signin_summary(
        database_status: object,
        *,
        today: object = None,
    ) -> dict[str, object]:
        """Convert ``read_player_status`` dates into the calendar payload."""
        status = database_status if isinstance(database_status, dict) else {}
        current_month = str(today or time.strftime("%Y-%m-%d"))[:7]
        if len(current_month) != 7 or current_month[4] != "-":
            current_month = time.strftime("%Y-%m")
        dates: list[str] = []
        seen: set[str] = set()
        raw_dates = status.get("sign_dates", [])
        if isinstance(raw_dates, (list, tuple, set)):
            for raw_date in raw_dates:
                value = str(raw_date or "").strip()
                # The database contract is ISO dates; trim timestamps from
                # legacy rows while rejecting malformed values.
                value = value[:10]
                if len(value) != 10 or value[:7] != current_month:
                    continue
                try:
                    # Avoid displaying impossible dates from a damaged row.
                    import datetime as _datetime

                    _datetime.date.fromisoformat(value)
                except (TypeError, ValueError):
                    continue
                if value not in seen:
                    seen.add(value)
                    dates.append(value)
        dates.sort()

        def _count(value: object, fallback: int = 0) -> int:
            try:
                return max(0, int(value))
            except (TypeError, ValueError, OverflowError):
                return fallback

        signin_days = _count(status.get("month_signins", len(dates)), len(dates))
        return {
            "month": current_month,
            "signin_days": signin_days,
            "dates": dates,
            "signed_today": bool(status.get("signed_today")),
            "consecutive_days": _count(status.get("consecutive_signins", 0)),
            "total_days": _count(status.get("total_signins", 0)),
        }

    @staticmethod
    def _database_status_has_calendar(database_status: object) -> bool:
        """Return whether a status payload carries usable sign-in history."""
        status = database_status if isinstance(database_status, dict) else {}
        if bool(status.get("sign_log_available")):
            return True
        raw_dates = status.get("sign_dates")
        return isinstance(raw_dates, (list, tuple, set)) and bool(raw_dates)

    def _signin_database_error_reply(
        self,
        policy: object,
        database_status: object,
        *,
        user_id: str = "",
        steam_id: str = "",
        group_id: str = "",
        use_custom_message: bool = True,
    ) -> str:
        """Render a safe, useful error instead of exposing stale local data."""
        detail = database_status if isinstance(database_status, dict) else {}
        settings = policy if isinstance(policy, dict) else {}
        values = {
            "name": user_id,
            "user_name": user_id,
            "qq": user_id,
            "user_id": user_id,
            "steam_id": steam_id or detail.get("steam_id", ""),
            "code": detail.get("code", ""),
            "group_id": group_id,
        }
        if use_custom_message:
            rendered = self._render_signin_template(
                settings.get("steam_database_error_message"), values
            )
            if rendered:
                return rendered
        rendered_default = self._render_signin_template(detail.get("message"), values)
        return rendered_default or "服务器数据库暂不可用，请稍后重试。"

    @filter.command("签到")
    async def do_signin(self, event: AstrMessageEvent, profile: str = "") -> None:
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "签到只能在群聊中使用")
            return
        if not self._check_feature_cached(event, self.qqadmin_enable_stats, "stats_enabled"):
            return
        if not await self._check_feature_permission_async(
            event, "stats", "use", required_sub_admin_permission="stats"
        ):
            yield self._yield_plain(event, "当前签到权限不足。")
            return
        user_id = self._get_sender_id_from_event(event)
        sender = getattr(event.message_obj, "sender", None)
        # Different OneBot/AstrBot versions expose card, nickname, or
        # user_name.  Use the persisted administrative name as a final
        # fallback so local签到 remains useful without FTP/member lookups.
        user_name = ""
        for field in ("card", "nickname", "user_name", "name"):
            value = getattr(sender, field, "") if sender is not None else ""
            if str(value or "").strip():
                user_name = str(value).strip()
                break
        user_name = user_name or get_user_name(group_id, user_id)
        
        selected_profile = str(profile or "").strip()
        if not selected_profile:
            # ``/签到`` is registered statically by AstrBot, therefore the
            # dynamic profile listener deliberately ignores that token.  If a
            # portal profile uses the built-in command (the documented
            # default), resolve it here so its mode/reward/window is actually
            # applied instead of silently falling back to legacy settings.
            base_policy = self._get_signin_policy(group_id)
            for configured_profile in base_policy.get("signin_profiles", []):
                if not isinstance(configured_profile, dict):
                    continue
                if not configured_profile.get("enabled", True):
                    continue
                command = str(
                    configured_profile.get("command", "") or ""
                ).strip().lstrip("/")
                if command == "签到":
                    selected_profile = str(configured_profile.get("id", "") or "")
                    break
        policy = self._get_signin_policy(group_id, selected_profile)
        if selected_profile and not policy.get("enabled", True):
            yield self._yield_plain(event, "该签到方案已关闭。")
            event.stop_event()
            return
        reward_config = self._get_signin_reward_config(group_id)
        for reward_key in (
            "base_reward",
            "reward_3_days",
            "reward_7_days",
            "reward_14_days",
            "reward_30_days",
        ):
            if selected_profile and reward_key in policy:
                reward_config[reward_key] = policy[reward_key]
        signin_mode = str(policy.get("signin_mode", "basic") or "basic").strip().lower()
        steam_reward_mode = self._steam_reward_mode(policy)
        signin_backend = self._signin_backend(policy)
        database_adapter = (
            self._get_steam_database_adapter(group_id, policy, reward_config)
            if signin_backend == "database"
            else None
        )
        database_required = signin_backend == "database"
        database_diagnostic = ""
        if database_required and database_adapter is None:
            # A portal transaction operates on the live Linux database and
            # does not need a Windows snapshot. Resolve that route first so a
            # healthy direct database sign-in never downloads and re-uploads
            # a stale copy of the file.
            descriptor = self._signin_database_descriptor(policy)
            profile_id = str(
                descriptor.get("id", descriptor.get("profile_id", "")) or ""
            ).strip()
            portal_client = getattr(self, "_portal_sync_client", None)
            if profile_id and callable(
                getattr(portal_client, "mutate_database_signin", None)
            ):
                database_adapter = SimpleNamespace(
                    database_profile=profile_id,
                    database_path="",
                    database_snapshot_revision=0,
                    database_snapshot_sha256="",
                )
            else:
                # A web save and the background snapshot worker are
                # independent. Fill this timing gap synchronously only for
                # legacy local-SQLite groups that have no direct profile.
                _database_path, database_diagnostic = await self._ensure_signin_database_snapshot(
                    group_id, policy
                )
                if _database_path is not None:
                    database_adapter = self._get_steam_database_adapter(
                        group_id, policy, reward_config
                    )
        signin_descriptor = self._signin_database_descriptor(policy)
        selected_database_profile = str(
            signin_descriptor.get("id", signin_descriptor.get("profile_id", "")) or ""
        ).strip()
        portal_database_mutation = getattr(
            getattr(self, "_portal_sync_client", None), "mutate_database_signin", None
        )
        if (
            database_required
            and selected_database_profile
            and not callable(portal_database_mutation)
        ):
            yield self._yield_plain(
                event,
                "当前签到数据库已绑定 FTP，但最新数据库写入服务未连接；为避免写入旧快照，本次签到未执行，请稍后重试。",
            )
            event.stop_event()
            return
        reward_result: dict = {}
        if signin_backend == "websocket":
            binding = get_steam_binding(group_id, user_id=user_id) or {}
            steam_id = str(binding.get("steam_id", "") or "").strip()
            if not steam_id:
                bind_command = self._get_signin_command_settings(group_id)["bind"]
                result = {
                    "success": False,
                    "code": "steam_id_required",
                    "message": f"请先使用 /{bind_command} <17位SteamID> 绑定账号，再进行签到。",
                }
            else:
                preview = preview_signin_reward(
                    group_id,
                    user_id,
                    reward_config=reward_config,
                    signin_policy=policy,
                )
                if not preview.get("success"):
                    result = preview
                else:
                    planned_reward = int(preview.get("reward", 0) or 0)
                    reward_result = await self._execute_steam_signin_reward(
                        event,
                        group_id=group_id,
                        user_id=user_id,
                        user_name=user_name,
                        steam_id=steam_id,
                        reward=planned_reward,
                        policy=policy,
                    )
                    if reward_result.get("success") is not True:
                        failure_message = str(
                            policy.get(
                                "steam_reward_failure_message",
                                "签到奖励执行失败，未完成本次签到，请稍后重试。",
                            )
                            or "签到奖励执行失败，未完成本次签到，请稍后重试。"
                        )
                        execution_reason = self._game_execution_reply(reward_result)
                        result = {
                            "success": False,
                            "code": reward_result.get("code", "steam_reward_failed"),
                            "message": f"{failure_message}\n原因：{execution_reason}",
                            "steam_id": steam_id,
                            "reward": planned_reward,
                            "reward_result": reward_result,
                        }
                    else:
                        # The game command owns the external reward.  Record
                        # the claim locally with zero QQ points so ordinary
                        # group-management currency is never mixed with the
                        # Steam economy.
                        record_policy = dict(policy)
                        record_policy["signin_mode"] = "basic"
                        record_policy["database_sync"] = False
                        zero_rewards = {
                            "base_reward": 0,
                            "reward_3_days": 0,
                            "reward_7_days": 0,
                            "reward_14_days": 0,
                            "reward_30_days": 0,
                        }
                        result = signin(
                            group_id,
                            user_id,
                            user_name,
                            reward_config=zero_rewards,
                            signin_policy=record_policy,
                            database_adapter=None,
                            backend="websocket",
                        )
                        if result.get("success") is True:
                            result["reward"] = planned_reward
                            result["reward_mode"] = "websocket"
                            result["reward_result"] = reward_result
                            result["steam_id"] = steam_id
                            result["message"] = (
                                f"签到成功！连续签到 {result.get('consecutive_days', 0)} 天，"
                                f"已通过游戏指令发放 {planned_reward} 奖励"
                            )
                        else:
                            result["reward_result"] = reward_result
                            result["steam_id"] = steam_id
                            result["message"] = (
                                "游戏奖励已执行，但签到记录保存失败，请联系管理员核对后再重试。"
                            )
        else:
            direct_database_result = None
            direct_database_client = getattr(
                getattr(self, "_portal_sync_client", None),
                "mutate_database_signin",
                None,
            )
            direct_database_enabled = bool(
                database_required
                and signin_backend == "database"
                and database_adapter is not None
                # Legacy groups may still use a local SQLite path without a
                # portal database profile. Keep their existing local flow;
                # the portal transaction endpoint requires an explicit
                # profile scope to prevent writes to the wrong server file.
                and str(getattr(database_adapter, "database_profile", "") or "").strip()
                and callable(direct_database_client)
            )
            if direct_database_enabled:
                binding = get_steam_binding(group_id, user_id=user_id) or {}
                steam_id = str(binding.get("steam_id", "") or "").strip()
                preview = preview_signin_reward(
                    group_id,
                    user_id,
                    reward_config=reward_config,
                    signin_policy=policy,
                )
                if not steam_id:
                    result = {
                        "success": False,
                        "code": "steam_id_required",
                        "message": "请先绑定 SteamID，再进行签到。",
                    }
                elif not preview.get("success"):
                    result = preview
                else:
                    try:
                        direct_database_result = await direct_database_client(
                            group_id,
                            str(getattr(database_adapter, "database_profile", "") or ""),
                            steam_id=steam_id,
                            reward=int(preview.get("reward", 0) or 0),
                            player_name=user_name,
                            sign_date=str(preview.get("sign_date", "") or ""),
                            currency_column=str(
                                policy.get("currency_column", policy.get("database_currency", "amount"))
                                or "amount"
                            ),
                            period_mode=str(policy.get("schedule_mode", "daily") or "daily"),
                            reward_config=reward_config,
                        )
                    except Exception as exc:
                        logger.exception(
                            "服务器数据库事务调用失败 group=%s profile=%s",
                            group_id,
                            getattr(database_adapter, "database_profile", ""),
                        )
                        portal_detail = str(getattr(exc, "detail", "") or "").strip()[:180]
                        portal_code = str(
                            getattr(exc, "code", "") or "database_mutation_failed"
                        ).strip()
                        failure_message = (
                            portal_detail
                            if portal_detail
                            else "服务器数据库事务调用失败，请稍后重试。"
                        )
                        direct_database_result = {
                            "success": False,
                            "code": portal_code,
                            "message": failure_message,
                            "detail": type(exc).__name__,
                        }
                    if (
                        isinstance(direct_database_result, dict)
                        and direct_database_result.get("success") is True
                    ):
                        # The portal has already committed the authoritative
                        # row. Reuse its response only to update the local QQ
                        # mirror; this callable never touches SQLite or FTP.
                        def committed_database_result(*_args, **_kwargs):
                            return dict(direct_database_result)

                        result = signin(
                            group_id,
                            user_id,
                            user_name,
                            reward_config=reward_config,
                            signin_policy=policy,
                            database_adapter=committed_database_result,
                            backend="database",
                        )
                        result["database_direct"] = True
                    else:
                        result = {
                            "success": False,
                            "code": (direct_database_result or {}).get(
                                "code", "database_mutation_failed"
                            ),
                            "message": (direct_database_result or {}).get(
                                "message", "服务器数据库事务未完成，本次签到未发放奖励。"
                            ),
                            "database_result": direct_database_result,
                            "steam_id": steam_id,
                        }
            elif database_required and database_adapter is None:
                result = {
                    "success": False,
                    "code": "steam_database_unavailable",
                    "message": "服务器数据库暂不可用，暂时无法发放签到奖励。",
                    "database_diagnostic": database_diagnostic,
                    "profile_id": policy.get("profile_id", ""),
                }
            else:
                result = signin(
                    group_id,
                    user_id,
                    user_name,
                    reward_config=reward_config,
                    signin_policy=policy,
                    database_adapter=database_adapter,
                    backend=signin_backend,
                )
        # The SQLite transaction is committed before this point.  For a
        # portal-managed FTP database, publish the exact committed file and
        # require the portal to acknowledge its new revision before reporting
        # a fully successful server reward.
        database_result = (
            result.get("database_result")
            if isinstance(result, dict) and isinstance(result.get("database_result"), dict)
            else {}
        )
        if (
            result.get("success") is True
            and database_result
            and database_adapter is not None
            and not result.get("database_direct")
        ):
            upload_result = await self._upload_database_reward_snapshot(
                group_id, database_adapter
            )
            result["database_upload_result"] = upload_result
            if upload_result.get("success") is not True:
                result["success"] = False
                result["code"] = "database_snapshot_upload_failed"
                result["reason_code"] = str(
                    upload_result.get("reason_code", "") or ""
                ).strip().lower()
                result["message"] = (
                    "本地数据库奖励已执行，但服务器数据库回传失败，"
                    "本次不发送签到成功消息；请检查 FTP 权限和同步状态。"
                )
            elif upload_result.get("skipped"):
                result["message"] = (
                    f"{result.get('message', '签到成功！')}\n"
                    "提示：当前群未关联服务器 FTP 数据库，仅更新了 Windows 本地数据库。"
                )
        # Never render a Steam success reply from the local sign-in record
        # alone.  The external side effect is authoritative and must return
        # an explicit boolean acknowledgement before the message is sent.
        if result.get("success") is True and signin_mode == "steam":
            external_result = (
                result.get("reward_result")
                if steam_reward_mode == "websocket"
                else result.get("database_result")
            )
            if not isinstance(external_result, dict) or external_result.get("success") is not True:
                result = dict(result)
                result["success"] = False
                result["code"] = "steam_operation_unconfirmed"
                result["message"] = (
                    "Steam 奖励执行结果未确认，本次不发送签到成功消息；"
                    "请检查游戏执行端或数据库后再重试。"
                )
        custom_message = ""
        if result.get("success") is True:
            now = time.strftime("%Y-%m-%d %H:%M:%S")
            binding = get_steam_binding(group_id, user_id=user_id) or {}
            database_result = (
                result.get("database_result")
                if isinstance(result.get("database_result"), dict)
                else {}
            )
            reward_result = (
                result.get("reward_result")
                if isinstance(result.get("reward_result"), dict)
                else {}
            )
            custom_message = self._render_signin_template(
                policy.get("signin_message"),
                {
                    "name": user_name or user_id,
                    "user_name": user_name or user_id,
                    "qq": user_id,
                    "user_id": user_id,
                    "steam_id": binding.get("steam_id", ""),
                    "count": database_result.get(
                        "total_signins", result.get("total_days", 0)
                    ),
                    "streak": database_result.get(
                        "consecutive_signins", result.get("consecutive_days", 0)
                    ),
                    "month_count": database_result.get(
                        "month_signins", binding.get("monthly_count", 0)
                    ),
                    "week_count": database_result.get(
                        "week_signins", binding.get("weekly_count", 0)
                    ),
                    "reward": result.get("reward", 0),
                    "time": now,
                    "date": now[:10],
                    "group_id": group_id,
                    "balance": result.get("database_balance", ""),
                    "database_balance": result.get("database_balance", ""),
                },
            )
            if database_result:
                add_operation_log(
                    group_id,
                    user_id,
                    user_name,
                    "数据库签到",
                    user_id,
                    user_name,
                    (
                        f"签到 {database_result.get('sign_date', now[:10])} | "
                        f"奖励 {result.get('reward', 0)}"
                    ),
                    before=database_result.get("before"),
                    after=database_result.get("after"),
                )
            elif reward_result:
                add_operation_log(
                    group_id,
                    user_id,
                    user_name,
                    "WebSocket游戏签到",
                    user_id,
                    user_name,
                    (
                        f"签到 {now[:10]} | SteamID {result.get('steam_id', '')} | "
                        f"奖励 {result.get('reward', 0)} | 指令执行成功"
                    ),
                    before=reward_result.get("before"),
                    after=reward_result.get("after"),
                )
            else:
                add_operation_log(
                    group_id,
                    user_id,
                    user_name,
                    "签到",
                    user_id,
                    user_name,
                    f"连续签到 {result.get('consecutive_days', 0)} 天 | 奖励 {result.get('reward', 0)}",
                )
        elif result.get("code") in {
            "steam_database_unavailable",
            "steam_database_error",
            "db_unavailable",
            "schema_error",
            "query_error",
            "not_found",
            "ambiguous",
            "database_mutation_failed",
            "database_mutation_conflict",
            "database_ftp_not_configured",
            "remote_mode_disabled",
            "group_not_bound",
            "invalid_database_snapshot_scope",
            "database_snapshot_missing",
        }:
            custom_message = self._render_signin_template(
                policy.get("database_reward_error_message")
                or policy.get("steam_database_error_message"),
                {
                    "name": user_name or user_id,
                    "user_name": user_name or user_id,
                    "qq": user_id,
                    "user_id": user_id,
                    "steam_id": result.get("steam_id", ""),
                    "reward": result.get("reward", ""),
                    "group_id": group_id,
                },
            )
            reason = self._signin_database_failure_reason(result)
            if reason and reason not in custom_message:
                custom_message = f"{custom_message or '签到奖励未完成。'}\n原因：{reason}"
        elif result.get("code") == "already_signed":
            custom_message = self._render_signin_template(
                policy.get("database_already_signed_message"),
                {
                    "name": user_name or user_id,
                    "user_name": user_name or user_id,
                    "qq": user_id,
                    "user_id": user_id,
                    "steam_id": result.get("steam_id", ""),
                    "group_id": group_id,
                },
            )
        reply = custom_message or result["message"]
        if result.get("success") is not True:
            failure_reason = self._signin_database_failure_reason(result)
            logger.warning(
                "签到未完成 group=%s user=%s profile=%s code=%s reason=%s",
                group_id,
                user_id,
                str(policy.get("profile_id", "") or ""),
                str(result.get("code", "signin_failed") or "signin_failed"),
                failure_reason[:300],
            )
            print_group_action(
                "签到失败",
                group_id,
                user_id=user_id,
                user_name=user_name,
                detail=f"方案 {str(policy.get('profile_name', policy.get('profile_id', '默认')) or '默认')}; {failure_reason[:300]}",
            )
        if result.get("success") and result.get("database_balance") is not None:
            # Keep custom templates intact; the balance suffix is useful for
            # the default reply and makes the database-backed reward visible.
            if not custom_message:
                reply = f"{reply}\n服务器余额: {result['database_balance']}"
        yield self._yield_plain(event, reply)
        event.stop_event()

    async def _schedule_group_steam_binding_recall(
        self, event: AstrMessageEvent, group_id: str, policy: dict
    ) -> None:
        """Recall a member's group SteamID message when the privacy switch is on."""
        if not bool(policy.get("recall_group_steam_binding_message", True)):
            return
        message_id = self._get_event_message_id(event)
        if message_id is None:
            return
        try:
            delay = max(0, min(int(policy.get("group_steam_binding_recall_seconds", 5) or 0), 600))
        except (TypeError, ValueError, OverflowError):
            delay = 5

        async def _recall_later() -> None:
            if delay:
                await asyncio.sleep(delay)
            await self._delete_msg(message_id, context=self.context, group_id=group_id)

        task = asyncio.create_task(_recall_later())
        task.add_done_callback(self._remove_recall_task)
        self._recall_tasks.add(task)

    async def _bind_steam_id_for_event(self, event: AstrMessageEvent, steam_id: str = ""):
        """Validate and bind a member's SteamID from group or private chat."""
        private_binding = not self._is_group_event(event)
        group_id = self._get_group_id_from_event(event) if not private_binding else ""
        submitted_value = str(steam_id or "").strip()
        private_member_info: dict = {}
        if private_binding:
            parts = submitted_value.split()
            if (
                len(parts) != 2
                or not re.fullmatch(r"[1-9][0-9]{4,11}", parts[0])
                or not re.fullmatch(r"[0-9]{17}", parts[1])
            ):
                yield self._yield_plain(
                    event,
                    "请私聊机器人发送：/绑定SteamID <群号> <17位SteamID64>。\n示例：/绑定SteamID 1102579807 76561198000000000",
                )
                return
            group_id, submitted_value = parts
            if not self._can_send_group_message(group_id):
                yield self._yield_plain(event, "该群未启用机器人服务或你填写的群号无效，无法私聊绑定。")
                return
            user_id = self._get_sender_id_from_event(event)
            try:
                platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                if not platform:
                    raise RuntimeError("platform_unavailable")
                member_result = await platform.get_client().call_action(
                    action="get_group_member_info",
                    group_id=int(group_id),
                    user_id=int(user_id),
                    no_cache=True,
                )
                if not self._api_result_succeeded(member_result):
                    raise RuntimeError("member_not_found")
                private_member_info = (
                    member_result.get("data", member_result)
                    if isinstance(member_result, dict)
                    else {}
                )
                if not isinstance(private_member_info, dict):
                    private_member_info = {}
            except Exception as exc:
                logger.info(
                    "私聊 SteamID 绑定成员核验失败 group=%s user=%s error=%s",
                    group_id, user_id, type(exc).__name__,
                )
                yield self._yield_plain(event, "无法确认你是该群成员；请确认群号正确且机器人已在群内。")
                return
        else:
            access_error = self._get_scum_group_access_error(event)
            if access_error:
                yield self._yield_scum_group_access_error(event, access_error)
                return
        policy = self._get_signin_policy(group_id)
        if not private_binding:
            # Recall sensitive group submissions before applying the group
            # binding permission gate.
            await self._schedule_group_steam_binding_recall(event, group_id, policy)
            if not bool(policy.get("allow_group_steam_binding", False)):
                yield self._yield_plain(
                    event,
                    f"请不要在群里发送 SteamID。请私聊机器人发送：/{self._get_signin_command_settings(group_id)['bind']} {group_id} <17位SteamID64>。\n群内消息将按隐私设置自动撤回。",
                )
                return
            if not await self._check_feature_permission_async(
                event, "stats", "use", required_sub_admin_permission="stats"
            ):
                yield self._yield_plain(event, "当前签到权限不足，无法绑定 SteamID。")
                return
        # SteamID association is a prerequisite for the optional sign-in
        # ledger, but it is not itself a statistics operation.  Keep binding
        # available when a group has disabled points/statistics; otherwise an
        # exact 17-digit ``/绑定id`` is silently swallowed by the stats gate.
        user_id = self._get_sender_id_from_event(event)
        sender = getattr(event.message_obj, "sender", None)
        user_name = ""
        for field in ("card", "nickname", "user_name", "name"):
            value = getattr(sender, field, "") if sender is not None else ""
            if str(value or "").strip():
                user_name = str(value).strip()
                break
        if not user_name and private_member_info:
            for field in ("card", "nickname", "user_name", "name"):
                value = private_member_info.get(field, "")
                if str(value or "").strip():
                    user_name = str(value).strip()
                    break
        user_name = user_name or get_user_name(group_id, user_id)
        database_validator = None
        validated_game_name = ""
        if self._steam_binding_requires_database(group_id):
            # Resolve the database exactly once through the same
            # Windows-authoritative FTP snapshot path used by SteamID admission. The
            # previous code captured one portal response and fed it to the
            # binder, so a transient HTTP error could never recover locally.
            resolved_validation = await self._validate_group_steam_id(
                group_id,
                submitted_value,
            )

            def validate_from_selected_database(_steam_id: str) -> dict:
                return dict(resolved_validation)

            database_validator = validate_from_selected_database
            validated_game_name = self._steam_player_name_from_validation(
                resolved_validation
            )
            if validated_game_name:
                user_name = validated_game_name
        result = bind_steam_id(
            group_id,
            user_id,
            submitted_value,
            user_name,
            database_validator=database_validator,
            source="command",
        )
        if result.get("success"):
            binding = result.get("binding", {}) if isinstance(result.get("binding"), dict) else {}
            # A normal SteamID bind is already performed by a member who is
            # in the group, so apply the database game name immediately. The
            # admission flow has its own equivalent below; keeping this here
            # fixes the gap where the binding was saved but the QQ group card
            # stayed at the old nickname.
            game_name = str(
                validated_game_name
                or binding.get("user_name", "")
                or ""
            ).strip()[:60]
            card_updated = False
            card_enabled = self._steam_name_as_group_card_enabled(group_id)
            if card_enabled and game_name and game_name != str(user_id):
                card_updated = await self._set_group_card_from_game_name(
                    group_id, user_id, game_name
                )
                if not card_updated:
                    self._queue_group_card_update(group_id, user_id, game_name)
                    logger.warning(
                        "SteamID 绑定成功但 QQ 群名片暂未更新，将在成员事件重试 "
                        "group=%s user=%s game_name=%s",
                        group_id,
                        user_id,
                        game_name,
                    )
            add_operation_log(
                group_id,
                user_id,
                user_name,
                "绑定SteamID",
                binding.get("steam_id", submitted_value),
                user_name,
                f"QQ {user_id} 绑定 SteamID",
            )
            message = self._render_signin_template(
                policy.get("bind_success_message"),
                {
                    "name": user_name or user_id,
                    "user_name": user_name or user_id,
                    "qq": user_id,
                    "user_id": user_id,
                    "steam_id": binding.get("steam_id", submitted_value),
                    "time": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "date": time.strftime("%Y-%m-%d"),
                    "group_id": group_id,
                },
            )
            if card_enabled and game_name:
                card_status = (
                    "群名片已设置为：" + game_name
                    if card_updated
                    else "群名片将在成员状态刷新后重试设置为：" + game_name
                )
                message = (message or "SteamID 绑定成功。") + "\n" + card_status
            yield self._yield_plain(event, message or "SteamID 绑定成功。")
        elif result.get("code") == "already_bound":
            # Treat a repeated command for the same QQ/SteamID as an
            # idempotent repair operation. This lets an existing binding pick
            # up the game-name card update after an earlier QQ API failure.
            binding = result.get("binding", {}) if isinstance(result.get("binding"), dict) else {}
            game_name = str(
                validated_game_name
                or binding.get("user_name", "")
                or ""
            ).strip()[:60]
            card_updated = False
            card_enabled = self._steam_name_as_group_card_enabled(group_id)
            if card_enabled and game_name and game_name != str(user_id):
                card_updated = await self._set_group_card_from_game_name(
                    group_id, user_id, game_name
                )
                if not card_updated:
                    self._queue_group_card_update(group_id, user_id, game_name)
            status = (
                "群名片已设置为：" + game_name
                if card_updated
                else (
                    "群名片将在成员状态刷新后重试设置为：" + game_name
                    if game_name
                    else ""
                )
            )
            if not card_enabled:
                status = ""
            yield self._yield_plain(
                event,
                "该 SteamID 已经绑定当前 QQ。" + ("\n" + status if status else ""),
            )
        elif result.get("code") in {
            "steam_in_use",
            "already_bound",
            "user_already_bound",
        } and policy.get("duplicate_steam_message"):
            yield self._yield_plain(event, self._render_signin_template(
                policy["duplicate_steam_message"],
                {"name": user_name or user_id, "user_name": user_name or user_id,
                 "qq": user_id, "user_id": user_id, "steam_id": submitted_value,
                 "group_id": group_id},
            ))
        elif result.get("code") == "not_found" and policy.get("steam_not_found_message"):
            yield self._yield_plain(event, self._render_signin_template(
                policy["steam_not_found_message"],
                {"name": user_name or user_id, "user_name": user_name or user_id,
                 "qq": user_id, "user_id": user_id, "steam_id": submitted_value,
                 "group_id": group_id},
            ))
        elif result.get("code") in {"db_unavailable", "schema_error", "query_error", "ambiguous"} and policy.get("steam_database_error_message"):
            yield self._yield_plain(event, self._render_signin_template(
                policy["steam_database_error_message"],
                {"name": user_name or user_id, "user_name": user_name or user_id,
                 "qq": user_id, "user_id": user_id, "steam_id": submitted_value,
                 "group_id": group_id},
            ))
        else:
            failure_message = self._render_signin_template(
                policy.get("bind_failure_message"),
                {
                    "name": user_name or user_id,
                    "user_name": user_name or user_id,
                    "qq": user_id,
                    "user_id": user_id,
                    "steam_id": submitted_value,
                    "message": result.get("message", "SteamID 绑定失败。"),
                    "code": result.get("code", "bind_failed"),
                    "time": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "date": time.strftime("%Y-%m-%d"),
                    "group_id": group_id,
                },
            )
            yield self._yield_plain(event, failure_message or result.get("message", "SteamID 绑定失败。"))
        event.stop_event()

    @filter.command("绑定SteamID", alias={"绑定steam", "绑定Steam", "绑定steamid"})
    async def bind_steam_signin_id(self, event: AstrMessageEvent, steam_id: str = "") -> None:
        """Bind a member's unique SteamID for groups that opt into Steam sign-in."""
        # Private binding is intentionally group-scoped by an explicit
        # ``<group_id> <steam_id>`` pair. The normal slash-prefix gate asks
        # for a group administrator when no group id exists, which used to
        # make private binding return an empty result before validation.
        private_event = not self._is_group_event(event)
        group_id = "" if private_event else self._get_group_id_from_event(event)
        if group_id:
            slash_allowed = await self._is_slash_prefix_allowed_async(event)
        else:
            slash_allowed = True
            # AstrBot versions differ in how many positional tokens are
            # passed to a command handler. Recover the complete private
            # argument from the original message so both tokens reach the
            # canonical validator.
            raw_message = self._get_event_message_text(event)
            if raw_message.startswith("/"):
                raw_parts = raw_message[1:].split(maxsplit=1)
                if len(raw_parts) > 1:
                    steam_id = raw_parts[1].strip()
            # Some users follow the private prompt with only the SteamID.
            # Resolve the single pending admission group before the common
            # validator enforces its explicit group-id format.
            if re.fullmatch(r"[0-9]{17}", str(steam_id or "").strip()):
                from .qqadmin.audit import get_pending_steamid_request_by_user_all_groups

                pending_group, pending_request = (
                    get_pending_steamid_request_by_user_all_groups(
                        self._get_sender_id_from_event(event)
                    )
                )
                if pending_group and isinstance(pending_request, dict):
                    steam_id = f"{pending_group} {str(steam_id).strip()}"
        if not slash_allowed:
            yield self._yield_plain(event, "当前账号没有执行 SteamID 绑定的权限。")
            event.stop_event()
            return
        if not self.enable_binding:
            yield self._yield_plain(event, "SteamID 绑定功能当前未开启，请联系群管理员。")
            event.stop_event()
            return
        try:
            async for result in self._bind_steam_id_for_event(event, steam_id):
                yield result
        finally:
            event.stop_event()

    @filter.command("查看SteamID绑定", alias={"绑定列表", "查看绑定", "SteamID绑定列表"})
    async def list_steam_signin_bindings(self, event: AstrMessageEvent) -> None:
        """List the QQ/SteamID associations for administrators."""
        if not await self._is_slash_prefix_allowed_async(event) or not self.enable_binding:
            event.stop_event()
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "查看 SteamID 绑定只能在群聊中使用。")
            event.stop_event()
            return
        if not await self._check_feature_permission_async(
            event, "stats", "modify", required_sub_admin_permission="stats"
        ):
            yield self._yield_plain(event, "当前签到管理权限不足，无法查看 SteamID 绑定。")
            event.stop_event()
            return
        rows = list_steam_bindings(group_id, limit=200)
        if not rows:
            yield self._yield_plain(event, "本群暂无 SteamID 绑定记录。")
            event.stop_event()
            return
        lines = [f"本群 SteamID 绑定（共 {len(rows)} 条）："]
        for index, row in enumerate(rows, 1):
            source = "入群验证" if row.get("source") == "admission" else "指令绑定"
            display_name = str(row.get("user_name", "") or "未设置").strip()
            lines.append(
                f"{index}. {display_name} | QQ {row.get('user_id', '-')} | "
                f"SteamID {row.get('steam_id', '-')} | 来源：{source}"
            )
        yield self._yield_plain(event, "\n".join(lines))
        event.stop_event()

    @filter.command("解绑SteamID", alias={"解绑steam", "解除SteamID", "删除SteamID", "删除绑定"})
    async def unbind_steam_signin_id(self, event: AstrMessageEvent, target: str = "") -> None:
        """Only the bot owner or QQ group owner may remove a SteamID binding."""
        if not await self._is_slash_prefix_allowed_async(event) or not self.enable_binding:
            event.stop_event()
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "SteamID 解绑只能在群聊中使用。")
            event.stop_event()
            return
        access_error = self._get_scum_group_access_error(event)
        if access_error:
            yield self._yield_scum_group_access_error(event, access_error)
            event.stop_event()
            return
        if not await self._check_feature_permission_async(
            event, "stats", "modify", required_sub_admin_permission="stats"
        ):
            yield self._yield_plain(event, "当前签到管理权限不足，无法解绑 SteamID。")
            return
        result = unbind_steam_id(group_id, target)
        if result.get("success"):
            binding = result.get("binding", {}) if isinstance(result.get("binding"), dict) else {}
            add_operation_log(
                group_id,
                self._get_sender_id_from_event(event),
                "",
                "解绑SteamID",
                binding.get("steam_id", ""),
                binding.get("user_id", ""),
                f"QQ {binding.get('user_id', '-')} 的 SteamID 绑定已删除",
            )
            binding_user_id = binding.get("user_id", "-")
            yield self._yield_plain(event, self._group_reply_template(
                group_id, "stats", "unbind_success_message",
                {"user_id": binding_user_id, "qq": binding_user_id,
                 "steam_id": binding.get("steam_id", ""), "group_id": group_id},
                "已解除 QQ {user_id} 的 SteamID 绑定。"))
        else:
            unbind_error = str(result.get("message") or "SteamID 解绑失败。")
            yield self._yield_plain(event, self._group_reply_template(
                group_id, "stats", "unbind_failure_message",
                {"user_id": target, "qq": target, "message": unbind_error,
                 "group_id": group_id},
                "SteamID 解绑失败：{message}"))
        event.stop_event()

    @filter.command("签到状态", alias={"我的签到"})
    async def show_signin_status(self, event: AstrMessageEvent) -> None:
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "签到状态只能在群聊中使用")
            return
        if not self._check_feature_cached(event, self.qqadmin_enable_stats, "stats_enabled"):
            return
        if not await self._check_feature_permission_async(
            event, "stats", "use", required_sub_admin_permission="stats"
        ):
            yield self._yield_plain(event, "当前签到权限不足。")
            return
        user_id = self._get_sender_id_from_event(event)
        policy = self._get_signin_policy(group_id)
        database_authoritative = self._signin_database_is_authoritative(policy)
        binding = get_steam_binding(group_id, user_id=user_id) or {}
        steam_id = str(binding.get("steam_id", "") or "").strip()
        if database_authoritative and not steam_id:
            bind_command = self._get_signin_command_settings(group_id)["bind"]
            yield self._yield_plain(
                event,
                self._signin_database_error_reply(
                    policy,
                    {
                        "code": "steam_id_required",
                        "message": f"请先使用 /{bind_command} <17位SteamID> 绑定账号，再查看数据库签到状态。",
                    },
                    user_id=user_id,
                    group_id=group_id,
                    use_custom_message=False,
                ),
            )
            event.stop_event()
            return
        status = get_signin_status(group_id, user_id)
        monthly = get_monthly_signin_summary(group_id, user_id)
        database_status = {}
        if steam_id and database_authoritative:
            database_status = self._get_steam_database_status(
                group_id,
                steam_id,
                policy,
            )
            if database_status.get("success"):
                status = dict(status)
                # A bound Steam/database profile uses the selected snapshot
                # as its status source; basic profiles may retain local
                # calendar counts when an old snapshot has no sign_log table.
                status.update(
                    {
                        "points": database_status.get("balance", status.get("points", 0)),
                        "database_balance": database_status.get("balance"),
                    }
                )
                if self._database_status_has_calendar(database_status) or database_authoritative:
                    status.update(
                        {
                            "signed_today": bool(database_status.get("signed_today")),
                            "database_total_signins": database_status.get("total_signins", 0),
                            "total_days": database_status.get(
                                "total_signins", status.get("total_days", 0)
                            ),
                            "consecutive_days": database_status.get(
                                "consecutive_signins", status.get("consecutive_days", 0)
                            ),
                        }
                    )
                    monthly = self._database_monthly_signin_summary(database_status)
            elif database_authoritative:
                yield self._yield_plain(
                    event,
                    self._signin_database_error_reply(
                        policy,
                        database_status,
                        user_id=user_id,
                        steam_id=steam_id,
                        group_id=group_id,
                    ),
                )
                event.stop_event()
                return
        signed = "今日已签到" if status["signed_today"] else "今日未签到"
        balance_line = (
            f"服务器余额: {status['database_balance']}"
            if "database_balance" in status
            else f"当前积分: {status['points']}"
        )
        yield self._yield_plain(
            event,
            f"{signed}\n连续签到: {status['consecutive_days']} 天\n"
            f"累计签到: {status['total_days']} 天\n"
            f"本月签到: {monthly['signin_days']} 天\n{balance_line}",
        )
        event.stop_event()

    @filter.command("签到日历", alias={"本月签到", "签到记录"})
    async def show_monthly_signin_calendar(self, event: AstrMessageEvent) -> None:
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "签到日历只能在群聊中使用")
            return
        if not self._check_feature_cached(event, self.qqadmin_enable_stats, "stats_enabled"):
            return
        if not await self._check_feature_permission_async(
            event, "stats", "use", required_sub_admin_permission="stats"
        ):
            yield self._yield_plain(event, "当前签到权限不足。")
            return

        user_id = self._get_sender_id_from_event(event)
        policy = self._get_signin_policy(group_id)
        database_authoritative = self._signin_database_is_authoritative(policy)
        binding = get_steam_binding(group_id, user_id=user_id) or {}
        steam_id = str(binding.get("steam_id", "") or "").strip()
        if database_authoritative and not steam_id:
            bind_command = self._get_signin_command_settings(group_id)["bind"]
            yield self._yield_plain(
                event,
                self._signin_database_error_reply(
                    policy,
                    {
                        "code": "steam_id_required",
                        "message": f"请先使用 /{bind_command} <17位SteamID> 绑定账号，再查看数据库签到日历。",
                    },
                    user_id=user_id,
                    group_id=group_id,
                    use_custom_message=False,
                ),
            )
            event.stop_event()
            return

        monthly = get_monthly_signin_summary(group_id, user_id)
        if steam_id and database_authoritative:
            database_status = self._get_steam_database_status(
                group_id,
                steam_id,
                policy,
            )
            if database_status.get("success") and (
                self._database_status_has_calendar(database_status)
                or database_authoritative
            ):
                monthly = self._database_monthly_signin_summary(database_status)
            elif database_authoritative:
                yield self._yield_plain(
                    event,
                    self._signin_database_error_reply(
                        policy,
                        database_status,
                        user_id=user_id,
                        steam_id=steam_id,
                        group_id=group_id,
                    ),
                )
                event.stop_event()
                return
        days = "、".join(value[-2:] for value in monthly["dates"]) or "暂无"
        today_status = "已签到" if monthly["signed_today"] else "未签到"
        yield self._yield_plain(
            event,
            f"签到日历 · {monthly['month']}\n"
            f"本月签到: {monthly['signin_days']} 天\n"
            f"日期: {days}\n"
            f"今日: {today_status} | 当前连签: {monthly['consecutive_days']} 天",
        )
        event.stop_event()

    @filter.command("重置签到", alias={"重置签到记录", "删除签到", "删除签到记录"})
    async def reset_signin_command(self, event: AstrMessageEvent) -> None:
        """管理员安全重置某个日期的签到记录/数据库奖励。"""
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "重置签到只能在群聊中使用")
            return
        if not await self._check_feature_permission_async(
            event, "stats", "modify", required_sub_admin_permission="stats"
        ):
            yield self._yield_plain(event, "当前签到管理权限不足，无法重置签到记录。")
            return
        text = (event.message_str or "").strip()
        parts = text.split()
        target_user = self._get_at_user_id(event)
        if not target_user:
            target_user = self._parse_user_id(
                text,
                ["/重置签到", "重置签到", "/重置签到记录", "重置签到记录", "/删除签到", "删除签到", "/删除签到记录", "删除签到记录"],
            )
        if not target_user:
            target_user = self._get_sender_id_from_event(event)
        sign_date = next(
            (part for part in parts if re.fullmatch(r"\d{4}-\d{2}-\d{2}", part)),
            "",
        )
        if not sign_date:
            yield self._yield_plain(event, "用法: /删除签到 @用户 YYYY-MM-DD [仅记录]（/重置签到 也可用）")
            return
        remove_reward = not any(part in {"仅记录", "只删记录", "不退奖励"} for part in parts)
        policy = self._get_signin_policy(group_id)
        signin_backend = self._signin_backend(policy)
        database_authoritative = signin_backend == "database"
        adapter = (
            self._get_steam_database_reset_adapter(group_id, policy)
            if database_authoritative
            else None
        )
        direct_reset_client = getattr(
            getattr(self, "_portal_sync_client", None),
            "reset_database_signin",
            None,
        )
        if database_authoritative and adapter is None:
            # Reset uses the same live Linux transaction as sign-in.  A
            # missing Windows snapshot must not disable the operation when a
            # valid remote database profile is configured.
            descriptor = self._signin_database_descriptor(policy)
            profile_id = str(
                descriptor.get("id", descriptor.get("profile_id", "")) or ""
            ).strip()
            if profile_id and callable(direct_reset_client):
                adapter = SimpleNamespace(database_profile=profile_id)
        direct_reset_enabled = bool(
            database_authoritative
            and adapter is not None
            and str(getattr(adapter, "database_profile", "") or "").strip()
            and callable(direct_reset_client)
        )
        if direct_reset_enabled:
            binding = get_steam_binding(group_id, user_id=str(target_user)) or {}
            steam_id = str(binding.get("steam_id", "") or "").strip()
            if not steam_id:
                result = {
                    "success": False,
                    "code": "steam_id_required",
                    "message": "目标用户尚未绑定 SteamID，无法删除服务器签到记录。",
                }
            else:
                try:
                    direct_result = await direct_reset_client(
                        group_id,
                        str(getattr(adapter, "database_profile", "") or ""),
                        steam_id=steam_id,
                        sign_date=sign_date,
                        remove_reward=remove_reward,
                        currency_column=str(
                            policy.get("currency_column", policy.get("database_currency", "amount"))
                            or "amount"
                        ),
                    )
                except Exception as exc:
                    logger.exception(
                        "服务器数据库签到重置调用失败 group=%s profile=%s",
                        group_id,
                        getattr(adapter, "database_profile", ""),
                    )
                    direct_result = {
                        "success": False,
                        "code": str(getattr(exc, "code", "") or "database_mutation_failed"),
                        "message": "服务器数据库重置失败，请稍后重试。",
                        "detail": type(exc).__name__,
                    }
                if isinstance(direct_result, dict) and direct_result.get("success") is True:
                    def committed_reset_result(*_args, **_kwargs):
                        return dict(direct_result)

                    result = reset_signin(
                        group_id,
                        str(target_user),
                        sign_date,
                        signin_policy=policy,
                        database_adapter=committed_reset_result,
                        remove_reward=remove_reward,
                        backend="database",
                    )
                    result["database_direct"] = True
                else:
                    result = {
                        "success": False,
                        "code": (direct_result or {}).get("code", "database_mutation_failed"),
                        "message": (direct_result or {}).get(
                            "message", "服务器数据库重置失败，本次未删除签到记录。"
                        ),
                        "database_result": direct_result,
                    }
        else:
            result = reset_signin(
                group_id,
                str(target_user),
                sign_date,
                signin_policy=policy,
                database_adapter=adapter,
                remove_reward=remove_reward,
                backend=signin_backend,
            )
        if result.get("success"):
            if self._steam_reward_mode(policy) == "websocket":
                detail = "仅删除本地签到记录，WebSocket 游戏奖励不会自动回滚"
            else:
                detail = "并退回数据库奖励" if remove_reward else "仅删除签到记录，未退回奖励"
            database_result = (
                result.get("database_result")
                if isinstance(result.get("database_result"), dict)
                else {}
            )
            add_operation_log(
                group_id,
                self._get_sender_id_from_event(event),
                "",
                "重置签到",
                str(target_user),
                "",
                (
                    f"签到 {sign_date} | "
                    f"奖励 {database_result.get('reward', 0) if database_result else 0} | "
                    f"{detail}"
                ),
                before=(
                    database_result.get("before")
                    if database_result and database_result.get("before") is not None
                    else result.get("before_points")
                ),
                after=(
                    database_result.get("after")
                    if database_result and database_result.get("after") is not None
                    else result.get("after_points")
                ),
            )
            yield self._yield_plain(event, self._group_reply_template(
                group_id, "stats", "signin_reset_success_message",
                {"user_id": target_user, "qq": target_user, "date": sign_date,
                 "detail": detail, "group_id": group_id},
                "签到重置成功：{user_id} {date}（{detail}）。"))
        else:
            reset_error = str(result.get("message") or "签到重置失败，请检查数据库审计记录。")
            yield self._yield_plain(event, self._group_reply_template(
                group_id, "stats", "signin_reset_failure_message",
                {"user_id": target_user, "qq": target_user, "date": sign_date,
                 "message": reset_error, "group_id": group_id},
                "签到重置失败：{message}"))
        event.stop_event()

