    @filter.command("定时播报", alias={"每日播报"})
    async def add_daily_broadcast(self, event: AstrMessageEvent) -> None:
        """Add a daily broadcast without requiring users to write cron fields."""
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "定时播报只能在群聊中使用")
            return
        if not self._can_send_group_message(group_id):
            return
        if not await self._check_feature_permission_async(event, "timed_message", "modify"):
            yield self._yield_plain(event, "仅管理员或群主可添加定时播报")
            return
        if not self._check_timed_message_enabled(group_id):
            yield self._yield_plain(event, "本群未启用定时消息功能")
            return

        raw_message = (event.message_str or "").strip().lstrip("/")
        command, separator, argument_text = raw_message.partition(" ")
        if command not in {"定时播报", "每日播报"} or not separator:
            yield self._yield_plain(
                event,
                "格式错误: /定时播报 HH:MM 内容\n"
                "或: /定时播报 @全体 HH:MM 内容\n"
                "一次性发送: /定时播报 YYYY-MM-DD HH:MM 内容\n"
                "时间使用 24 小时制，例如 09:30；按本群时区执行。",
            )
            return

        from .qqadmin.timed_message import (
            cron_from_daily_time,
            parse_daily_broadcast_arguments,
            parse_one_time_broadcast_arguments,
            parse_one_time_datetime,
        )

        one_time_arguments = parse_one_time_broadcast_arguments(argument_text)
        if one_time_arguments is not None and parse_one_time_datetime(one_time_arguments[0]):
            run_at_text, at_all, content = one_time_arguments
            if not content:
                yield self._yield_plain(event, "播报内容不能为空")
                return
            result = add_timed_message(
                group_id,
                content,
                "",
                at_all=at_all,
                enabled=True,
                operator_id=self._get_sender_id_from_event(event),
                name=f"一次性播报 {run_at_text}",
                action="message",
                run_at=run_at_text,
            )
            if result.get("success"):
                yield self._yield_plain(event, f"已添加一次性播报：{run_at_text}\n发送成功后自动关闭。")
            else:
                yield self._yield_plain(event, "添加失败，请重试。")
            event.stop_event()
            return

        parsed_arguments = parse_daily_broadcast_arguments(argument_text)
        if parsed_arguments is None:
            yield self._yield_plain(
                event,
                "格式错误: /定时播报 HH:MM 内容\n"
                "或: /定时播报 @全体 HH:MM 内容\n"
                "一次性发送: /定时播报 YYYY-MM-DD HH:MM 内容\n"
                "时间使用 24 小时制，例如 09:30；按本群时区执行。",
            )
            return

        time_text, at_all, content = parsed_arguments
        if not content:
            yield self._yield_plain(event, "播报内容不能为空")
            return

        cron_expr = cron_from_daily_time(time_text)
        if cron_expr is None:
            yield self._yield_plain(event, "时间格式应为 HH:MM，例如 09:30")
            return

        operator_id = self._get_sender_id_from_event(event)
        result = add_timed_message(
            group_id,
            content,
            cron_expr,
            at_all=at_all,
            enabled=True,
            operator_id=operator_id,
            name=f"每日播报 {time_text}",
            action="message",
        )
        if result.get("success"):
            at_all_text = "，@全体" if at_all else ""
            yield self._yield_plain(
                event,
                f"已添加每日播报: {time_text}{at_all_text}\n使用 /查看定时消息 管理任务",
            )
        else:
            yield self._yield_plain(event, "添加失败，请重试。")
        event.stop_event()

    @filter.command("添加定时消息")
    async def add_timed_msg(self, event: AstrMessageEvent) -> None:
        group_id = self._get_group_id_from_event(event)
        if not self._can_send_group_message(group_id):
            return
        if not await self._check_feature_permission_async(event, "timed_message", "modify"):
            yield self._yield_plain(event,"仅管理员/群主可添加定时消息")
            return
        
        if not self._check_timed_message_enabled(group_id):
            yield self._yield_plain(event,"本群未启用定时消息功能")
            return
        
        msg_str = event.message_str
        
        # 正确解析: 命令 名称 cron(5字段) 消息内容
        parts = msg_str.split()
        # 至少需要: 命令(1) + 名称(1) + cron(5) + 消息(1) = 8 个部分
        if len(parts) < 8:
            yield self._yield_plain(event,"格式错误: /添加定时消息 <名称> <分> <时> <日> <月> <周> <消息内容>\n示例: /添加定时消息 早安 0 9 * * * 大家早上好！\n时间顺序是：分钟(0-59) 小时(0-23) 日期 月份 星期(0-6)。")
            return
        
        name = parts[1]
        cron_expr = " ".join(parts[2:7])  # 取5个字段作为 cron 表达式
        message = " ".join(parts[7:])     # 保留正文中的单词间空格
        
        result = add_timed_message(group_id, message, cron_expr, at_all=False, enabled=True,
                                  operator_id=self._get_sender_id_from_event(event), name=name, action="message")
        
        if result["success"]:
            yield self._yield_plain(event,f"定时消息添加成功，ID: {result['id']}")
        else:
            yield self._yield_plain(event, "添加失败，请重试。")

    @filter.command("添加定时音乐")
    async def add_timed_music(self, event: AstrMessageEvent) -> None:
        """Add a cron task that randomly selects one music keyword."""
        group_id = self._get_group_id_from_event(event)
        if not self._can_send_group_message(group_id):
            return
        if not await self._check_feature_permission_async(event, "timed_message", "modify"):
            yield self._yield_plain(event, "仅管理员/群主可添加定时音乐")
            return
        if not self._check_timed_message_enabled(group_id):
            yield self._yield_plain(event, "本群未启用定时消息功能")
            return

        parts = str(event.message_str or "").split()
        if len(parts) < 8:
            yield self._yield_plain(
                event,
                "格式错误: /添加定时音乐 <名称> <分> <时> <日> <月> <周> <歌名|歌手|歌名>\n"
                "示例: /添加定时音乐 午间 0 12 * * * 晴天|稻香\n"
                "时间顺序是：分钟 小时 日期 月份 星期。",
            )
            return
        name = parts[1]
        cron_expr = " ".join(parts[2:7])
        music_pool = " ".join(parts[7:])
        try:
            from .qqadmin.entertainment import split_music_keywords

            split_music_keywords(music_pool, allow_empty=True)
        except (TypeError, ValueError) as exc:
            logger.warning("添加定时随机音乐失败: %s", exc, exc_info=True)
            yield self._yield_plain(event, "添加失败，请重试。")
            return
        result = add_timed_message(
            group_id,
            music_pool,
            cron_expr,
            at_all=False,
            enabled=True,
            operator_id=self._get_sender_id_from_event(event),
            name=name,
            action="random_music",
        )
        if result.get("success"):
            yield self._yield_plain(event, f"定时随机音乐添加成功，ID: {result['id']}")
        else:
            yield self._yield_plain(event, "添加失败，请重试。")

