    def _parse_member_name_command(
        self,
        event: AstrMessageEvent,
        command_names: tuple[str, ...],
    ) -> tuple[str | None, str]:
        """Parse ``<target> <display name>`` while supporting @ mentions.

        AstrBot adapters do not all put the numeric target in
        ``message_str``.  Prefer the structured ``At`` component and only
        fall back to a numeric/legacy CQ token in the text.
        """
        import re

        raw = (event.message_str or "").strip().lstrip("/").strip()
        payload = ""
        for command_name in sorted(command_names, key=len, reverse=True):
            if raw == command_name:
                payload = ""
                break
            prefix = command_name + " "
            if raw.startswith(prefix):
                payload = raw[len(prefix):].strip()
                break
        target_user_id = self._get_at_user_id(event)

        if target_user_id:
            # Remove the textual representation of the leading mention when
            # the adapter includes it in message_str as well as in the chain.
            payload = re.sub(
                r"^\s*(?:\[CQ:at,qq=\d+\]|\[At:\d+\]|@[^\s]+)\s*",
                "",
                payload,
                count=1,
            ).strip()
        else:
            target_match = re.match(
                r"^\s*(?:\[CQ:at,qq=(\d+)\]|\[At:(\d+)\]|@?(\d+))(?:\s+|$)",
                payload,
            )
            if target_match:
                target_user_id = next(
                    value for value in target_match.groups() if value
                )
                payload = payload[target_match.end():].strip()

        if not target_user_id:
            return None, ""
        return str(target_user_id).strip(), payload[:128].strip()

    def _get_group_action_client(self, group_id: str):
        """Return the QQ client that most recently handled this group."""
        normalized_group = self._normalize_positive_id(group_id)
        if not normalized_group:
            return None

        candidates = []
        seen_clients: set[int] = set()

        def add(candidate) -> None:
            if not callable(getattr(candidate, "call_action", None)):
                return
            marker = id(candidate)
            if marker in seen_clients:
                return
            seen_clients.add(marker)
            candidates.append(candidate)

        add(getattr(self, "_group_platform_bots", {}).get(normalized_group))
        known = getattr(self, "_group_platform_bot_candidates", {}).get(
            normalized_group, {}
        )
        if isinstance(known, dict):
            ordered = sorted(
                known.values(),
                key=lambda value: int(value.get("seen_at", 0) or 0)
                if isinstance(value, dict)
                else 0,
                reverse=True,
            )
            for value in ordered:
                add(value.get("bot") if isinstance(value, dict) else None)
        if candidates:
            return candidates[0]

        try:
            platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
            return platform.get_client() if platform else None
        except Exception:
            return None

    async def _is_bot_group_owner_async(self, group_id: str, client=None) -> bool:
        """Return whether the QQ account handling this group is the owner."""
        group_id = self._normalize_positive_id(group_id)
        if not group_id:
            return False
        client = client or self._get_group_action_client(group_id)
        now = time.monotonic()
        owner_cache = getattr(self, "_bot_group_owner_cache", {})
        cached = owner_cache.get(group_id)
        # Keep confirmed ownership cached, but retry a transient negative
        # result quickly because some adapters omit role fields while their
        # group cache is refreshing.
        cached_client_id = cached[2] if isinstance(cached, tuple) and len(cached) > 2 else None
        if (
            cached
            and client is not None
            and cached_client_id == id(client)
            and now - cached[1] < (300 if cached[0] else 30)
        ):
            return bool(cached[0])
        try:
            if not client:
                return False
            login_info = await client.call_action(action="get_login_info")
            if isinstance(login_info, dict):
                login_data = login_info.get("data")
                if not isinstance(login_data, dict):
                    login_data = login_info
                # OneBot returns ``{"data": {"user_id": ...}}`` on most
                # adapters, while a few older adapters put the field at the
                # top level.  Passing the whole mapping to the ID normalizer
                # (the old implementation) always produced an empty ID and
                # made every title grant look like a non-owner failure.
                bot_id = self._normalize_positive_id(
                    login_data.get("user_id")
                    or login_data.get("userId")
                    or login_data.get("qq")
                    or login_data.get("id")
                )
            else:
                bot_id = ""
            if not bot_id:
                return False
            member_info = await client.call_action(
                action="get_group_member_info",
                group_id=int(group_id),
                user_id=int(bot_id),
            )
            is_owner = self._extract_onebot_role(member_info) == "owner"
            owner_id = ""
            if not is_owner:
                # Several OneBot implementations omit the role from
                # get_group_member_info. The group owner ID is a reliable
                # fallback and avoids rejecting a real group-owner bot.
                group_info = await client.call_action(
                    action="get_group_info",
                    group_id=int(group_id),
                )
                pending = [group_info]
                visited: set[int] = set()
                while pending and not owner_id:
                    value = pending.pop(0)
                    marker = id(value)
                    if marker in visited:
                        continue
                    visited.add(marker)
                    if not isinstance(value, dict):
                        continue
                    owner_id = self._normalize_positive_id(
                        value.get("owner_id")
                        or value.get("ownerId")
                        or value.get("group_owner_id")
                        or value.get("groupOwnerId")
                        or value.get("owner_uin")
                        or value.get("ownerUin")
                        or value.get("group_owner_uin")
                        or value.get("groupOwnerUin")
                    )
                    for key in ("data", "result", "group", "group_info"):
                        nested = value.get(key)
                        if isinstance(nested, dict):
                            pending.append(nested)
                is_owner = bool(owner_id and owner_id == bot_id)
            if not is_owner and not owner_id:
                # NapCat/NTQQ can omit owner_id from get_group_info while
                # retaining it in get_group_member_list. This fallback is
                # cached and only runs when the normal role check is absent.
                try:
                    members_response = await client.call_action(
                        action="get_group_member_list", group_id=int(group_id)
                    )
                    for member in self._extract_onebot_records(members_response):
                        member_id = self._normalize_positive_id(
                            member.get("user_id")
                            or member.get("userId")
                            or member.get("id")
                        )
                        if (
                            member_id == bot_id
                            and self._extract_onebot_role(member) == "owner"
                        ):
                            is_owner = True
                            break
                except Exception as exc:
                    logger.debug(
                        "通过群成员列表检查机器人群主失败 group=%s: %s",
                        group_id,
                        type(exc).__name__,
                    )
            owner_cache[group_id] = (is_owner, now, id(client))
            self._bot_group_owner_cache = owner_cache
            return is_owner
        except Exception as exc:
            logger.warning("检查机器人群主身份失败 group=%s: %s", group_id, type(exc).__name__)
            owner_cache[group_id] = (False, now, id(client) if client is not None else None)
            self._bot_group_owner_cache = owner_cache
            return False

    @staticmethod
    def _parse_member_identity_rules(
        raw_rules: object, value_key: str, maximum_length: int
    ) -> dict[str, str]:
        """Normalize web/legacy QQ identity rules into ``{user_id: value}``."""
        if isinstance(raw_rules, str):
            serialized = raw_rules.strip()
            candidates: list[object]
            if serialized.startswith("["):
                try:
                    parsed = json.loads(serialized)
                except (TypeError, ValueError, json.JSONDecodeError):
                    parsed = None
                candidates = list(parsed) if isinstance(parsed, list) else serialized.splitlines()
            else:
                candidates = serialized.splitlines()
        elif isinstance(raw_rules, dict):
            candidates = [raw_rules]
        elif isinstance(raw_rules, (list, tuple)):
            candidates = list(raw_rules)
        else:
            return {}
        rules: dict[str, str] = {}
        for raw in candidates[:200]:
            item = raw if isinstance(raw, dict) else None
            if item is None:
                text = str(raw or "").strip()
                if not text:
                    continue
                if text.startswith("{"):
                    try:
                        item = json.loads(text)
                    except (TypeError, ValueError, json.JSONDecodeError):
                        item = None
                elif "=" in text:
                    user_id, value = text.split("=", 1)
                    item = {"user_id": user_id, value_key: value}
            if not isinstance(item, dict):
                continue
            raw_user_id = (
                item.get("user_id")
                or item.get("userId")
                or item.get("qq")
                or item.get("id")
            )
            # ``*``/``all`` is a deliberately narrow wildcard used by the
            # web form for a common card/title policy.  It is not treated as
            # a real QQ ID and is kept separate from normal numeric rules.
            wildcard = str(raw_user_id or "").strip().casefold()
            user_id = "*" if wildcard in {"*", "all", "everyone", "全体", "所有人"} else MyPlugin._normalize_positive_id(raw_user_id)
            value = str(item.get(value_key, "") or "").replace("\r", " ").replace("\n", " ").strip()
            if not user_id or not value or len(value) > maximum_length:
                continue
            rules[user_id] = value
        return rules

    def _upsert_member_identity_rule(
        self, group_id: str, user_id: str, value_key: str, value: str
    ) -> None:
        """Persist a manual card/title command in the per-group web config."""
        group_id = self._normalize_positive_id(group_id)
        user_id = self._normalize_positive_id(user_id)
        value = str(value or "").replace("\r", " ").replace("\n", " ").strip()
        if not group_id or not user_id or not value:
            return
        field_key = "member_names" if value_key == "name" else "member_titles"
        try:
            def update_rules(existing):
                rules = self._parse_member_identity_rules(existing, value_key, 60 if value_key == "name" else 18)
                rules[user_id] = value
                return [
                    json.dumps(
                        {"user_id": rule_user_id, value_key: rule_value},
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    for rule_user_id, rule_value in sorted(rules.items())
                ]

            update_group_feature_config(
                group_id,
                "group_config",
                field_key,
                update_rules(
                    get_group_feature_detail(group_id, "group_config", self.config).get(field_key, [])
                ),
                operator_id="command",
            )
        except Exception as exc:
            logger.debug("保存群员身份规则失败 group=%s user=%s: %s", group_id, user_id, type(exc).__name__)

    @staticmethod
    def _default_member_title_rules() -> list[str]:
        """Return the safe starter rule used when a group enables titles."""

        return [
            json.dumps(
                {"user_id": "*", "title": "群成员"},
                ensure_ascii=False,
                separators=(",", ":"),
            )
        ]

    def _remove_member_identity_rule(
        self, group_id: str, user_id: str, value_key: str
    ) -> None:
        """Remove one persisted card/title rule after QQ confirms removal."""
        group_id = self._normalize_positive_id(group_id)
        user_id = self._normalize_positive_id(user_id)
        if not group_id or not user_id:
            return
        field_key = "member_names" if value_key == "name" else "member_titles"
        maximum_length = 60 if value_key == "name" else 18
        try:
            detail = get_group_feature_detail(group_id, "group_config", self.config)
            rules = self._parse_member_identity_rules(
                detail.get(field_key, []) if isinstance(detail, dict) else [],
                value_key,
                maximum_length,
            )
            if user_id not in rules:
                return
            rules.pop(user_id, None)
            update_group_feature_config(
                group_id,
                "group_config",
                field_key,
                [
                    json.dumps(
                        {"user_id": rule_user_id, value_key: rule_value},
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    for rule_user_id, rule_value in sorted(rules.items())
                ],
                operator_id="command",
            )
        except Exception as exc:
            logger.debug(
                "删除群员身份规则失败 group=%s user=%s: %s",
                group_id,
                user_id,
                type(exc).__name__,
            )

    async def _apply_member_identity_policy(self, group_id: str, user_id: str) -> None:
        """Apply configured card/title rules for one member without chat noise."""
        group_id = self._normalize_positive_id(group_id)
        user_id = self._normalize_positive_id(user_id)
        if not group_id or not user_id:
            return
        try:
            detail = get_group_feature_detail(group_id, "group_config", self.config)
        except Exception:
            return
        if not isinstance(detail, dict):
            return

        def config_bool(value: object, default: bool = False) -> bool:
            if value is None:
                return default
            if isinstance(value, str):
                return value.strip().lower() not in {
                    "",
                    "0",
                    "false",
                    "off",
                    "no",
                }
            return bool(value)

        if not config_bool(detail.get("enabled"), True):
            return
        # The portal exposes independent switches for automatic card and
        # special-title updates.  Manual command changes are still persisted
        # even when a switch is off; ordinary messages only apply a rule when
        # its corresponding automatic policy is enabled.
        name_rules = self._parse_member_identity_rules(detail.get("member_names"), "name", 60)
        title_rules = self._parse_member_identity_rules(detail.get("member_titles"), "title", 18)
        include_prefix_for_admins = detail.get("member_name_prefix_include_admins", True)
        if isinstance(include_prefix_for_admins, str):
            include_prefix_for_admins = include_prefix_for_admins.strip().lower() not in {
                "", "0", "false", "off", "no", "否", "关闭"
            }
        else:
            include_prefix_for_admins = bool(include_prefix_for_admins)
        if not include_prefix_for_admins and self._cached_member_role(group_id, user_id) in {"admin", "owner"}:
            return
        binding = get_steam_binding(group_id, user_id=user_id) or {}
        bound_name = str(binding.get("user_name", "") or "").strip()
        member_name = (
            bound_name
            or self._cached_member_nickname(group_id, user_id)
            or str(get_user_name(group_id, user_id) or user_id).strip()
            or user_id
        )
        name_prefix = str(detail.get("member_name_prefix", "") or "").strip()
        name = (
            (name_rules.get(user_id) or name_rules.get("*"))
            if config_bool(detail.get("auto_member_name"), False)
            else None
        )
        if name_prefix:
            # A configured global prefix is itself an automatic group-card
            # policy and applies even when the per-member name switch is off.
            name = apply_member_name_prefix(name_prefix, name or member_name)
        title = (
            (title_rules.get(user_id) or title_rules.get("*"))
            if config_bool(detail.get("auto_member_title"), False)
            else None
        )
        if not name and not title:
            return
        try:
            client = self._get_group_action_client(group_id)
        except Exception as exc:
            logger.debug(
                "获取群成员身份策略客户端失败 group=%s user=%s error=%s",
                group_id,
                user_id,
                type(exc).__name__,
            )
            return
        if not client:
            return
        now = time.monotonic()
        cache = getattr(self, "_member_identity_apply_cache", {})

        failure_cache = getattr(self, "_member_identity_failure_cache", {})

        async def apply_action(kind: str, value: str, action: str, **params) -> None:
            cache_key = (group_id, user_id, kind, value)
            cached_at = cache.get(cache_key)
            if cached_at and now - cached_at < getattr(self, "_member_identity_cache_ttl", 21600):
                return
            failed_at = failure_cache.get(cache_key)
            if failed_at and now - failed_at < 600:
                return
            try:
                # NapCat/aiocqhttp may return an empty body for a successful
                # group-card or special-title action. Normalize that empty
                # success here; moderation actions keep strict result checks
                # at their own execution boundary.
                result = self._normalize_action_result(
                    await client.call_action(action=action, **params)
                )
                if not self._api_result_succeeded(result):
                    raise RuntimeError(self._onebot_failure_detail(result))
                cache[cache_key] = now
                failure_cache.pop(cache_key, None)
            except Exception as exc:
                # Do not make ordinary messages fail when a platform denies a
                # card/title update. Keep a short failure cooldown so a
                # rejected owner/title request cannot trigger on every chat.
                failure_cache[cache_key] = now
                detail = self._onebot_failure_detail(exc)
                if self._is_packet_backend_unavailable(exc):
                    detail = "NapCat packetBackend 不可用；QQ 未执行该群资料操作"
                logger.warning(
                    "自动设置群员身份失败 group=%s user=%s kind=%s detail=%s",
                    group_id,
                    user_id,
                    kind,
                    detail,
                )

        # Resolve the small set of documented placeholders without an extra
        # group-member API call.  The local sign-in name is already updated by
        # the normal member event path; QQ ID is the final deterministic
        # fallback for a brand-new member.
        def render_identity(value: str) -> str:
            rendered = str(value or "")
            replacements = {
                "{user_id}": user_id,
                "{qq}": user_id,
                "{user_name}": member_name,
                "{nickname}": member_name,
            }
            for token, replacement in replacements.items():
                rendered = rendered.replace(token, replacement)
            return rendered[:60]

        if name:
            name = render_identity(name)
            await apply_action(
                "name",
                name,
                "set_group_card",
                group_id=int(group_id),
                user_id=int(user_id),
                card=name,
            )
        if title:
            # QQ only permits special-title updates from the actual group
            # owner.  Check once before calling NapCat so an enabled wildcard
            # rule cannot produce a rejected packetBackend request for every
            # ordinary group message.
            if await self._is_bot_group_owner_async(group_id, client=client):
                title = render_identity(title)[:18]
                await apply_action(
                    "title",
                    title,
                    "set_group_special_title",
                    group_id=int(group_id),
                    user_id=int(user_id),
                    special_title=title,
                )
            else:
                logger.debug(
                    "自动授予称号跳过：机器人不是群主 group=%s user=%s",
                    group_id,
                    user_id,
                )
        self._member_identity_apply_cache = cache
        self._member_identity_failure_cache = failure_cache

    def _schedule_member_identity_policy(self, group_id: str, user_id: str) -> None:
        """Apply group-card rules without delaying message/command handling."""
        group_id = self._normalize_positive_id(group_id)
        user_id = self._normalize_positive_id(user_id)
        if not group_id or not user_id:
            return
        key = f"{group_id}:{user_id}"
        if key in self._member_identity_task_keys:
            return
        self._member_identity_task_keys.add(key)

        async def runner() -> None:
            try:
                await self._apply_member_identity_policy(group_id, user_id)
            except asyncio.CancelledError:
                raise
            except Exception:
                logger.debug(
                    "后台应用群员身份规则失败 group=%s user=%s",
                    group_id,
                    user_id,
                    exc_info=True,
                )
            finally:
                self._member_identity_task_keys.discard(key)

        task = asyncio.create_task(runner())
        self._member_identity_tasks.add(task)
        task.add_done_callback(self._member_identity_tasks.discard)

    @filter.command("群资料状态", alias={"群名片状态", "群称号状态"})
    async def group_member_profile_status_cmd(self, event: AstrMessageEvent) -> None:
        """Report the exact QQ/NapCat prerequisites for member card actions."""

        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能查看群资料状态。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        bot_is_owner = await self._is_bot_group_owner_async(group_id)
        detail = get_group_feature_detail(group_id, "group_config", self.config)
        detail = detail if isinstance(detail, dict) else {}
        lines = [
            f"群资料状态｜群 {group_id}",
            f"机器人群主：{'是' if bot_is_owner else '否或暂时无法确认'}",
            f"自动群名片：{'开启' if bool(detail.get('auto_member_name', False)) else '关闭'}",
            f"群名片全局前缀：{str(detail.get('member_name_prefix', '') or '') or '未设置'}",
            f"前缀修改管理员：{'是' if bool(detail.get('member_name_prefix_include_admins', True)) else '否'}",
            f"自动称号：{'开启' if bool(detail.get('auto_member_title', False)) else '关闭'}",
            "群名片：机器人需具备群管理权限。",
            "群称号：机器人必须是群主，且 NapCat PacketBackend 必须已初始化。",
            "操作：/设置群名片前缀 scum-｜/初始化群员名称｜/设置群员名称 <QQ> <名称>",
        ]
        if not bot_is_owner:
            lines.append("当前不执行自动称号；请先在 QQ 群资料中确认机器人账号的身份为群主。")
        else:
            lines.append("若授予称号仍提示 packetBackend，请检查 NapCat 启动日志的 PacketBackend 状态。")
        yield self._yield_plain(event, "\n".join(lines))

    @filter.command("设置初始化群名称", alias={"设置数据库群名称", "初始化群名称"})
    async def set_initial_database_group_name_cmd(self, event: AstrMessageEvent) -> None:
        """Choose the authoritative SCUM name used by Steam bindings."""

        if not await self._is_group_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能设置初始化群名称。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        parts = (event.message_str or "").strip().lstrip("/").split(maxsplit=1)
        name = str(parts[1] if len(parts) > 1 else "").strip()[:255]
        if not name:
            name = await self._get_group_display_name(group_id, event)
        if not name or name == group_id:
            yield self._yield_plain(event, "无法取得群名称，请在命令后填写名称。")
            return
        update_group_feature_config(
            group_id,
            "group_config",
            "database_player_name",
            name,
            operator_id=self._get_sender_id_from_event(event),
        )
        yield self._yield_plain(event, f"已设置初始化群名称：{name}\n后续绑定 SteamID 时会同步修改服务器数据库玩家名称。")

    @filter.command("批量修改群名称", alias={"批量初始化群名称", "批量修改数据库名称"})
    async def batch_update_database_group_name_cmd(self, event: AstrMessageEvent) -> None:
        """Rename all locally bound Steam players in one selected DB profile."""

        if not await self._is_group_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能批量修改群名称。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        detail = get_group_feature_detail(group_id, "group_config", self.config)
        detail = detail if isinstance(detail, dict) else {}
        target_name = str(detail.get("database_player_name", "") or "").strip()
        if not target_name:
            target_name = await self._get_group_display_name(group_id, event)
        policy = self._get_signin_policy(group_id)
        descriptor = self._signin_database_descriptor(policy)
        profile_id = str(descriptor.get("id", descriptor.get("profile_id", "")) or "").strip()
        client = getattr(self, "_portal_sync_client", None)
        rename = getattr(client, "rename_database_member", None)
        if not profile_id or not callable(rename):
            yield self._yield_plain(event, "当前群未配置可写入的服务器数据库。")
            return
        bindings = list_steam_bindings(group_id, limit=500)
        if not bindings:
            yield self._yield_plain(event, "当前群没有已绑定 SteamID。")
            return
        success = 0
        failed = 0
        for binding in bindings:
            steam_id = str(binding.get("steam_id", "") or "").strip()
            if not steam_id:
                continue
            try:
                result = await rename(group_id, profile_id, steam_id, target_name)
            except Exception as exc:
                result = {"success": False, "message": type(exc).__name__}
            if isinstance(result, dict) and result.get("success") is True:
                success += 1
            else:
                failed += 1
        update_group_feature_config(
            group_id,
            "group_config",
            "database_player_name",
            target_name,
            operator_id=self._get_sender_id_from_event(event),
        )
        yield self._yield_plain(event, f"批量修改服务器数据库玩家名称完成：成功 {success} 条，失败 {failed} 条；名称：{target_name}")

    async def _bulk_apply_group_member_names(
        self, group_id: str, *, strip_prefix: str = ""
    ) -> tuple[int, int, str, bool]:
        """Apply configured names/prefix to the current QQ member list."""
        platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
        if not platform:
            raise RuntimeError("AIOCQHTTP 平台不可用")
        client = platform.get_client()
        response = await client.call_action(
            action="get_group_member_list", group_id=int(group_id)
        )
        members = self._extract_onebot_records(response)
        detail = get_group_feature_detail(group_id, "group_config", self.config)
        detail = detail if isinstance(detail, dict) else {}
        rules = self._parse_member_identity_rules(
            detail.get("member_names", []), "name", 60
        )
        name_prefix = str(detail.get("member_name_prefix", "") or "").strip()
        include_prefix_for_admins = detail.get("member_name_prefix_include_admins", True)
        if isinstance(include_prefix_for_admins, str):
            include_prefix_for_admins = include_prefix_for_admins.strip().lower() not in {
                "", "0", "false", "off", "no", "否", "关闭"
            }
        else:
            include_prefix_for_admins = bool(include_prefix_for_admins)
        strip_prefix = str(strip_prefix or "").strip()
        if not rules and not name_prefix and not strip_prefix:
            return 0, 0, "", False
        try:
            binding_by_user = {
                str(item.get("user_id", "")).strip(): item
                for item in list_steam_bindings(group_id, limit=5000)
                if isinstance(item, dict) and str(item.get("user_id", "")).strip()
            }
        except Exception:
            # A missing or legacy Steam binding store must not prevent ordinary
            # member-card rules and prefixes from being applied.
            binding_by_user = {}
        applied = 0
        failed = 0
        failure_detail = ""
        # The member directory is already normalized and deduplicated by the
        # refresh path. Apply the prefix to the complete live directory rather
        # than silently stopping at 500 users in larger groups.
        for member in members[:5000]:
            target = self._normalize_positive_id(
                member.get("user_id") or member.get("userId") or member.get("id")
            )
            if not target:
                continue
            role = str(member.get("role") or member.get("permission") or "member").strip().lower()
            role = {
                "group_owner": "owner", "groupowner": "owner", "群主": "owner",
                "administrator": "admin", "group_admin": "admin", "管理员": "admin", "群管理员": "admin",
            }.get(role, role)
            if name_prefix and not include_prefix_for_admins and role in {"admin", "owner"}:
                continue
            value = rules.get(target) or rules.get("*")
            binding = binding_by_user.get(target) or {}
            bound_name = str(binding.get("user_name", "") or "").strip()
            # Steam-bound members use the verified game name. Unbound members
            # always start from their QQ nickname, never the existing group
            # card, so reinitializing names cannot preserve an old prefix.
            # Never use the existing group card as the unbound source name:
            # it may already contain a previous prefix or another stale
            # operator edit.  A live QQ nickname is the only safe source;
            # falling back to the QQ number is preferable to resurrecting an
            # old group-card value.
            base_name = bound_name or str(
                member.get("nickname") or member.get("nick") or target
            ).strip() or target
            if strip_prefix:
                base_name = strip_member_name_prefix(strip_prefix, base_name)
            if value:
                value = (
                    str(value)
                    .replace("{user_id}", target)
                    .replace("{qq}", target)
                    .replace("{user_name}", base_name)
                    .replace("{nickname}", base_name)
                )[:60]
            else:
                value = base_name
            if name_prefix:
                value = apply_member_name_prefix(name_prefix, value)
            if not value:
                continue
            try:
                result = self._normalize_action_result(await client.call_action(
                    action="set_group_card",
                    group_id=int(group_id),
                    user_id=int(target),
                    card=value,
                ))
                if not self._api_result_succeeded(result):
                    failed += 1
                    failure_detail = failure_detail or self._onebot_failure_detail(result)
                    if self._is_packet_backend_unavailable(result):
                        break
                    continue
                set_user_name(group_id, target, value)
                applied += 1
            except Exception as exc:
                failed += 1
                failure_detail = failure_detail or self._onebot_failure_detail(exc)
                if self._is_packet_backend_unavailable(exc):
                    break
        return applied, failed, failure_detail, True

    @filter.command(
        "设置群名片前缀",
        alias={"设置群昵称前缀", "设置全局群昵称前缀", "清除群名片前缀"},
    )
    async def set_group_member_name_prefix_cmd(self, event: AstrMessageEvent) -> None:
        """Set and immediately apply one prefix to every member card."""
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能设置群名片前缀。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        raw = str(event.message_str or "").strip().lstrip("/")
        parts = raw.split(maxsplit=2)
        prefix = parts[1].strip() if len(parts) > 1 else ""
        admin_option = parts[2].strip() if len(parts) > 2 else ""
        admin_tokens = {
            "包含管理员": True, "修改管理员": True, "含管理员": True,
            "管理员": True, "all": True, "true": True, "on": True, "yes": True, "1": True,
            "不修改管理员": False, "不含管理员": False, "排除管理员": False,
            "跳过管理员": False, "仅普通成员": False, "false": False, "off": False,
            "no": False, "0": False, "否": False, "关闭": False,
        }
        existing_detail = get_group_feature_detail(group_id, "group_config", self.config)
        existing_detail = existing_detail if isinstance(existing_detail, dict) else {}
        old_prefix = str(existing_detail.get("member_name_prefix", "") or "").strip()
        include_admins = existing_detail.get("member_name_prefix_include_admins", True)
        if isinstance(include_admins, str):
            include_admins = include_admins.strip().lower() not in {"", "0", "false", "off", "no", "否", "关闭"}
        else:
            include_admins = bool(include_admins)
        if len(parts) == 2 and prefix.casefold() in {key.casefold() for key in admin_tokens}:
            admin_option = prefix
            prefix = ""
        if admin_option:
            option_key = admin_option.strip().casefold()
            for token, value in admin_tokens.items():
                if option_key == token.casefold():
                    include_admins = value
                    break
            else:
                yield self._yield_plain(event, "管理员选项仅支持：包含管理员、不修改管理员。")
                return
        if prefix.casefold() in {"关闭", "清除", "取消", "无", "none", "off"}:
            prefix = ""
        prefix = prefix.replace("\r", " ").replace("\n", " ").strip()
        if len(prefix) > 20:
            yield self._yield_plain(event, "群名片前缀不能超过 20 个字符。")
            return
        update_group_feature_config(
            group_id,
            "group_config",
            "member_name_prefix",
            prefix,
            operator_id=self._get_sender_id_from_event(event),
        )
        update_group_feature_config(
            group_id,
            "group_config",
            "member_name_prefix_include_admins",
            include_admins,
            operator_id=self._get_sender_id_from_event(event),
        )
        try:
            applied, failed, failure_detail, has_policy = (
                await self._bulk_apply_group_member_names(group_id, strip_prefix=old_prefix)
            )
        except Exception as exc:
            logger.warning(
                "批量应用群名片前缀失败 group=%s detail=%s",
                group_id,
                self._onebot_failure_detail(exc),
            )
            yield self._yield_plain(
                event,
                f"✅️ 已保存群名片前缀：{prefix or '已清除'}；批量应用失败，请稍后发送 /初始化群员名称。",
            )
            return
        if not prefix and not has_policy:
            message = "✅️ 已清除群名片全局前缀；不会再自动添加前缀。"
        else:
            message = (
                f"✅️ 群名片全局前缀已设置为：{prefix or '无'}；"
                f"管理员：{'包含' if include_admins else '不修改'}；已应用 {applied} 人，失败 {failed} 人。"
            )
        yield self._yield_plain(event, message)

    @filter.command(
        "设置群员名称",
        alias={
            "修改群员名称",
            "初始化群员名称",
            "设置群员昵称",
            "修改群员昵称",
        },
    )
    async def set_group_member_name_cmd(self, event: AstrMessageEvent) -> None:
        """Set both the QQ group card and the local sign-in display name."""
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能修改群员名称。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        user_id, display_name = self._parse_member_name_command(
            event,
            (
                "设置群员名称",
                "修改群员名称",
                "初始化群员名称",
                "设置群员昵称",
                "修改群员昵称",
            ),
        )
        user_id = self._normalize_positive_id(user_id)
        # ``/初始化群员名称`` without a target is a bulk operation.  It is
        # useful after enabling a wildcard/name plan and avoids requiring an
        # administrator to send one command per member.  The member list is
        # fetched once, then each configured rule is applied locally.
        raw_command = (event.message_str or "").strip().lstrip("/").split(maxsplit=1)[0]
        if raw_command == "初始化群员名称" and not user_id:
            try:
                applied, failed, failure_detail, has_policy = (
                    await self._bulk_apply_group_member_names(group_id)
                )
                if not has_policy:
                    yield self._yield_plain(event, "当前没有可初始化的群员名称方案或全局前缀。")
                    return
                result_text = f"✅️ 群员名称初始化完成：成功 {applied} 条，失败 {failed} 条。"
                if failure_detail:
                    result_text += "\n" + self._format_group_profile_failure(
                        "初始化群员名称",
                        failure_detail,
                        "请确认机器人具备群管理权限，并且目标成员允许修改群名片。",
                    )
                yield self._yield_plain(event, result_text)
            except Exception as exc:
                detail = self._onebot_failure_detail(exc)
                logger.warning("批量初始化群员名称失败 group=%s detail=%s", group_id, detail)
                yield self._yield_plain(
                    event,
                    self._format_group_profile_failure(
                        "初始化群员名称",
                        exc,
                        "请确认机器人具备群管理权限，并且目标成员允许修改群名片。",
                    ),
                )
            return
        if not user_id or not display_name:
            yield self._yield_plain(
                event,
                "用法：/设置群员名称 <QQ号或@成员> <名称>\n"
                "例如：/设置群员名称 123456 新名称",
            )
            return
        if len(display_name) > 60:
            yield self._yield_plain(event, "群员名称不能超过 60 个字符。")
            return

        try:
            platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
            if not platform:
                raise RuntimeError("AIOCQHTTP 平台不可用")
            result = self._normalize_action_result(await platform.get_client().call_action(
                action="set_group_card",
                group_id=int(group_id),
                user_id=int(user_id),
                card=display_name,
            ))
            if not self._api_result_succeeded(result):
                raise RuntimeError(self._onebot_failure_detail(result))
        except Exception as exc:
            detail = self._onebot_failure_detail(exc)
            logger.warning("设置群员名称失败 group=%s user=%s detail=%s", group_id, user_id, detail)
            yield self._yield_plain(
                event,
                self._format_group_profile_failure(
                    "设置群员名称",
                    exc,
                    "请确认机器人具备群管理权限，并且目标成员允许修改群名片。",
                ),
            )
            return

        set_user_name(group_id, user_id, display_name)
        # Keep the web-visible rule in the same per-group feature document as
        # the runtime name.  The Windows command remains authoritative; this
        # only records the successful local action for the next portal sync.
        self._upsert_member_identity_rule(group_id, user_id, "name", display_name)
        add_operation_log(
            group_id,
            self._get_sender_id_from_event(event),
            "",
            "set_group_member_name",
            user_id,
            display_name,
            "",
        )
        yield self._yield_plain(event, f"✅️ 已将 {user_id} 的群员名称设置为：{display_name}")

    @filter.command("清除群员名称", alias={"清除群员昵称", "恢复群员名称"})
    async def clear_group_member_name_cmd(self, event: AstrMessageEvent) -> None:
        """Clear one QQ group card and remove its one-off automatic rule."""
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能清除群员名称。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        user_id, _ = self._parse_member_name_command(
            event, ("清除群员名称", "清除群员昵称", "恢复群员名称")
        )
        user_id = self._normalize_positive_id(user_id)
        if not user_id:
            yield self._yield_plain(event, "用法：/清除群员名称 <QQ号或@成员>")
            return
        try:
            platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
            if not platform:
                raise RuntimeError("AIOCQHTTP 平台不可用")
            result = self._normalize_action_result(await platform.get_client().call_action(
                action="set_group_card",
                group_id=int(group_id),
                user_id=int(user_id),
                card="",
            ))
            if not self._api_result_succeeded(result):
                raise RuntimeError(self._onebot_failure_detail(result))
        except Exception as exc:
            detail = self._onebot_failure_detail(exc)
            logger.warning(
                "清除群员名称失败 group=%s user=%s detail=%s",
                group_id,
                user_id,
                detail,
            )
            yield self._yield_plain(
                event,
                self._format_group_profile_failure(
                    "清除群员名称",
                    exc,
                    "请确认机器人具备群管理权限，并且目标成员允许修改群名片。",
                ),
            )
            return
        self._remove_member_identity_rule(group_id, user_id, "name")
        add_operation_log(
            group_id,
            self._get_sender_id_from_event(event),
            "",
            "clear_group_member_name",
            user_id,
            "",
            "",
        )
        yield self._yield_plain(event, f"✅️ 已清除 {user_id} 的群员名称。")

    @filter.command("自动授予称号", alias={"给自己称号", "设置自己的称号"})
    async def set_self_group_title_cmd(self, event: AstrMessageEvent) -> None:
        """Set a special title for the member who sent the command."""
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能设置群称号。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        raw = str(event.message_str or "").strip().lstrip("/").strip()
        title = ""
        for command_name in ("自动授予称号", "给自己称号", "设置自己的称号"):
            if raw == command_name:
                break
            prefix = command_name + " "
            if raw.startswith(prefix):
                title = raw[len(prefix):].strip()
                break
        if not title:
            yield self._yield_plain(event, "用法：/自动授予称号 <称号>")
            return
        if len(title) > 18:
            yield self._yield_plain(event, "群称号不能超过 18 个字符。")
            return
        user_id = self._normalize_positive_id(self._get_sender_id_from_event(event))
        if not user_id:
            yield self._yield_plain(event, "无法取得你的 QQ 号。")
            return
        client = self._get_group_action_client(group_id)
        if not await self._is_bot_group_owner_async(group_id, client=client):
            yield self._yield_plain(event, "机器人不是本群群主，不能设置群称号。")
            return
        try:
            if not client:
                raise RuntimeError("AIOCQHTTP 平台不可用")
            target_info = await client.call_action(
                action="get_group_member_info",
                group_id=int(group_id),
                user_id=int(user_id),
            )
            if self._extract_onebot_role(target_info) == "owner":
                yield self._yield_plain(event, "群主不能设置专属群称号。")
                return
            result = self._normalize_action_result(
                await client.call_action(
                    action="set_group_special_title",
                    group_id=int(group_id),
                    user_id=int(user_id),
                    special_title=title,
                )
            )
            if not self._api_result_succeeded(result):
                raise RuntimeError(self._onebot_failure_detail(result))
        except Exception as exc:
            logger.warning(
                "设置自己的群称号失败 group=%s user=%s detail=%s",
                group_id,
                user_id,
                self._onebot_failure_detail(exc),
            )
            yield self._yield_plain(event, "设置群称号失败，请确认机器人是群主后重试。")
            return
        self._upsert_member_identity_rule(group_id, user_id, "title", title)
        yield self._yield_plain(event, f"✅️ 已设置你的群称号：{title}")

    @filter.command("开启自动称号", alias={"启用自动称号"})
    async def enable_auto_member_title_cmd(self, event: AstrMessageEvent) -> None:
        """Enable the per-group automatic special-title policy."""
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能修改自动称号设置。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        detail = get_group_feature_detail(group_id, "group_config", self.config)
        rules = self._parse_member_identity_rules(
            detail.get("member_titles", []) if isinstance(detail, dict) else [],
            "title",
            18,
        )
        seeded_default = not rules
        if seeded_default:
            update_group_feature_config(
                group_id,
                "group_config",
                "member_titles",
                self._default_member_title_rules(),
                operator_id=self._get_sender_id_from_event(event),
            )
        update_group_feature_config(
            group_id,
            "group_config",
            "auto_member_title",
            True,
            operator_id=self._get_sender_id_from_event(event),
        )
        self._member_identity_apply_cache = {}
        self._member_identity_failure_cache = {}
        suffix = "已写入默认规则：全体成员 = 群成员。" if seeded_default else ""
        yield self._yield_plain(
            event,
            "✅️ 已开启自动授予称号。"
            + suffix,
        )

    @filter.command("关闭自动称号", alias={"停用自动称号"})
    async def disable_auto_member_title_cmd(self, event: AstrMessageEvent) -> None:
        """Disable automatic special-title updates without removing rules."""
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能修改自动称号设置。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        update_group_feature_config(
            group_id,
            "group_config",
            "auto_member_title",
            False,
            operator_id=self._get_sender_id_from_event(event),
        )
        yield self._yield_plain(event, "✅️ 已关闭自动授予称号，已有称号不会被清除。")

    @filter.command("恢复默认称号设置", alias={"重置称号设置", "默认称号设置"})
    async def restore_default_member_title_cmd(self, event: AstrMessageEvent) -> None:
        """Restore the ready-to-use wildcard title policy for this group."""
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有群主或群管理员才能恢复默认称号设置。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        operator_id = self._get_sender_id_from_event(event)
        update_group_feature_config(
            group_id,
            "group_config",
            "member_titles",
            self._default_member_title_rules(),
            operator_id=operator_id,
        )
        update_group_feature_config(
            group_id,
            "group_config",
            "auto_member_title",
            False,
            operator_id=operator_id,
        )
        self._member_identity_apply_cache = {}
        self._member_identity_failure_cache = {}
        yield self._yield_plain(
            event,
            "✅️ 已恢复默认称号设置：自动授予已关闭，全体成员默认称号为“群成员”。",
        )

    @filter.command("查看称号设置", alias={"自动称号设置"})
    async def show_auto_member_title_cmd(self, event: AstrMessageEvent) -> None:
        """Show the effective automatic-title switch and configured rules."""
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        detail = get_group_feature_detail(group_id, "group_config", self.config)
        rules = self._parse_member_identity_rules(
            detail.get("member_titles", []) if isinstance(detail, dict) else [],
            "title",
            18,
        )
        enabled = bool(detail.get("auto_member_title", False)) if isinstance(detail, dict) else False
        lines = [
            f"自动称号：{'开启' if enabled else '关闭'}",
            f"称号规则：{len(rules)} 条",
        ]
        for user_id, title in list(rules.items())[:20]:
            lines.append(f"{'全体成员' if user_id == '*' else user_id}：{title}")
        if len(rules) > 20:
            lines.append(f"其余 {len(rules) - 20} 条请在网页分群设置查看。")
        lines.append("修改开关：/开启自动称号 或 /关闭自动称号")
        lines.append("恢复默认：/恢复默认称号设置")
        lines.append("给自己设置：/自动授予称号 <称号>")
        lines.append("手动操作：/授予称号 <QQ> <称号>｜/清除群员称号 <QQ>")
        yield self._yield_plain(event, "\n".join(lines))

    @filter.command(
        "初始化群员称号",
        alias={"批量授予称号", "批量初始化称号"},
    )
    async def initialize_group_titles_cmd(self, event: AstrMessageEvent) -> None:
        """Apply the configured title rules to current group members."""
        if not await self._is_group_owner_async(event):
            yield self._yield_plain(event, "只有群主或机器人主人才能初始化群员称号。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        client = self._get_group_action_client(group_id)
        if not await self._is_bot_group_owner_async(group_id, client=client):
            yield self._yield_plain(
                event,
                "机器人当前不是群主或无法确认群主身份，不能初始化群员称号。发送 /群资料状态 查看检测结果。",
            )
            return
        try:
            if not client:
                raise RuntimeError("AIOCQHTTP 平台不可用")
            detail = get_group_feature_detail(group_id, "group_config", self.config)
            rules = self._parse_member_identity_rules(
                detail.get("member_titles", []) if isinstance(detail, dict) else [],
                "title",
                18,
            )
            if not rules:
                rules = self._parse_member_identity_rules(
                    self._default_member_title_rules(), "title", 18
                )
                update_group_feature_config(
                    group_id,
                    "group_config",
                    "member_titles",
                    self._default_member_title_rules(),
                    operator_id=self._get_sender_id_from_event(event),
                )
            response = await client.call_action(
                action="get_group_member_list",
                group_id=int(group_id),
            )
            members = self._extract_onebot_records(response)
            applied = 0
            skipped = 0
            failed = 0
            failure_detail = ""
            for member in members[:500]:
                target = self._normalize_positive_id(
                    member.get("user_id") or member.get("userId") or member.get("id")
                )
                if not target:
                    skipped += 1
                    continue
                if self._extract_onebot_role(member) == "owner":
                    skipped += 1
                    continue
                title = rules.get(target) or rules.get("*")
                if not title:
                    skipped += 1
                    continue
                member_name = str(
                    member.get("card") or member.get("nickname") or target
                ).strip() or target
                title = (
                    str(title)
                    .replace("{user_id}", target)
                    .replace("{qq}", target)
                    .replace("{user_name}", member_name)
                    .replace("{nickname}", member_name)
                )[:18]
                try:
                    result = self._normalize_action_result(await client.call_action(
                        action="set_group_special_title",
                        group_id=int(group_id),
                        user_id=int(target),
                        special_title=title,
                    ))
                    if not self._api_result_succeeded(result):
                        failed += 1
                        failure_detail = failure_detail or self._onebot_failure_detail(result)
                        if self._is_packet_backend_unavailable(result):
                            break
                        continue
                    applied += 1
                except Exception as exc:
                    failed += 1
                    failure_detail = failure_detail or self._onebot_failure_detail(exc)
                    logger.warning(
                        "批量授予群称号失败 group=%s user=%s error=%s",
                        group_id,
                        target,
                        type(exc).__name__,
                    )
            result_text = f"✅️ 群员称号初始化完成：成功 {applied} 条，失败 {failed} 条，跳过 {skipped} 条。"
            if failure_detail:
                result_text += "\n" + self._format_group_profile_failure(
                    "初始化群员称号",
                    failure_detail,
                    "请确认机器人是群主；群管理员和普通成员可作为目标，群主本人不能被设置称号。",
                )
            yield self._yield_plain(event, result_text)
        except Exception as exc:
            detail = self._onebot_failure_detail(exc)
            logger.warning("批量初始化群员称号失败 group=%s detail=%s", group_id, detail)
            yield self._yield_plain(
                event,
                self._format_group_profile_failure(
                    "初始化群员称号",
                    exc,
                    "请确认机器人是群主且具备群管理权限。",
                ),
            )

    @filter.command(
        "授予称号",
        alias={"授予头衔", "设置群头衔", "设置称号"},
    )
    async def grant_group_title_cmd(self, event: AstrMessageEvent) -> None:
        """Grant a QQ special title; only the group owner can do this."""
        if not await self._is_group_owner_async(event):
            yield self._yield_plain(event, "只有群主或机器人主人才能授予群成员称号。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        client = self._get_group_action_client(group_id)
        if not await self._is_bot_group_owner_async(group_id, client=client):
            yield self._yield_plain(
                event,
                "机器人当前不是群主或无法确认群主身份，不能授予称号。发送 /群资料状态 查看检测结果。",
            )
            return
        user_id, title = self._parse_member_name_command(
            event,
            ("授予称号", "授予头衔", "设置群头衔", "设置称号"),
        )
        user_id = self._normalize_positive_id(user_id)
        if not user_id or not title:
            yield self._yield_plain(
                event,
                "用法：/授予称号 <QQ号或@成员> <称号>\n"
                "例如：/授予称号 123456 勇者",
            )
            return
        if len(title) > 18:
            yield self._yield_plain(event, "群称号不能超过 18 个字符。")
            return
        try:
            if not client:
                raise RuntimeError("AIOCQHTTP 平台不可用")
            target_role = ""
            try:
                target_info = await client.call_action(
                    action="get_group_member_info",
                    group_id=int(group_id),
                    user_id=int(user_id),
                )
                target_role = self._extract_onebot_role(target_info)
            except Exception as exc:
                logger.debug(
                    "读取称号目标身份失败 group=%s user=%s detail=%s",
                    group_id,
                    user_id,
                    self._onebot_failure_detail(exc),
                )
            if target_role == "owner":
                yield self._yield_plain(event, "目标是本群群主，QQ 平台不允许修改群主的专属称号。")
                return
            result = self._normalize_action_result(await client.call_action(
                action="set_group_special_title",
                group_id=int(group_id),
                user_id=int(user_id),
                special_title=title,
            ))
            if not self._api_result_succeeded(result):
                raise RuntimeError(self._onebot_failure_detail(result))
        except Exception as exc:
            detail = self._onebot_failure_detail(exc)
            logger.warning("授予群称号失败 group=%s user=%s detail=%s", group_id, user_id, detail)
            yield self._yield_plain(
                event,
                self._format_group_profile_failure(
                    "授予称号",
                    exc,
                    "请确认机器人是群主；群管理员和普通成员可作为目标，群主本人不能被设置称号。",
                ),
            )
            return

        # Persist the successful title grant so the Linux editor and future
        # Windows syncs do not lose the rule after a reload.
        self._upsert_member_identity_rule(group_id, user_id, "title", title)
        add_operation_log(
            group_id,
            self._get_sender_id_from_event(event),
            "",
            "set_group_special_title",
            user_id,
            title,
            "",
        )
        yield self._yield_plain(event, f"✅️ 已授予 {user_id} 群称号：{title}")

    @filter.command("清除群员称号", alias={"清除称号", "移除称号"})
    async def clear_group_title_cmd(self, event: AstrMessageEvent) -> None:
        """Clear one QQ special title and remove its one-off automatic rule."""
        if not await self._is_group_owner_async(event):
            yield self._yield_plain(event, "只有群主或机器人主人才能清除群成员称号。")
            return
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event, "此命令只能在群聊中使用。")
            return
        client = self._get_group_action_client(group_id)
        if not await self._is_bot_group_owner_async(group_id, client=client):
            yield self._yield_plain(
                event,
                "机器人当前不是群主或无法确认群主身份，不能清除称号。发送 /群资料状态 查看检测结果。",
            )
            return
        user_id, _ = self._parse_member_name_command(
            event, ("清除群员称号", "清除称号", "移除称号")
        )
        user_id = self._normalize_positive_id(user_id)
        if not user_id:
            yield self._yield_plain(event, "用法：/清除群员称号 <QQ号或@成员>")
            return
        try:
            if not client:
                raise RuntimeError("AIOCQHTTP 平台不可用")
            result = self._normalize_action_result(await client.call_action(
                action="set_group_special_title",
                group_id=int(group_id),
                user_id=int(user_id),
                special_title="",
            ))
            if not self._api_result_succeeded(result):
                raise RuntimeError(self._onebot_failure_detail(result))
        except Exception as exc:
            detail = self._onebot_failure_detail(exc)
            logger.warning(
                "清除群称号失败 group=%s user=%s detail=%s",
                group_id,
                user_id,
                detail,
            )
            yield self._yield_plain(
                event,
                self._format_group_profile_failure(
                    "清除群称号",
                    exc,
                    "请确认机器人确实是群主；若目标是群主，QQ 平台不允许修改其称号。",
                ),
            )
            return
        self._remove_member_identity_rule(group_id, user_id, "title")
        add_operation_log(
            group_id,
            self._get_sender_id_from_event(event),
            "",
            "clear_group_special_title",
            user_id,
            "",
            "",
        )
        yield self._yield_plain(event, f"✅️ 已清除 {user_id} 的群称号。")

    @filter.command(
        "群管功能",
        alias={"管理功能", "群管理", "群管帮助", "功能", "功能帮助", "插件功能"},
    )
    async def show_qqadmin_help(self, event: AstrMessageEvent) -> None:
        # Keep the established detailed renderer available for feature pages;
        # the index and category layers below intentionally use compact views.
        _ = self._format_nested_command_help
        if not self._is_slash_prefix_allowed(event) or not self.enable_help:
            return
        group_id = self._get_group_id_from_event(event)
        help_settings = self._get_group_help_settings(group_id)
        if not await self._group_help_permission_allowed(
            event, help_settings.get("permission", "member")
        ):
            yield self._yield_plain(event, "当前群管目录仅限指定用户查看。")
            event.stop_event()
            return
        configured_aliases = {
            str(alias).strip()
            for alias in help_settings.get("aliases", ())
            if str(alias).strip()
        }
        args = self._command_help_args(
            event,
            {
                "群管功能", "管理功能", "群管理", "群管帮助",
                "功能", "功能帮助", "插件功能",
            } | configured_aliases,
        )
        sections = self._group_help_sections(event, group_id)
        category_aliases = self._group_help_category_aliases()
        requested_category = category_aliases.get(args[0].strip().lower()) if args else None
        detail_handler = self._group_help_detail_handler(args[-1]) if args else None

        # The nested route keeps the compact index useful while allowing a
        # member or administrator to drill into one exact feature.
        if detail_handler is not None and (requested_category is None or len(args) > 1):
            async for result in detail_handler(event):
                yield result
            event.stop_event()
            return
        if args:
            if requested_category is None:
                yield self._yield_plain(
                    event,
                    f"未找到该分类。用法：/{help_settings['command']} 管理|回复|统计|工具|娱乐|SCUM查询\n"
                    f"查看具体用法：/{help_settings['command']} <分类> <功能>",
                )
                event.stop_event()
                return
            if len(args) > 1:
                yield self._yield_plain(
                    event,
                    f"未找到“{args[-1]}”的用法。请发送 /{help_settings['command']} {args[0]} 查看该分类指令。",
                )
                event.stop_event()
                return
            selected = [section for section in sections if section[0] == requested_category]
            help_text = self._format_feature_category_help(
                f"{help_settings['command']} / {requested_category}｜群 {group_id or '私聊'}",
                requested_category,
                selected[0][1] if selected else [],
                footer=f"只显示当前分群有效指令；完整目录：/{help_settings['command']}。",
            )
            yield self._yield_plain(event, help_text)
            event.stop_event()
            return

        help_text = self._format_group_admin_feature_menu(
            sections,
            category_command=str(help_settings.get("command", "群管功能")),
            audience=str(help_settings.get("permission", "member")),
        )
        yield self._yield_plain(event,help_text)

    

    
    
    @filter.command("添加白名单群")
    async def add_whitelist_group(self, event: AstrMessageEvent) -> None:
        if not self._is_owner(event):
            return
        message = self._get_event_message_text(event)
        parts = message.split()
        if len(parts) < 2:
            yield self._yield_plain(event,"用法: /添加白名单群 <群号>")
            return
        group_id = parts[1].strip()
        if "basic"not in self.config:
            self.config["basic"] = {}
        if "whitelist_groups"not in self.config["basic"]:
            self.config["basic"]["whitelist_groups"] = []
        whitelist_groups = self.config["basic"]["whitelist_groups"]
        if not isinstance(whitelist_groups, list):
            yield self._yield_plain(event,"白名单配置格式错误，未做任何修改。")
            return
        if self._is_in_whitelist(group_id):
            yield self._yield_plain(event,f"群 {group_id} 已在白名单中")
            return

        whitelist_groups.append(group_id)
        if not self._persist_plugin_config():
            whitelist_groups.pop()
            yield self._yield_plain(event,"保存白名单失败，未做任何修改。")
            return
        self.whitelist_groups = whitelist_groups
        yield self._yield_plain(event,f"已添加群 {group_id} 到白名单")
    
    @filter.command("删除白名单群")
    async def remove_whitelist_group(self, event: AstrMessageEvent) -> None:
        if not self._is_owner(event):
            return
        message = (event.message_str or "").strip()
        parts = message.split()
        if len(parts) < 2:
            yield self._yield_plain(event,"用法: /删除白名单群 <群号>")
            return
        group_id = parts[1].strip()
        if "basic"in self.config and "whitelist_groups"in self.config["basic"]:
            whitelist_groups = self.config["basic"]["whitelist_groups"]
            if not isinstance(whitelist_groups, list):
                yield self._yield_plain(event,"白名单配置格式错误，未做任何修改。")
                return
            match_index = next(
                (
                    index
                    for index, configured_group_id in enumerate(whitelist_groups)
                    if str(configured_group_id).strip() == group_id
                ),
                None,
            )
            if match_index is None:
                yield self._yield_plain(event,f"群 {group_id} 不在白名单中")
                return

            removed_group_id = whitelist_groups.pop(match_index)
            if not self._persist_plugin_config():
                whitelist_groups.insert(match_index, removed_group_id)
                yield self._yield_plain(event,"保存白名单失败，未做任何修改。")
                return
            self.whitelist_groups = whitelist_groups
            yield self._yield_plain(event,f"已从白名单移除群 {group_id}")
        else:
            yield self._yield_plain(event,f"白名单为空")
    
