    # ==================== 群管总开关命令 ====================
    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE)
    async def handle_group_manage_commands(self, event: AstrMessageEvent) -> None:
        message_str = event.message_str or ""
        # 早期返回：消息不以 / 开头则跳过
        if not message_str.startswith('/'):
            return
        raw = message_str.lstrip('/').strip()
        # 支持 /开启群管 和 /开启群管 <功能名> 两种形式
        parts = raw.split(maxsplit=1)
        if not parts or not parts[0]:
            return
        base_cmd = parts[0]
        sub_feature = parts[1].strip() if len(parts) > 1 else None

        # 检查是否是群管总开关命令
        group_manage_commands = ["开启群管", "关闭群管", "开启黑名单系统", "关闭黑名单系统"]
        if base_cmd not in group_manage_commands:
            return

        all_features_map = feature_alias_map()

        if base_cmd in ("开启群管", "关闭群管", "开启黑名单系统", "关闭黑名单系统"):
            # 公共校验：权限 + 群组环境
            ok, group_id, err = await self._check_admin_group(event)
            if not ok:
                yield err
                return

            # 黑名单系统的两个别名命令等价于 /开启群管 黑名单 / /关闭群管 黑名单
            if base_cmd == "开启黑名单系统":
                sub_feature = "blacklist"
                enable_flag = True
            elif base_cmd == "关闭黑名单系统":
                sub_feature = "blacklist"
                enable_flag = False
            else:
                enable_flag = base_cmd == "开启群管"

            all_keys = list(dict.fromkeys(all_features_map.values()))  # 去重保留顺序

            if sub_feature is None:
                # 全开 / 全关
                for key in all_keys:
                    set_feature_enabled(group_id, key, enable_flag, self.config)
                msg = f"{'✅️ 已开启' if enable_flag else '❌️ 已关闭'}群管系统所有功能（{len(all_keys)} 个模块）"
            else:
                # 指定功能名
                target_key = all_features_map.get(sub_feature)
                if target_key is None:
                    target_key = all_features_map.get(sub_feature.lower())
                if target_key is None:
                    available = "/".join(category.key for category in CONFIGURABLE_FEATURES)
                    yield self._yield_plain(event, f"未知功能: {sub_feature}\n可用: {available}")
                    event.stop_event()
                    return
                set_feature_enabled(group_id, target_key, enable_flag, self.config)
                category = next(
                    (item for item in CONFIGURABLE_FEATURES if item.enabled_key == target_key),
                    None,
                )
                display_name = category.label if category else sub_feature
                msg = f"{'✅️ 已开启' if enable_flag else '❌️ 已关闭'}: {display_name}"

            self._log_send(event, msg, "群管命令")
            # 群内修改是 Windows 端的本地权威变更：立即清理当前进程的
            # 功能缓存，并唤醒出站同步，让 Linux 网页尽快显示同一状态。
            self._on_local_group_config_changed(str(group_id))
            yield self._yield_plain(event, msg)
            event.stop_event()

    async def _handle_mention_mute_config(self, event: AstrMessageEvent, command: str):
        """Maintain target and trigger-to-target rules for automatic @禁言."""
        ok, group_id, error = await self._check_admin_group(
            event, required_sub_admin_permission="mute"
        )
        if not ok:
            yield error
            return
        detail = get_group_feature_detail(group_id, "mute", self.config)
        rules = self._parse_mention_mute_rules(
            detail.get("mention_mute_rules", []) if isinstance(detail, dict) else []
        )
        if command == "查看艾特禁言":
            if not rules:
                yield self._yield_plain(event, "当前没有艾特禁言规则。")
                return
            lines = ["艾特禁言规则（消息中艾特成员时自动执行）："]
            for rule_key, duration in sorted(rules.items()):
                if ">" in rule_key:
                    source, target = rule_key.split(">", 1)
                    lines.append(f"艾特 QQ {source}：禁言 QQ {target} {duration} 秒")
                else:
                    lines.append(
                        f"有人艾特 QQ {rule_key}：禁言发言人 {duration} 秒"
                    )
            yield self._yield_plain(event, "\n".join(lines))
            return
        if command in {"清空艾特禁言", "关闭艾特禁言"}:
            rules.clear()
        else:
            mentioned = list(self._get_at_user_ids(event))
            rule_key = ""
            if len(mentioned) >= 2:
                rule_key = f"{mentioned[0]}>{mentioned[1]}"
            else:
                payload = command
                for prefix in ("设置艾特禁言", "取消艾特禁言"):
                    if payload.startswith(prefix):
                        payload = payload[len(prefix):].strip()
                        break
                pair = re.search(r"(?<!\d)(\d{5,20})\s*(?:->|>|,)\s*(\d{5,20})(?!\d)", payload)
                if pair:
                    rule_key = f"{pair.group(1)}>{pair.group(2)}"
                else:
                    target = mentioned[0] if mentioned else self._parse_user_id(command, ["设置艾特禁言", "取消艾特禁言"])
                    if target and target.isdigit():
                        rule_key = target
            if not rule_key:
                yield self._yield_plain(
                    event,
                    "用法：/设置艾特禁言 @触发对象 @禁言对象 5m；"
                    "单人格式 /设置艾特禁言 @目标 5m（有人艾特目标时禁言发言人）。",
                )
                return
            if command.startswith("取消"):
                rules.pop(rule_key, None)
            else:
                duration_text = command
                for user_id in set(mentioned) | set(re.findall(r"\d{5,20}", rule_key)):
                    duration_text = re.sub(rf"@?{re.escape(user_id)}", " ", duration_text)
                tokens = duration_text.split()
                duration = next((self._parse_duration_token(token) for token in tokens if self._parse_duration_token(token)), 0)
                if not duration:
                    yield self._yield_plain(event, "请填写禁言时长，例如 30s、5m；裸数字按分钟计算。")
                    return
                rules[rule_key] = duration
        value = self._format_mention_mute_rules(rules)
        update_group_feature_config(group_id, "mute", "mention_mute_rules", value)
        from .qqadmin.mute import set_mute_settings
        set_mute_settings(group_id, "mention_mute_rules", value)
        self._on_local_runtime_changed(str(group_id))
        yield self._yield_plain(event, "✅️ 艾特禁言规则已更新。" if rules else "✅️ 艾特禁言规则已清空。")

    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE, priority=10950)
    async def handle_mention_mute(self, event: AstrMessageEvent):
        """Mute only explicitly configured @ targets without affecting normal mentions."""
        group_id = self._get_group_id_from_event(event)
        if not group_id or self._get_event_message_text(event).lstrip().startswith("/"):
            return
        if not self._check_group_authorized(event) or not is_feature_enabled(group_id, "mute", self.config):
            return
        targets = self._get_at_user_ids(event)
        if not targets:
            return
        detail = get_group_feature_detail(group_id, "mute", self.config)
        rules = self._parse_mention_mute_rules(
            detail.get("mention_mute_rules", []) if isinstance(detail, dict) else []
        )
        if not rules:
            return
        # Prefer the bot that received this event.  AIOCQHTTP can host several
        # QQ logins in one AstrBot process; the context-level client may belong
        # to another login that is not in this group and then returns the
        # misleading ``ERR_NOT_GROUP_MEMBER``.  ``call_action`` receives an
        # explicit user_id, so it does not inherit the message author.
        client = None
        call_action = None
        try:
            client = getattr(event, "bot", None)
            call_action = getattr(client, "call_action", None)
        except Exception:
            client = None
            call_action = None
        if not callable(call_action):
            try:
                platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                client = platform.get_client() if platform else None
                call_action = getattr(client, "call_action", None)
            except Exception:
                client = None
                call_action = None
        if not callable(call_action):
            logger.warning("艾特禁言执行失败 group=%s reason=platform_unavailable", group_id)
            return
        operator_id = self._get_sender_id_from_event(event) or "system"
        # Directed rules use the mentioned QQ as the trigger: A>B means
        # “when A is mentioned, mute B”. A legacy single-target rule has a
        # different, intentional meaning: “when A is mentioned, mute the
        # sender”. Keep these paths separate so the mentioned user is never
        # muted accidentally by the single-target form.
        actions: dict[str, tuple[int, str]] = {}
        for trigger_id in targets:
            legacy_duration = rules.get(trigger_id)
            if legacy_duration:
                if operator_id.isdigit():
                    actions[operator_id] = (
                        legacy_duration,
                        f"艾特禁言规则（发言人艾特 {trigger_id}）",
                    )
            for rule_key, duration in rules.items():
                if ">" not in rule_key:
                    continue
                source_id, target_id = rule_key.split(">", 1)
                if source_id == trigger_id and target_id.isdigit():
                    actions[target_id] = (
                        duration,
                        f"艾特禁言规则 {source_id}>{target_id}",
                    )
        handled_actions = 0
        for user_id, (duration, rule_name) in actions.items():
            try:
                result = await call_action(
                    action="set_group_ban",
                    group_id=int(group_id),
                    user_id=int(user_id),
                    duration=duration,
                )
                if not self._api_result_succeeded(result):
                    raise RuntimeError(self._onebot_failure_detail(result) or "平台拒绝禁言")
                from .qqadmin.mute import mute_user
                mute_user(group_id, user_id, duration, rule_name, operator_id, "manual")
                add_operation_log(group_id, operator_id, "", "艾特禁言", user_id, "", f"{duration}秒")
                logger.info(
                    "艾特禁言执行成功 group=%s sender=%s target=%s duration=%s",
                    group_id,
                    operator_id,
                    user_id,
                    duration,
                )
                handled_actions += 1
            except Exception as exc:
                logger.warning(
                    "艾特禁言执行失败 group=%s sender=%s target=%s reason=%s",
                    group_id,
                    operator_id,
                    user_id,
                    self._onebot_failure_detail(exc)[:160],
                )

        # This message has been handled by the dedicated @ mute rule. Stop
        # the generic moderation pipeline from re-processing the same event;
        # otherwise a keyword/recall rule (or the audit timeout sweep) can
        # perform a second action and make a harmless @ message look like an
        # unexplained kick. A failed platform call is left visible to the
        # normal pipeline so its own configured fallback can still run.
        if handled_actions:
            event.stop_event()

    # ==================== 禁言系统命令 ====================
    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE)
    async def handle_mute_commands(self, event: AstrMessageEvent) -> None:
        message_str = self._get_event_message_text(event)
        cmd = message_str.lstrip('/').strip().replace("\u3000", " ")
        group_id = self._get_group_id_from_event(event)

        # 检查是否是禁言相关命令
        mute_commands = ["开启禁言", "关闭禁言", "禁言", "解除禁言", "解禁", "全体禁言", "全体解禁", "查看禁言列表", "设置禁言级别", "设置禁言时长", "设置解禁提示", "查看解禁提示", "清除解禁提示", "设置艾特禁言", "取消艾特禁言", "查看艾特禁言", "清空艾特禁言", "关闭艾特禁言"]
        is_mute_command = cmd in mute_commands or \
                         cmd.startswith("禁言 ") or cmd.startswith("禁言@") or \
                         cmd.startswith("解除禁言 ") or cmd.startswith("解除禁言@") or \
                         cmd.startswith("解禁 ") or cmd.startswith("解禁@") or \
                         cmd.startswith("设置禁言级别 ") or \
                         cmd.startswith("设置禁言时长 ") or \
                         cmd.startswith("设置解禁提示 ") or cmd.startswith("设置解禁提示") or \
                         cmd.startswith("设置艾特禁言") or cmd.startswith("取消艾特禁言")
        
        if not is_mute_command:
            return

        if group_id and not self._event_allows_primary_group_bot(event, group_id):
            event.stop_event()
            return
        if group_id and not self._claim_group_moderation_command(event, group_id, cmd):
            logger.debug(
                "跳过重复群管指令 group=%s command=%s",
                group_id,
                cmd[:80],
            )
            event.stop_event()
            return
        
        mute_configuration_command = (
            cmd in {"开启禁言", "关闭禁言", "查看解禁提示", "清除解禁提示"}
            or cmd.startswith("设置禁言级别")
            or cmd.startswith("设置禁言时长")
            or cmd.startswith("设置解禁提示")
        )
        if mute_configuration_command:
            ok, group_id, err = await self._check_admin_group(
                event, required_sub_admin_permission="mute"
            )
            if not ok:
                yield err
                event.stop_event()
                return

        if (
            cmd in {"查看艾特禁言", "清空艾特禁言", "关闭艾特禁言"}
            or cmd.startswith("设置艾特禁言")
            or cmd.startswith("取消艾特禁言")
        ):
            async for result in self._handle_mention_mute_config(event, cmd):
                yield result
            event.stop_event()
            return

        if cmd in {"开启禁言", "关闭禁言"}:
            enabled = cmd == "开启禁言"
            set_feature_enabled(group_id, "mute_enabled", enabled, self.config)
            yield self._yield_plain(event, f"{'✅️ 已开启' if enabled else '❌️ 已关闭'}禁言系统")
            event.stop_event()
            return

        if cmd.startswith("设置禁言级别") or cmd.startswith("设置禁言时长"):
            parts = cmd.split()
            if len(parts) < 2 or not parts[1].isdigit():
                usage = "/设置禁言级别 <1-10>" if cmd.startswith("设置禁言级别") else "/设置禁言时长 <秒数>"
                yield self._yield_plain(event, f"用法: {usage}")
                event.stop_event()
                return
            value = int(parts[1])
            if cmd.startswith("设置禁言级别") and not 1 <= value <= 10:
                yield self._yield_plain(event, "禁言级别必须在 1-10 之间")
                event.stop_event()
                return
            if cmd.startswith("设置禁言时长") and not 1 <= value <= 2592000:
                yield self._yield_plain(event, "禁言时长必须在 1-2592000 秒之间")
                event.stop_event()
                return
            setting = "level" if cmd.startswith("设置禁言级别") else "duration"
            from .qqadmin.mute import set_mute_settings
            set_mute_settings(group_id, setting, value)
            update_group_feature_config(group_id, "mute", setting, value)
            unit = "级" if setting == "level" else "秒"
            yield self._yield_plain(event, f"已设置默认禁言{setting == 'level' and '级别' or '时长'}: {value}{unit}")
            event.stop_event()
            return

        if cmd == "设置解禁提示" or cmd.startswith("设置解禁提示 "):
            async for result in self._handle_set_unmute_notification(event):
                yield result
            event.stop_event()
            return

        if cmd == "查看解禁提示":
            async for result in self._handle_view_unmute_notification(event):
                yield result
            event.stop_event()
            return

        if cmd == "清除解禁提示":
            async for result in self._handle_clear_unmute_notification(event):
                yield result
            event.stop_event()
            return

        if not self._check_feature_cached(event, self.qqadmin_enable_mute, "mute_enabled"):
            return
        
        if cmd == "禁言" or cmd.startswith("禁言 ") or cmd.startswith("禁言@"):
            async for result in self._handle_mute(event):
                yield result
            event.stop_event()
        
        elif (
            cmd in ["解除禁言", "解禁"]
            or cmd.startswith("解除禁言 ")
            or cmd.startswith("解除禁言@")
            or cmd.startswith("解禁 ")
            or cmd.startswith("解禁@")
        ):
            async for result in self._handle_unmute(event):
                yield result
            event.stop_event()
        
        elif cmd == "全体禁言":
            async for result in self._handle_whole_ban(event, enable=True):
                yield result
            event.stop_event()
        
        elif cmd == "全体解禁":
            async for result in self._handle_whole_ban(event, enable=False):
                yield result
            event.stop_event()
        
        elif cmd == "查看禁言列表":
            async for result in self._handle_list_muted(event):
                yield result
            event.stop_event()

