    # ==================== 踢出系统命令 ====================
    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE)
    async def handle_kick_commands(self, event: AstrMessageEvent) -> None:
        message_str = event.message_str or ""
        cmd = message_str.lstrip('/').strip()

        # 检查是否是踢出相关命令
        kick_commands = ["开启踢出", "关闭踢出", "踢出", "查看踢出记录", "清除踢出记录", "连带踢出", "设置踢出上限", "设置踢出拉黑"]
        is_kick_command = cmd in kick_commands or cmd.startswith("踢出 ") or cmd.startswith("连带踢出") or cmd.startswith("设置踢出上限 ") or cmd.startswith("设置踢出拉黑 ")
        
        if not is_kick_command:
            return
        
        if cmd in {"开启踢出", "关闭踢出"}:
            if not await self._is_admin_or_owner_async(
                event, required_sub_admin_permission="kick"
            ):
                yield self._yield_plain(event, "只有管理员或群主才能执行此操作。")
                event.stop_event()
                return
            group_id = self._get_group_id_from_event(event)
            enabled = cmd == "开启踢出"
            set_feature_enabled(group_id, "kick_enabled", enabled, self.config)
            yield self._yield_plain(event, f"{'✅️ 已开启' if enabled else '❌️ 已关闭'}踢出系统")
            event.stop_event()
            return

        if cmd.startswith("设置踢出上限") or cmd.startswith("设置踢出拉黑"):
            if not await self._is_admin_or_owner_async(
                event, required_sub_admin_permission="kick"
            ):
                yield self._yield_plain(event, "只有管理员或群主才能执行此操作。")
                event.stop_event()
                return
            parts = cmd.split()
            if len(parts) < 2:
                yield self._yield_plain(event, "用法: /设置踢出上限 <1-100> 或 /设置踢出拉黑 <开/关>")
                event.stop_event()
                return
            from .qqadmin.kick import set_kick_settings
            group_id = self._get_group_id_from_event(event)
            if cmd.startswith("设置踢出上限"):
                if not parts[1].isdigit() or not 1 <= int(parts[1]) <= 100:
                    yield self._yield_plain(event, "踢出上限必须在 1-100 之间")
                    event.stop_event()
                    return
                value = int(parts[1])
                set_kick_settings(group_id, "limit", value)
                update_group_feature_config(group_id, "kick", "limit", value)
                yield self._yield_plain(event, f"已设置踢出上限: {value}次")
            else:
                if parts[1] not in {"开", "关", "1", "0"}:
                    yield self._yield_plain(event, "用法: /设置踢出拉黑 <开/关>")
                    event.stop_event()
                    return
                enabled = parts[1] in {"开", "1"}
                set_kick_settings(group_id, "auto_blacklist", enabled)
                update_group_feature_config(group_id, "kick", "auto_blacklist", enabled)
                yield self._yield_plain(event, f"{'✅️ 已开启' if enabled else '❌️ 已关闭'}踢出自动拉黑")
            event.stop_event()
            return

        if not self._check_feature_cached(event, self.qqadmin_enable_kick, "kick_enabled"):
            return
        
        if cmd == "踢出"or cmd.startswith("踢出 ") or cmd.startswith("踢出@"):
            async for result in self._handle_kick(event):
                yield result
            event.stop_event()
        
        elif cmd == "连带踢出"or cmd.startswith("连带踢出 "):
            async for result in self._handle_kick_with_inviter(event):
                yield result
            event.stop_event()
        
        elif cmd == "查看踢出记录"or cmd.startswith("查看踢出记录 "):
            async for result in self._handle_list_kick_records(event):
                yield result
            event.stop_event()
        
        elif cmd == "清除踢出记录"or cmd.startswith("清除踢出记录 "):
            async for result in self._handle_clear_kick_records(event):
                yield result
            event.stop_event()

