    @filter.command("查看全局黑名单")
    async def list_global_blacklist_command(self, event: AstrMessageEvent) -> None:
        if not self._is_slash_prefix_allowed(event):
            return
        if not self._is_owner(event):
            yield self._yield_plain(event,"只有主人才能查看全局黑名单。")
            return
        current_group = self._get_group_id_from_event(event)
        blacklist = list_global_blacklist(group_id=current_group) if current_group else list_global_blacklist()
        if not blacklist:
            yield self._yield_plain(event,"暂无全局黑名单用户")
            return
        lines = ["全局黑名单"]
        for entry in blacklist:
            user_id = entry.get("user_id", "")
            reason = entry.get("reason", "无")
            ban_type = entry.get("ban_type", "")
            added_at = entry.get("added_at", 0)
            added_time = time.strftime("%Y-%m-%d %H:%M", time.localtime(added_at)) if added_at > 0 else "未知"
            lines.append(f"\nQQ: {user_id}")
            lines.append(f"  ├─ 原因: {reason}")
            lines.append(f"  ├─ 类型: {'永久'if ban_type == 'permanent'else '临时'}")
            lines.append(f"  └─ 添加时间: {added_time}")
        yield self._yield_plain(event,"\n".join(lines))

