    # ==================== 入群审核命令 ====================
    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE)
    async def handle_audit_commands(self, event: AstrMessageEvent) -> None:
        message_str = event.message_str or ""
        cmd = message_str.lstrip('/').strip()

        # 检查是否是入群审核相关命令
        audit_commands = ["开启审核", "关闭审核", "审核", "审核通过", "审批", "拒绝",
                         "查看待审核", "查看白名单", "开启验证", "关闭验证", "验证提示"]
        audit_setting_commands = {
            "审核超时", "设置验证超时", "审核次数", "设置验证次数",
            "设置验证最大尝试", "设置验证类型", "设置审批模式",
        }
        command_name = cmd.split(maxsplit=1)[0] if cmd else ""
        is_audit_command = cmd in audit_commands or \
                          cmd.startswith("审核 ") or \
                          cmd.startswith("审核通过 ") or \
                          cmd.startswith("审批 ") or \
                          cmd.startswith("拒绝 ") or \
                          cmd.startswith("添加白名单") or \
                          cmd.startswith("移除白名单") or \
                          command_name in audit_setting_commands
        
        if not is_audit_command:
            return

        logger.debug(f"handle_audit_commands: 收到审核命令 '{cmd}'")

        if cmd == "开启审核":
            logger.debug("handle_audit_commands: 处理 开启审核")
            if not await self._is_admin_or_owner_async(event):
                self._log_send(event, "只有管理员或群主才能执行此操作。", "审核命令")
                yield self._yield_plain(event,"只有管理员或群主才能执行此操作。")
                event.stop_event()
                return
            group_id = self._get_group_id_from_event(event)
            if not group_id or group_id == "None":
                self._log_send(event, "此命令只能在群组中使用。", "审核命令")
                yield self._yield_plain(event,"此命令只能在群组中使用。")
                event.stop_event()
                return
            set_audit_settings(group_id, "enabled", True)
            set_feature_enabled(group_id, "audit_enabled", True, self.config)
            logger.debug(f"handle_audit_commands: 已开启群 {group_id} 审核功能")
            self._log_send(event, "✅ 已开启入群审核", "审核命令")
            yield self._yield_plain(event,"✅️ 已开启入群审核\n 可使用 /克隆全局 一次性启用所有功能")
            event.stop_event()
            return
        elif cmd == "关闭审核":
            logger.debug("handle_audit_commands: 处理 关闭审核")
            if not await self._is_admin_or_owner_async(event):
                self._log_send(event, "只有管理员或群主才能执行此操作。", "审核命令")
                yield self._yield_plain(event,"只有管理员或群主才能执行此操作。")
                event.stop_event()
                return
            group_id = self._get_group_id_from_event(event)
            if not group_id or group_id == "None":
                self._log_send(event, "此命令只能在群组中使用。", "审核命令")
                yield self._yield_plain(event,"此命令只能在群组中使用。")
                event.stop_event()
                return
            set_audit_settings(group_id, "enabled", False)
            set_feature_enabled(group_id, "audit_enabled", False, self.config)
            logger.debug(f"handle_audit_commands: 已关闭群 {group_id} 审核功能")
            self._log_send(event, "❌ 已关闭入群审核", "审核命令")
            yield self._yield_plain(event,"❌️ 已关闭入群审核")
            event.stop_event()
            return
        
        # 设置命令（审核模式等）即使审核功能没开启也能执行
        if cmd == "审核" or command_name == "设置审批模式":
            async for result in self._handle_set_approval_mode(event):
                yield result
            event.stop_event()
            return
        
        # 设置命令（审核超时、审核次数）即使审核功能没开启也能执行
        if command_name in {"审核超时", "设置验证超时"}:
            async for result in self._handle_set_verification_timeout(event):
                yield result
            event.stop_event()
            return
        elif command_name in {"审核次数", "设置验证次数", "设置验证最大尝试"}:
            async for result in self._handle_set_max_verify_attempts(event):
                yield result
            event.stop_event()
            return
        elif command_name == "设置验证类型":
            async for result in self._handle_set_verification_type(event):
                yield result
            event.stop_event()
            return
        
        # 其他命令需要检查审核功能是否开启
        if not self._check_feature_cached(event, self.qqadmin_enable_audit, "audit_enabled"):
            return
        
        if cmd.startswith("审核通过"):
            async for result in self._handle_approve_audit_user(event):
                yield result
            event.stop_event()
        elif cmd == "审批"or cmd.startswith("审批 "):
            async for result in self._handle_approve_audit_direct(event):
                yield result
            event.stop_event()
        elif cmd == "拒绝"or cmd.startswith("拒绝 "):
            async for result in self._handle_reject_by_code(event):
                yield result
            event.stop_event()
        elif cmd == "查看待审核":
            async for result in self._handle_list_pending_audit(event):
                yield result
            event.stop_event()
        elif cmd.startswith("添加白名单"):
            async for result in self._handle_add_whitelist(event):
                yield result
            event.stop_event()
        elif cmd.startswith("移除白名单"):
            async for result in self._handle_remove_whitelist(event):
                yield result
            event.stop_event()
        elif cmd == "开启验证":
            async for result in self._handle_enable_verification(event):
                yield result
            event.stop_event()
        elif cmd == "关闭验证":
            async for result in self._handle_disable_verification(event):
                yield result
            event.stop_event()
        elif cmd == "验证提示":
            async for result in self._handle_show_verification_hint(event):
                yield result
            event.stop_event()

