    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE, priority=11000)
    async def handle_group_steamid_privacy(self, event: AstrMessageEvent) -> None:
        """Recall group-posted SteamIDs before message archival/other handlers."""
        group_id = self._get_group_id_from_event(event)
        if not group_id:
            return
        if not self._event_allows_primary_group_bot(event, group_id):
            event.stop_event()
            return
        message = self._get_event_message_text(event)
        user_id = self._get_sender_id_from_event(event)
        # Avoid loading sign-in policy/audit state for the bot's own echoed
        # outbound message. The echo is not a member binding attempt.
        self_id = self._get_event_self_id(event)
        if user_id and self_id and user_id == self_id:
            event.stop_event()
            return
        policy = self._get_signin_policy(group_id)
        from .qqadmin.audit import get_pending_verification
        pending = get_pending_verification(group_id, user_id) or {}
        pending_steamid = (
            bool(pending.get("steamid_stage", False))
            or str(pending.get("approval_mode", "") or "") == "steamid"
        )
        if await self._is_event_from_bot(event, user_id):
            return
        # Only an explicit binding command is a group-side binding attempt.
        # A bare 17-digit value is ordinary chat unless this member is in the
        # private-only SteamID admission stage; never turn every numeric post
        # into an unsolicited binding prompt.
        try:
            bind_aliases = self._get_signin_command_settings(group_id).get(
                "bind_aliases", ("绑定SteamID",)
            )
        except Exception:
            bind_aliases = ("绑定SteamID", "绑定steam", "绑定Steam", "绑定steamid")
        alias_pattern = "|".join(
            re.escape(str(alias)) for alias in bind_aliases if str(alias).strip()
        ) or r"绑定(?:\s*(?:steamid|steam))"
        server_binding_command = self._is_server_binding_command(message)
        binding_command = bool(
            not server_binding_command
            and (
                re.match(rf"^/?(?:{alias_pattern})(?:\s|$)", message, re.IGNORECASE)
                or re.match(
                    r"^/?绑定(?:\s*(?:steam\s*id|steam))(?:\s|$)",
                    message,
                    re.IGNORECASE,
                )
            )
        )
        if not binding_command:
            return
        submitted_steam_id = re.search(r"(?<!\d)\d{17}(?!\d)", message)
        message_id = self._get_event_message_id(event)
        if message_id is not None and bool(policy.get("recall_group_steam_binding_message", True)):
            recalled = await self._delete_msg(
                message_id,
                context=self.context,
                group_id=group_id,
            )
            if not recalled:
                logger.warning(
                    "群内 SteamID 绑定命令撤回失败 group=%s user=%s message_id=%s",
                    group_id,
                    user_id,
                    message_id,
                )
        # Always try the private prompt first, including when the group
        # binding switch is disabled and there is no pending audit record.
        # The helper never exposes a SteamID instruction or value in group
        # chat when private delivery is unavailable.
        await self._prompt_steamid_submission(
            event,
            group_id,
            user_id,
            steam_id=submitted_steam_id.group(0) if submitted_steam_id else "",
        )
        logger.info(
            "已在高优先级处理群内 SteamID 并撤回 group=%s user=%s",
            group_id,
            user_id,
        )
        event.stop_event()

    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE, priority=11900)
    async def handle_direct_verification(self, event: AstrMessageEvent) -> None:
        from .qqadmin.audit import (get_pending_verification, verify_answer, approve_join_request,
                                     remove_pending_request, remove_challenge,
                                     get_max_verify_attempts, increment_pending_attempts,
                                     get_group_data, get_verification_timeout,
                                     mark_pending_steamid_warning,
                                     is_verification_expired,
                                     normalize_verification_answer,
                                     restore_pending_challenge,
                                     mark_pending_kick_exhausted,
                                     should_kick_on_verification_failure)
        
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            return
        if not self._event_allows_primary_group_bot(event, group_id):
            event.stop_event()
            return
        sender_id = self._get_sender_id_from_event(event)
        self_id = self._get_event_self_id(event)
        if sender_id and self_id and sender_id == self_id:
            event.stop_event()
            return
        # 从群配置读取开关，而不是只读全局默认值。这样 Linux 网页保存的
        # 单群审核开关同步到 Windows 后会立刻影响验证处理。
        from .qqadmin.group_config import is_feature_enabled
        if not is_feature_enabled(group_id, "audit", self.config):
            return
        if not self._can_send_group_message(group_id):
            return
        
        user_id = self._get_sender_id_from_event(event)
        message_str = (event.message_str or "").strip()
        
        if not message_str:
            return
        
        # 跳过命令格式的消息（让专门的命令处理器处理）
        if self._is_command_message(event):
            return
        
        # 如果消息包含"帮助"、"菜单"、"专属回复"等关键词，跳过（让命令处理器处理）
        help_keywords = ["帮助", "菜单", "命令", "专属回复", "黑名单", "禁言", "踢出", 
                        "撤回", "欢迎", "自动回复", "签到", "排行榜", "定时消息", 
                        "入群审核", "分群管理", "群设置", "群管功能", "审核设置",
                        "群白名单", "过滤群", "功能开关", "群数据", "统计数据",
                        "审核列表", "审核模式", "验证模式", "同意", "拒绝",
                        "用户专属回复系统", "专属回复系统", "设置验证", "查看系统设置",
                        "文转图", "开启文转图", "关闭文转图"]
        for keyword in help_keywords:
            if keyword in message_str:
                logger.debug(f"跳过包含命令关键词的消息: {message_str}")
                # 不停止事件传播，让其他处理器（如 handle_audit_commands）处理
                return
        
        # 根据验证模式统一规范化用户输入（宽松匹配：支持前缀文字、空格、特殊符号包裹）
        import re
        from astrbot.core.message.components import At, Plain
        answer = ""
        pending = get_pending_verification(group_id, user_id)
        if pending:
            approval_mode = pending.get("approval_mode", "direct")
            steamid_stage = bool(pending.get("steamid_stage", False))
            if steamid_stage:
                approval_mode = "steamid"
        else:
            logger.debug(f"用户 {user_id} 不在待验证队列中")
            return
        # Once the configured limit has been reached and QQ could not confirm
        # the kick, keep this prompt terminal instead of consuming 4/3, 5/3…
        # on every later group message.
        if pending.get("verification_kick_exhausted"):
            # Do not keep deleting every later message.  The failed kick is
            # recorded and the event is stopped, but message recall belongs to
            # the explicit blacklist/recall policy, not to this retry guard.
            logger.warning(
                "验证踢出未确认，跳过后续消息撤回 group=%s user=%s",
                group_id,
                user_id,
            )
            event.stop_event()
            return
        prompt_delivered = bool(
            pending.get("verification_prompt_sent", False)
            or pending.get("steamid_prompt_sent", False)
        )
        if not prompt_delivered:
            remove_pending_request(group_id, user_id)
            challenge_id = pending.get("challenge_id")
            if challenge_id:
                remove_challenge(group_id, challenge_id)
            self._update_invite_status_if_enabled(group_id, user_id, "joined")
            event.stop_event()
            return
        if prompt_delivered and is_verification_expired(group_id, user_id):
            if not should_kick_on_verification_failure(group_id):
                remove_pending_request(group_id, user_id)
                challenge_id = pending.get("challenge_id")
                if challenge_id:
                    remove_challenge(group_id, challenge_id)
                self._update_invite_status_if_enabled(group_id, user_id, "rejected")
                self._schedule_verification_recall(
                    group_id,
                    user_id,
                    context=self.context,
                    bot=getattr(event, "bot", None),
                )
                add_operation_log(
                    group_id,
                    "system",
                    "自动系统",
                    "验证超时",
                    user_id,
                    "",
                    "验证超时，未移出群聊（已关闭失败踢出）",
                )
                yield self._yield_plain(event, "验证已超时，未移出群聊。")
                return
            from .qqadmin.kick import kick_user_api

            verification_bot = self._verification_bot_for_pending(
                group_id, pending, self._get_event_platform_id(event)
            ) or getattr(event, "bot", None)
            kicked = await kick_user_api(
                group_id,
                user_id,
                "验证超时未完成",
                context=self.context,
                platform_id=self._get_event_platform_id(event),
                bot=verification_bot,
            )
            if kicked:
                remove_pending_request(group_id, user_id)
                challenge_id = pending.get("challenge_id")
                if challenge_id:
                    remove_challenge(group_id, challenge_id)
                self._update_invite_status_if_enabled(group_id, user_id, "rejected")
                self._schedule_verification_recall(
                    group_id,
                    user_id,
                    context=self.context,
                    bot=getattr(event, "bot", None),
                )
                timeout_message = f"@{user_id} 验证已超时，已移出群聊。"
            else:
                timeout_message = f"@{user_id} 验证超时，踢出失败。"
            target_name = str(pending.get("user_name", "") or user_id).strip()[:80]
            add_operation_log(
                group_id,
                "system",
                "自动系统",
                "验证超时",
                user_id,
                target_name,
                "验证超时，" + ("已移出群聊" if kicked else "移出群聊失败"),
            )
            add_operation_log(
                group_id,
                "system",
                "自动系统",
                "踢出",
                user_id,
                target_name,
                "验证超时自动移出群聊" if kicked else "验证超时移出群聊失败",
            )
            await self._send_group_msg(
                group_id,
                timeout_message,
                context=self.context,
                bot=getattr(event, "bot", None),
            )
            event.stop_event()
            return
        if await self._is_event_from_bot(event, user_id):
            return

        # The same member message is delivered once per connected QQ account
        # when multiple bot logins share a group.  Without a message-level
        # claim, one wrong answer consumes two attempts and a correct answer
        # can send duplicate welcome messages.  Prefer the immutable OneBot
        # message id; older adapters fall back to their event timestamp.
        event_account = self._get_event_self_id(event)
        if event_account and not self._is_primary_group_bot(event, group_id):
            event.stop_event()
            return
        raw_event = self._get_event_raw_payload(event)
        verification_token = str(
            self._get_event_message_id(event)
            or raw_event.get("message_id", "")
            or raw_event.get("time", "")
            or ""
        ).strip()
        if verification_token and not self._claim_group_admission_event(
            "verification", group_id, user_id, verification_token
        ):
            logger.debug(
                "跳过重复验证答案 group=%s user=%s message=%s",
                group_id,
                user_id,
                verification_token,
            )
            event.stop_event()
            return

        if approval_mode == "steamid":
            # Admission SteamID checks are private-only. Group text, including
            # short numeric replies and messages from other bots, must never
            # be treated as a malformed SteamID or consume verification tries.
            return

        message_stripped = message_str.strip()
        answer = normalize_verification_answer(message_stripped, approval_mode)
        if not answer:
            logger.debug(
                "[入群验证] 跳过无有效答案输入: 用户=%s 模式=%s 消息=%s",
                user_id,
                approval_mode,
                message_str,
            )
            return
        
        pending = get_pending_verification(group_id, user_id)
        if not pending:
            return
        
        logger.debug(f"检测到待验证用户 {user_id} 发送消息: {message_str}")
        
        # 从 pending 中获取实际的 approval_mode（与入群时一致）
        approval_mode = pending.get("approval_mode", "direct")
        max_attempts = get_max_verify_attempts(group_id)
        if approval_mode in {"math", "id"} and restore_pending_challenge(group_id, pending):
            logger.warning(
                "恢复缺失的入群验证挑战 group=%s user=%s mode=%s",
                group_id,
                user_id,
                approval_mode,
            )
        verification_mode_label = {
            "math": "算数验证",
            "id": "ID验证",
            "code": "验证码验证",
            "direct": "直接验证",
            "steamid": "SteamID验证",
        }.get(str(approval_mode or "").strip().lower(), "入群验证")
        
        # 处理不同验证模式
        steamid_failure_message = ""
        steamid_failure_code = ""
        game_player_name = ""
        if approval_mode == "steamid":
            if not re.fullmatch(r"[0-9]{17}", answer):
                is_correct = False
                correct_code = ""
                steamid_failure_code = "invalid_steam_id"
                steamid_failure_message = self._steamid_failure_message(
                    {"code": steamid_failure_code}, answer
                )
                add_operation_log(
                    group_id,
                    "system",
                    "自动系统",
                    "验证失败",
                    user_id,
                    str(pending.get("user_name", "") or user_id).strip()[:80],
                    f"{verification_mode_label}格式无效，保留验证记录",
                )
                # A malformed value is a correctable input error, not a failed
                # human check. Keep the SteamID stage active and warn once.
                if mark_pending_steamid_warning(group_id, user_id, "format"):
                    await self._send_group_msg(
                        group_id,
                        steamid_failure_message + "请重新私聊发送，不要在群里公开 SteamID。",
                        context=self.context,
                        bot=getattr(event, "bot", None),
                    )
                event.stop_event()
                return
            else:
                # Reuse the same Windows-authoritative FTP snapshot path used
                # by sign-in and database rewards.
                validation = await self._validate_group_steam_id(group_id, answer)
                is_correct = validation.get("success") is True
                correct_code = ""
                if is_correct:
                    game_player_name = self._steam_player_name_from_validation(validation)
                    binding_result = bind_steam_id(
                        group_id,
                        user_id,
                        answer,
                        game_player_name or str(pending.get("user_name", "") or user_id),
                        database_validator=lambda _steam_id: dict(validation),
                        source="admission",
                    )
                    is_correct = binding_result.get("success") is True
                    if not is_correct:
                        validation = binding_result
                if not is_correct:
                    steamid_failure_code = str(
                        validation.get("code", "") or ""
                    ).strip().lower()
                    steamid_failure_message = self._steamid_failure_message(
                        validation, answer
                    )

            if not is_correct:
                add_operation_log(
                    group_id,
                    "system",
                    "自动系统",
                    "验证失败",
                    user_id,
                    str(pending.get("user_name", "") or user_id).strip()[:80],
                    f"SteamID验证失败：{steamid_failure_code or 'unknown'}；准备备用验证",
                )
                if steamid_failure_code in {"steam_in_use", "user_already_bound"}:
                    await self._send_group_msg(
                        group_id,
                        self._steamid_failure_message(validation, answer),
                        context=self.context,
                        bot=getattr(event, "bot", None),
                    )
                    event.stop_event()
                    return
                fallback = self._switch_steamid_to_random_fallback(
                    group_id, user_id, reason=steamid_failure_code, allowed_modes=("math", "id")
                )
                if fallback.get("success"):
                    fallback["failure_message"] = steamid_failure_message
                    fallback_mode = str(fallback.get("approval_mode", "") or "")
                    if fallback_mode not in {"math", "id"}:
                        logger.error(
                            "SteamID 验证返回非法备用模式 group=%s user=%s mode=%s",
                            group_id,
                            user_id,
                            fallback_mode or "<empty>",
                        )
                        await self._send_group_msg(
                            group_id,
                            steamid_failure_message
                            + "\n备用数学/ID 人机验证创建失败，请稍后重试。",
                            context=self.context,
                            bot=getattr(event, "bot", None),
                        )
                    else:
                        from .qqadmin.audit import get_verification_timeout

                        fallback_msg_id = await self._send_group_msg_with_id(
                            group_id,
                            self._steamid_fallback_prompt(
                                fallback,
                                timeout=get_verification_timeout(group_id),
                            ),
                            context=self.context,
                            bot=getattr(event, "bot", None),
                            console_force_output=True,
                        )
                        if fallback_msg_id:
                            self._remember_verification_message(
                                group_id, user_id, fallback_msg_id, bot=getattr(event, "bot", None)
                            )
                        logger.info(
                            "SteamID 验证未通过，已切换备用真人验证 group=%s user=%s mode=%s code=%s",
                            group_id,
                            user_id,
                            fallback_mode,
                            steamid_failure_code,
                        )
                else:
                    await self._send_group_msg(
                        group_id,
                        steamid_failure_message
                        + "\n备用数学/ID 人机验证创建失败，请联系管理员处理。",
                        context=self.context,
                        bot=getattr(event, "bot", None),
                    )
                # The SteamID attempt has now been converted into a new
                # challenge. Prevent lower-priority handlers from consuming
                # the same message and leaving the fallback challenge idle.
                event.stop_event()
                return
        elif approval_mode == "math":
            challenge_id = pending.get("challenge_id", "")
            is_correct, should_reject = verify_answer(
                group_id, challenge_id, answer, max_attempts=max_attempts
            )
            challenges = get_group_data(group_id, "audit_challenges", {})
            correct_code = challenges.get(challenge_id, {}).get("answer", "")
            logger.debug(f"数学验证比对: 用户输入='{answer}', 结果={is_correct}")
        elif approval_mode == "id":
            # 统一使用 verify_answer，从 challenge 对象中正确读取 verify_id 字段（避免取错verification_question）
            challenge_id = pending.get("challenge_id", "")
            is_correct, should_reject = verify_answer(
                group_id, challenge_id, answer, max_attempts=max_attempts
            )
            challenges = get_group_data(group_id, "audit_challenges", {})
            correct_code = challenges.get(challenge_id, {}).get("verify_id", "")
            logger.debug(f"[ID验证比对] 用户:{user_id} | 输入='{answer}' | 正确='{correct_code}' | 结果={is_correct} | 超限={should_reject}")
        elif approval_mode in ["code", "direct"]:
            correct_code = pending.get("approval_code", "")
            correct_code = normalize_verification_answer(correct_code, approval_mode)
            is_correct = (answer == correct_code)
            logger.debug(f"验证码比对: 用户输入='{answer}', approval_code='{correct_code}', 结果={is_correct}")
        else:
            correct_code = pending.get("approval_code", "")
            correct_code = normalize_verification_answer(correct_code, approval_mode)
            is_correct = (answer == correct_code)
            logger.debug(f"验证码比对(默认): 用户输入='{answer}', approval_code='{correct_code}', 结果={is_correct}")
        
        if is_correct:
            # A standalone math/ID challenge is a complete admission flow.
            # SteamID admission has its own explicit stage above, and a failed
            # SteamID lookup marks the fallback with ``steamid_fallback``.
            # Do not force a database-backed group configured for math/ID into
            # a second SteamID step: that left the pending row alive until the
            # timeout even after the human verification was answered correctly.
            approve_join_request(group_id, user_id, "system", "验证通过")
            # Keep the admission state explicit even when an older audit
            # implementation only changed the status instead of removing the
            # row.  A correct answer must never be treated as another attempt.
            remove_pending_request(group_id, user_id)
            add_operation_log(
                group_id,
                "system",
                "自动系统",
                "验证通过",
                user_id,
                str(pending.get("user_name", "") or user_id).strip()[:80],
                f"{verification_mode_label}通过",
            )
            # 清理挑战数据
            challenge_id = pending.get("challenge_id")
            if challenge_id:
                remove_challenge(group_id, challenge_id)
                logger.debug(f"验证成功，清理挑战数据: {challenge_id}")

            # 验证成功后延迟撤回验证消息（等待撤回功能设置的时间）
            self._schedule_verification_recall(group_id, user_id, context=self.context)

            if (
                approval_mode == "steamid"
                and game_player_name
                and self._steam_name_as_group_card_enabled(group_id)
            ):
                if not await self._set_group_card_from_game_name(
                    group_id, user_id, game_player_name
                ):
                    self._queue_group_card_update(
                        group_id, user_id, game_player_name
                    )
                    logger.warning(
                        "SteamID 已验证但 QQ 群名片设置失败 group=%s user=%s",
                        group_id,
                        user_id,
                    )

            from astrbot.core.message.components import At, Plain
            from .qqadmin.welcome import (
                format_welcome_message,
                is_welcome_enabled,
                log_welcome,
            )
            display_name = await self._get_welcome_display_name(
                group_id,
                user_id,
                event=event,
                fallback=game_player_name or pending.get("user_name", ""),
            )
            welcome_enabled = bool(self.qqadmin_enable_welcome or is_welcome_enabled(group_id))
            if welcome_enabled:
                success_msg = format_welcome_message(group_id, user_id, display_name)
                if not success_msg:
                    success_msg = self.qqadmin_default_welcome_message.format(
                        user_id=user_id,
                        user_name=display_name,
                        group_id=group_id,
                        time=time.strftime("%Y-%m-%d %H:%M:%S", time.localtime()),
                    )
            else:
                success_msg = f"验证成功！欢迎 {display_name} 加入本群！"
            if approval_mode == "steamid":
                success_msg = self._group_reply_template(
                    group_id,
                    "audit",
                    "steamid_success_message",
                    {
                        "user_name": display_name,
                        "name": display_name,
                        "user_id": user_id,
                        "qq": user_id,
                        "steam_id": answer,
                        "group_id": group_id,
                    },
                    "SteamID 验证成功，欢迎 {user_name} 加入本群！",
                )
            # 使用一次直接 call_action 发送，避免验证成功提示和欢迎语
            # 各发一条；Plain 前的空格保证艾特后文字不会粘连。
            success_chain = [At(qq=int(user_id)), Plain(" " + success_msg)]
            # Treat the successful bot notice as a normal outbound message so
            # the configured self-recall policy can remove it as well.
            await self._send_group_msg_with_id(
                group_id,
                success_chain,
                context=self.context,
                auto_recall=True,
                bot=getattr(event, "bot", None),
            )
            if welcome_enabled:
                log_welcome(group_id, user_id, display_name, "audit")
            logger.debug(f"用户 {user_id} 验证成功")
            
            # 更新邀请状态为已入群
            self._update_invite_status_if_enabled(group_id, user_id, "joined")
            logger.debug(f"更新邀请状态: user_id={user_id}, group_id={group_id}, status=joined")
            
            event.stop_event()
        else:
            from astrbot.core.message.components import At, Plain
            
            def build_fail_chain_at(message_text: str):
                return [At(qq=int(user_id)), Plain(" " + message_text)]

            # A recalled, failed, or unavailable prompt must never turn into
            # a kick.  Re-read the durable pending row before consuming an
            # attempt so this guard also covers races with prompt delivery.
            current_pending = get_pending_verification(group_id, user_id)
            if not current_pending:
                logger.debug(
                    "用户 %s 已不在 pending 队列中，跳过验证失败处理",
                    user_id,
                )
                event.stop_event()
                return
            prompt_delivered = bool(
                current_pending.get("verification_prompt_sent", False)
                or current_pending.get("steamid_prompt_sent", False)
            )
            if not prompt_delivered:
                logger.warning(
                    "验证提示未确认发送，跳过失败计数和踢人 group=%s user=%s",
                    group_id,
                    user_id,
                )
                remove_pending_request(group_id, user_id)
                challenge_id = current_pending.get("challenge_id")
                if challenge_id:
                    remove_challenge(group_id, challenge_id)
                self._update_invite_status_if_enabled(group_id, user_id, "joined")
                event.stop_event()
                return

            try:
                stored_attempts = max(0, int(pending.get("attempts", 0) or 0))
            except (TypeError, ValueError, OverflowError):
                stored_attempts = 0
            # A previous process may have already reached the limit before it
            # was restarted.  Never increment that persisted value beyond the
            # configured maximum.
            current_attempts = increment_pending_attempts(group_id, user_id) if stored_attempts < max_attempts else max_attempts

            if current_attempts >= max_attempts:
                # Re-check the sent marker after incrementing.  The prompt
                # record is durable and is intentionally independent from
                # message recall, so recalling the QQ message cannot disable
                # this admission decision.
                current_pending = get_pending_verification(group_id, user_id)
                prompt_delivered = bool(
                    current_pending
                    and (
                        current_pending.get("verification_prompt_sent", False)
                        or current_pending.get("steamid_prompt_sent", False)
                    )
                )
                if not prompt_delivered:
                    logger.warning(
                        "验证提示在失败处理期间变为未发送，跳过踢人 group=%s user=%s",
                        group_id,
                        user_id,
                    )
                    remove_pending_request(group_id, user_id)
                    challenge_id = current_pending.get("challenge_id")
                    if challenge_id:
                        remove_challenge(group_id, challenge_id)
                    self._update_invite_status_if_enabled(group_id, user_id, "joined")
                    event.stop_event()
                    return

                if not should_kick_on_verification_failure(group_id):
                    self._schedule_verification_recall(
                        group_id, user_id, context=self.context
                    )
                    remove_pending_request(group_id, user_id)
                    challenge_id = current_pending.get("challenge_id")
                    if challenge_id:
                        remove_challenge(group_id, challenge_id)
                    self._update_invite_status_if_enabled(group_id, user_id, "rejected")
                    target_name = str(
                        current_pending.get("user_name", "") or pending.get("user_name", "") or user_id
                    ).strip()[:80]
                    reason = f"{verification_mode_label}失败，第 {current_attempts}/{max_attempts} 次；未移出群聊（已关闭失败踢出）"
                    add_operation_log(
                        group_id,
                        "system",
                        "自动系统",
                        "验证失败",
                        user_id,
                        target_name,
                        reason,
                    )
                    await self._send_group_msg_with_id(
                        group_id,
                        build_fail_chain_at(
                            f"验证失败（{current_attempts}/{max_attempts}）。未移出群聊。"
                        ),
                        context=self.context,
                        auto_recall=True,
                        bot=getattr(event, "bot", None),
                    )
                    event.stop_event()
                    return

                kicked = False
                kick_error = ""
                try:
                    verification_bot = self._verification_bot_for_pending(
                        group_id,
                        current_pending,
                        self._get_event_platform_id(event),
                    ) or getattr(event, "bot", None)
                    if not callable(getattr(verification_bot, "call_action", None)):
                        platform = None
                        platform_id = self._get_event_platform_id(event)
                        if platform_id and callable(getattr(self.context, "get_platform_inst", None)):
                            platform = self.context.get_platform_inst(str(platform_id))
                        if platform is None:
                            platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                        if not platform:
                            raise RuntimeError("无法获取验证消息对应的 QQ 平台实例")
                        verification_bot = platform.get_client()
                    api_result = await verification_bot.call_action(
                        action="set_group_kick",
                        group_id=int(group_id),
                        user_id=int(user_id),
                        reject_add_request=False,
                    )
                    if not self._api_result_succeeded(api_result):
                        detail = ""
                        if isinstance(api_result, dict):
                            detail = str(
                                api_result.get("message")
                                or api_result.get("msg")
                                or api_result.get("wording")
                                or api_result.get("retcode")
                                or ""
                            ).strip()
                        if "uid" in detail.lower() or "user" in detail.lower():
                            retry_result = await verification_bot.call_action(
                                action="set_group_kick",
                                group_id=str(group_id),
                                user_id=str(user_id),
                                reject_add_request=False,
                            )
                            if self._api_result_succeeded(retry_result):
                                api_result = retry_result
                            elif isinstance(retry_result, dict):
                                detail = str(
                                    retry_result.get("message")
                                    or retry_result.get("msg")
                                    or retry_result.get("wording")
                                    or retry_result.get("retcode")
                                    or detail
                                ).strip()
                        if self._api_result_succeeded(api_result):
                            kicked = True
                        elif await self._confirm_member_absent(
                            verification_bot, group_id, user_id
                        ):
                            # A second kick can race with QQ's membership
                            # update and return a blank rejection even though
                            # the member has already left the group.
                            kicked = True
                            logger.info(
                                "验证失败用户已不在群内，按已移出处理 group=%s user=%s",
                                group_id,
                                user_id,
                            )
                        else:
                            raise RuntimeError(
                                detail or "QQ 平台拒绝了验证失败踢出请求"
                            )
                    else:
                        kicked = True
                    logger.info(
                        "验证失败已移出群聊 group=%s user=%s attempts=%s/%s",
                        group_id,
                        user_id,
                        current_attempts,
                        max_attempts,
                    )
                except Exception as exc:
                    kick_error = str(exc) or type(exc).__name__
                    logger.error(
                        "验证失败踢人未成功，保留待验证记录 group=%s user=%s error=%s",
                        group_id,
                        user_id,
                        kick_error,
                    )

                if kicked:
                    # Recall only the visible prompt; the challenge and its
                    # sent marker remain durable until this successful result.
                    self._schedule_verification_recall(
                        group_id, user_id, context=self.context
                    )
                    remove_pending_request(group_id, user_id)
                    self._update_invite_status_if_enabled(group_id, user_id, "rejected")
                else:
                    mark_pending_kick_exhausted(
                        group_id,
                        user_id,
                        kick_error or "QQ 平台未确认验证失败踢出请求",
                    )

                target_name = str(
                    current_pending.get("user_name", "") or pending.get("user_name", "") or user_id
                ).strip()[:80]
                failure_reason = (
                    f"{verification_mode_label}失败，第 {current_attempts}/{max_attempts} 次"
                )
                if kicked:
                    failure_reason += "；已移出群聊"
                elif kick_error:
                    failure_reason += f"；移出失败：{kick_error[:120]}"
                add_operation_log(
                    group_id,
                    "system",
                    "自动系统",
                    "验证失败并移出" if kicked else "验证失败",
                    user_id,
                    target_name,
                    failure_reason,
                )
                add_operation_log(
                    group_id,
                    "system",
                    "自动系统",
                    "踢出",
                    user_id,
                    target_name,
                    (
                        f"验证失败达到 {current_attempts}/{max_attempts} 次，已移出群聊"
                        if kicked
                        else f"验证失败达到 {current_attempts}/{max_attempts} 次，移出群聊失败"
                    ),
                )

                if kicked and self._should_auto_blacklist_after_verification_failure(group_id):
                    from .qqadmin.blacklist import add_to_blacklist
                    add_to_blacklist(
                        group_id,
                        user_id,
                        reason="验证失败",
                        operator_id="system",
                        ban_type="permanent",
                    )
                    add_operation_log(
                        group_id,
                        "system",
                        "自动系统",
                        "拉黑",
                        user_id,
                        target_name,
                        f"验证失败达到 {current_attempts}/{max_attempts} 次，自动加入黑名单",
                    )
                    fail_msg = f"验证失败（{current_attempts}/{max_attempts}）。已踢出并拉黑。"
                elif kicked:
                    fail_msg = f"验证失败（{current_attempts}/{max_attempts}）。已踢出。"
                else:
                    fail_msg = f"验证失败（{current_attempts}/{max_attempts}）。踢人失败。"
                await self._send_group_msg_with_id(
                    group_id,
                    build_fail_chain_at(fail_msg),
                    context=self.context,
                    auto_recall=True,
                    bot=getattr(event, "bot", None),
                )
                event.stop_event()
            else:
                remaining_attempts = max_attempts - current_attempts
                add_operation_log(
                    group_id,
                    "system",
                    "自动系统",
                    "验证失败",
                    user_id,
                    str(current_pending.get("user_name", "") or pending.get("user_name", "") or user_id).strip()[:80],
                    f"{verification_mode_label}答案错误，第 {current_attempts}/{max_attempts} 次",
                )
                timeout = get_verification_timeout(group_id)
                requested_at = pending.get("requested_at", 0)
                elapsed_time = int(time.time()) - requested_at
                remaining_time = max(0, timeout - elapsed_time)
                
                if approval_mode == "steamid":
                    hint = steamid_failure_message or "请发送服务器数据库中存在的 17 位 SteamID64。"
                elif approval_mode == "math":
                    # Keep the active expression in the retry response.  The
                    # answer is deliberately not exposed; only the question
                    # stored with this user's challenge is shown again.
                    question = str(
                        challenges.get(challenge_id, {}).get("question", "")
                        or pending.get("verification_question", "")
                    ).strip()
                    hint = f"请重新计算：{question}" if question else "请重新计算"
                elif approval_mode == "id":
                    # Repeat the active ID explicitly. The original prompt
                    # may already have been recalled, so referring to it is
                    # not actionable for the member.
                    verification_id = str(
                        correct_code
                        or pending.get("verify_id", "")
                        or pending.get("verification_question", "")
                        or ""
                    ).strip()
                    hint = (
                        f"请发送验证 ID：{verification_id}"
                        if verification_id
                        else "请发送当前有效的 5 位验证 ID"
                    )
                else:
                    hint = f"请输入审批码: {correct_code}"
                
                error_msg = (
                    f"答案错误！\n"
                    f"第 {current_attempts}/{max_attempts} 次尝试\n"
                    f"还剩 {remaining_attempts} 次机会\n"
                    f"剩余验证时间: {remaining_time}秒\n"
                    f"{hint}"
                )
                await self._send_group_msg_with_id(
                    group_id,
                    build_fail_chain_at(error_msg),
                    context=self.context,
                    auto_recall=False,
                    bot=getattr(event, "bot", None),
                )
                event.stop_event()

