    @filter.event_message_type(filter.EventMessageType.OTHER_MESSAGE, priority=12000)
    async def handle_other_message_steamid_submission(self, event: AstrMessageEvent) -> None:
        """NapCat may classify friend messages as OTHER_MESSAGE; route them through the same private flow."""
        await self.handle_private_steamid_submission(event)

    @filter.event_message_type(filter.EventMessageType.ALL, priority=10000)
    async def handle_private_steamid_submission(self, event: AstrMessageEvent) -> None:
        """Validate a pending admission SteamID from a private message."""
        # Some OneBot adapters leave ``message_str`` empty for private
        # messages while still exposing the Plain component.
        message = self._get_event_message_text(event)
        # NapCat/aiocqhttp deployments may expose a direct message as
        # ``OTHER_MESSAGE`` instead of ``PRIVATE_MESSAGE``.  Listening to ALL
        # above covers that adapter variation; a real group event is rejected
        # here so the group privacy handler remains the sole group path.
        if self._is_group_event(event):
            return
        if not message:
            return
        logger.info(
            "SteamID 私聊兼容入口已接收消息 type=%s user=%s command=%s",
            str(getattr(getattr(event, "get_message_type", lambda: None)(), "value", "") or "private"),
            self._get_sender_id_from_event(event) or "-",
            message.split(maxsplit=1)[0][:40],
        )
        # A few adapters expose the complete command only in raw_message while
        # message_str contains the command name without its arguments. Read
        # both shapes before deciding that the command is empty.
        binding_payload = ""
        binding_command_seen = False
        binding_candidates = [message]
        raw_message = getattr(getattr(event, "message_obj", None), "raw_message", None)
        if isinstance(raw_message, dict):
            binding_candidates.extend(
                value
                for value in (raw_message.get("raw_message"), raw_message.get("message"))
                if isinstance(value, str)
            )
            segment_text = self._moderation_segments_to_text(raw_message.get("message"))
            if segment_text:
                binding_candidates.append(segment_text)
        elif isinstance(raw_message, str):
            binding_candidates.append(raw_message)
        else:
            for attr in ("raw_message", "message"):
                value = getattr(raw_message, attr, None)
                if isinstance(value, str):
                    binding_candidates.append(value)
                else:
                    segment_text = self._moderation_segments_to_text(value)
                    if segment_text:
                        binding_candidates.append(segment_text)
        for candidate in binding_candidates:
            candidate = str(candidate or "").strip()
            if not candidate:
                continue
            match = re.search(
                r"/\s*绑定\s*(?:steam\s*id|steam|id)?\s+(.+)$",
                candidate,
                re.IGNORECASE,
            )
            if match:
                binding_command_seen = True
                binding_payload = match.group(1).strip()
                break
            if re.fullmatch(r"/\s*绑定\s*(?:steam\s*id|steam|id)?", candidate, re.IGNORECASE):
                binding_command_seen = True
        if binding_command_seen:
                user_id = self._get_sender_id_from_event(event)
                from .qqadmin.audit import get_pending_steamid_request_by_user_all_groups

                submitted = binding_payload
                # A single SteamID after the private prompt uses the one
                # pending admission group; explicit group + SteamID remains
                # supported for ordinary private binding.
                if re.fullmatch(r"[0-9]{17}", submitted):
                    pending_group, pending_request = (
                        get_pending_steamid_request_by_user_all_groups(user_id)
                    )
                    if pending_group and isinstance(pending_request, dict):
                        submitted = f"{pending_group} {submitted}"
                    else:
                        await self._send_plain(
                            event,
                            "请私聊发送：/绑定SteamID <群号> <17位SteamID64>。\n"
                            "例如：/绑定SteamID 1102579807 76561198000000000",
                        )
                        event.stop_event()
                        return
                if not submitted:
                    await self._send_plain(
                        event,
                        "请私聊发送：/绑定SteamID <群号> <17位SteamID64>。\n"
                        "例如：/绑定SteamID 1102579807 76561198000000000",
                    )
                    event.stop_event()
                    return
                logger.info(
                    "私聊 SteamID 绑定兜底入口 group_arg=%s user=%s",
                    submitted.split(maxsplit=1)[0] if submitted else "-",
                    user_id,
                )
                async for result in self._bind_steam_id_for_event(event, submitted):
                    if result is not None:
                        # ``_bind_steam_id_for_event`` yields a framework
                        # MessageEventResult.  Direct ``event.send`` expects
                        # a MessageChain on newer AstrBot versions, so unwrap
                        # the result before sending the private reply.
                        chain = getattr(result, "chain", None)
                        if chain is not None:
                            from astrbot.core.message.message_event_result import MessageChain

                            if chain:
                                await event.send(MessageChain(chain=list(chain)))
                        else:
                            await event.send(result)
                event.stop_event()
                return
        user_id = self._get_sender_id_from_event(event)
        from .qqadmin.audit import (
            get_pending_steamid_request_by_user_all_groups,
            approve_join_request,
            mark_pending_steamid_warning,
        )

        group_id, pending = get_pending_steamid_request_by_user_all_groups(user_id)
        group_id = str(group_id or "").strip()
        if not group_id or not isinstance(pending, dict):
            if message.isdigit():
                await self._send_plain(
                    event,
                    "这是普通 SteamID 绑定，请私聊发送完整命令：\n"
                    "/绑定SteamID <群号> <17位SteamID64>\n"
                    "例如：/绑定SteamID 1102579807 76561198000000000",
                )
                event.stop_event()
            return
        if not (
            str(pending.get("approval_mode", "") or "") == "steamid"
            or bool(pending.get("steamid_stage", False))
        ):
            return

        # Admission verification and ordinary ``/绑定SteamID`` are separate
        # flows. Only a bare numeric private message belongs to admission;
        # command messages are handled by the binding command below. When an
        # applicant sends a numeric value with the wrong length, answer once
        # in private and keep the SteamID stage active instead of silently
        # ignoring it or switching to a human challenge.
        match = re.fullmatch(r"[0-9]{17}", message)
        if not match:
            if mark_pending_steamid_warning(group_id, user_id, "format"):
                await self._send_plain(
                    event,
                    "入群验证需要 17 位 SteamID64。位数不正确，请重新私聊发送纯数字 SteamID；"
                    "普通绑定请使用 /绑定SteamID <群号> <SteamID>。",
                )
                event.stop_event()
            return

        steam_id = match.group(0)
        validation = await self._validate_group_steam_id(group_id, steam_id)
        game_name = self._steam_player_name_from_validation(validation)
        if validation.get("success") is True:
            binding = bind_steam_id(
                group_id,
                user_id,
                steam_id,
                game_name or str(pending.get("user_name", "") or "新成员"),
                database_validator=lambda _steam_id: dict(validation),
                source="admission",
            )
            # Re-submitting the same SteamID for the same QQ is idempotent.
            # It commonly happens when a tester leaves and rejoins while the
            # old local binding is still valid; it must not fall through to a
            # human challenge.
            binding_is_usable = (
                binding.get("success") is True
                or str(binding.get("code", "") or "").strip().lower()
                == "already_bound"
            )
            if binding_is_usable:
                binding_record = binding.get("binding")
                if isinstance(binding_record, dict):
                    game_name = game_name or str(
                        binding_record.get("user_name", "") or ""
                    ).strip()
                approve_join_request(
                    group_id,
                    user_id,
                    "system",
                    "SteamID 私聊数据库验证通过",
                )
                card_enabled = self._steam_name_as_group_card_enabled(group_id)
                if game_name and card_enabled:
                    if not await self._set_group_card_from_game_name(
                        group_id, user_id, game_name, bot=getattr(event, "bot", None)
                    ):
                        self._queue_group_card_update(group_id, user_id, game_name)
                await self._send_plain(
                    event,
                    f"SteamID 数据库验证成功，已完成入群验证。"
                    f"{('群名片已设置为：' + game_name) if game_name and card_enabled else ''}",
                )
                display_name = await self._get_welcome_display_name(
                    group_id,
                    user_id,
                    event=event,
                    fallback=game_name or pending.get("user_name", ""),
                )
                from astrbot.core.message.components import At, Plain
                steamid_success = self._group_reply_template(
                    group_id,
                    "audit",
                    "steamid_success_message",
                    {
                        "user_name": display_name,
                        "name": display_name,
                        "user_id": user_id,
                        "qq": user_id,
                        "steam_id": steam_id,
                        "group_id": group_id,
                    },
                    "SteamID 验证成功，欢迎 {user_name} 加入本群！",
                )
                await self._send_group_msg_with_id(
                    group_id,
                    [
                        At(qq=int(user_id)),
                        Plain(" " + steamid_success),
                    ],
                    context=self.context,
                    auto_recall=True,
                    bot=getattr(event, "bot", None),
                )
                self._update_invite_status_if_enabled(group_id, user_id, "joined")
                logger.info(
                    "私聊 SteamID 数据库验证成功 group=%s user=%s game_name=%s",
                    group_id,
                    user_id,
                    game_name or "-",
                )
                event.stop_event()
                return
            validation = binding

        reason = str(validation.get("code", "") or "query_error").strip().lower()
        if reason in {"steam_in_use", "user_already_bound"}:
            # These are binding conflicts, not proof that the applicant is a
            # bot and not a database outage.  Keep admission automatic and
            # tell the user/admin what must be cleaned up.
            if reason == "steam_in_use":
                message = (
                    "该 SteamID 已绑定其他 QQ，未重复绑定。"
                    "请联系群管理员使用 /删除绑定 <SteamID> 后重新提交。"
                )
            else:
                message = (
                    "该 QQ 已绑定其他 SteamID，未覆盖原绑定。"
                    "请联系群管理员先删除旧绑定后重新提交。"
                )
            await self._send_plain(event, message)
            logger.info(
                "私聊 SteamID 绑定冲突，未切换人机验证 group=%s user=%s reason=%s",
                group_id,
                user_id,
                reason,
            )
            event.stop_event()
            return
        # A correctly shaped but unknown SteamID gets one explicit private
        # explanation.  Repeated retries must not create duplicate fallback
        # challenges or flood the group with identical notices.
        if not mark_pending_steamid_warning(group_id, user_id, "not_found"):
            return
        fallback = self._switch_steamid_to_random_fallback(
            group_id,
            user_id,
            reason=reason or "not_found",
            allowed_modes=("math", "id"),
        )
        if fallback.get("success") and str(fallback.get("approval_mode", "")) in {"math", "id"}:
            fallback["failure_message"] = self._steamid_failure_message(validation, steam_id)
            from .qqadmin.audit import get_verification_timeout
            fallback_msg_id = await self._send_group_msg_with_id(
                group_id,
                self._steamid_fallback_prompt(
                    fallback,
                    timeout=get_verification_timeout(group_id),
                ),
                context=self.context,
                bot=getattr(event, "bot", None),
                console_force_output=True,
            )
            if fallback_msg_id:
                self._remember_verification_message(
                    group_id, user_id, fallback_msg_id, bot=getattr(event, "bot", None)
                )
            await self._send_plain(
                event,
                self._steamid_failure_message(validation, steam_id)
                + "\n已切换为群内数学/ID 人机验证，请回到群里完成验证。",
            )
            logger.info(
                "私聊 SteamID 未确认，已切换人机验证 group=%s user=%s mode=%s reason=%s",
                group_id,
                user_id,
                fallback.get("approval_mode"),
                reason,
            )
        else:
            await self._send_plain(
                event,
                self._steamid_failure_message(validation, steam_id)
                + "\n备用数学/ID 人机验证创建失败，请联系管理员处理。",
            )
            logger.error(
                "私聊 SteamID 备用人机验证创建失败 group=%s user=%s reason=%s",
                group_id,
                user_id,
                reason,
            )
        event.stop_event()

    # ==================== 撤回系统命令 ====================
    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE)
    async def handle_recall_commands(self, event: AstrMessageEvent) -> None:
        message_str = (event.message_str or "").strip()
        # Some OneBot adapters leave message_str empty for a Plain-only
        # message chain. Keep recall commands usable in that event shape.
        if not message_str:
            try:
                from astrbot.core.message.components import Plain

                message_str = "".join(
                    str(getattr(component, "text", "") or "")
                    for component in event.get_messages()
                    if isinstance(component, Plain)
                ).strip()
            except Exception:
                message_str = ""

        if not message_str.strip():
            return

        cmd = message_str.lstrip('/').strip().replace("\u3000", " ")
        cmd_name = cmd.split(maxsplit=1)[0] if cmd else ""

        # 检查用户是否正在进行验证，如果是，则跳过撤回命令处理
        from .qqadmin.audit import get_pending_verification
        group_id = self._get_group_id_from_event(event)
        user_id = self._get_sender_id_from_event(event)
        if group_id and group_id != "None"and user_id:
            pending = get_pending_verification(group_id, user_id)
            if pending:
                # 用户正在进行验证，跳过撤回命令处理
                logger.debug(f"用户 {user_id} 正在进行验证，跳过撤回命令处理")
                return

        if cmd_name in {"查看消息记录", "查看群消息"}:
            if not self._can_send_group_message(group_id):
                return
            async for result in self._handle_view_group_messages(event):
                yield result
            event.stop_event()
        elif cmd == "查看白名单":
            async for result in self._handle_list_audit_whitelist(event):
                yield result
            event.stop_event()
            return

        # 检查是否是撤回相关命令
        if cmd_name in {"查看撤回消息", "查看撤回记录"}:
            # Keep the read path as strict as outbound behavior.  Returning
            # without stopping lets the common command gate emit its normal
            # powered-off or expired prompt when applicable.
            if not self._can_send_group_message(group_id):
                return
            async for result in self._handle_view_recalled_messages(event):
                yield result
            event.stop_event()
            return

        recall_commands = ["开启撤回", "关闭撤回", "开启自身撤回", "关闭自身撤回",
                          "添加撤回关键词", "删除撤回关键词", "设置撤回模式",
                          "查看撤回关键词", "添加撤回正则", "删除撤回正则", "查看撤回正则",
                          "添加撤回白名单", "撤回", "设置撤回时间", "设置撤回数量", "设置撤回范围",
                          "开启撤回通知", "关闭撤回通知", "设置撤回通知",
                          "撤回帮助", "查看自身撤回", "查看撤回消息", "查看撤回记录",
                          "开启敏感词撤回", "关闭敏感词撤回",
                          "开启网址撤回", "关闭网址撤回",
                          "开启名片撤回", "关闭名片撤回",
                          "开启图片撤回", "关闭图片撤回",
                          "查看内容检测状态", "查看敏感词"]

        # 如果不是撤回相关命令，直接返回，让事件继续传递
        # 注意：单独的数字命令不触发撤回，必须是"撤回 数字"格式
        is_recall_command = cmd in recall_commands or \
                          cmd.startswith("添加撤回关键词") or \
                          cmd.startswith("删除撤回关键词") or \
                          cmd.startswith("设置撤回模式") or \
                          cmd.startswith("添加撤回正则") or \
                          cmd.startswith("删除撤回正则") or \
                          cmd == "查看撤回正则" or \
                          cmd.startswith("添加撤回白名单") or \
                          cmd.startswith("撤回 ") or cmd.startswith("撤回@") or \
                          cmd.startswith("设置撤回时间") or \
                          cmd.startswith("设置撤回数量") or \
                          cmd.startswith("设置撤回范围") or \
                          cmd.startswith("设置撤回通知") or \
                          cmd.startswith("开启自身撤回") or \
                          cmd.startswith("关闭自身撤回") or \
                          cmd.startswith("设置自身撤回时间") or \
                          cmd.startswith("查看自身撤回") or \
                          cmd.startswith("添加敏感词") or \
                          cmd.startswith("删除敏感词")
        
        # 排除单独数字的命令（必须使用"撤回 数字"格式）
        if cmd.isdigit():
            is_recall_command = False
        
        if not is_recall_command:
            return
        
        logger.debug(f"撤回命令处理: message_str='{message_str}', cmd='{cmd}'")

        # Configuration commands must remain usable while the recall master
        # switch is off; otherwise an administrator cannot add a keyword and
        # then enable the feature.  Actual message-recall operations still
        # obey the switch below.
        recall_configuration_command = (
            cmd in {
                "撤回帮助", "查看撤回关键词", "查看撤回正则", "查看自身撤回",
                "开启敏感词撤回", "关闭敏感词撤回", "查看内容检测状态", "查看敏感词",
                "开启网址撤回", "关闭网址撤回", "开启名片撤回", "关闭名片撤回",
                "开启图片撤回", "关闭图片撤回",
            }
            or cmd.startswith((
                "添加撤回关键词", "删除撤回关键词", "设置撤回模式",
                "添加撤回正则", "删除撤回正则", "添加撤回白名单",
                "设置撤回时间", "设置撤回数量", "设置撤回范围",
                "设置撤回通知", "设置自身撤回时间", "添加敏感词", "删除敏感词",
            ))
        )
        # An administrator's explicit ``/撤回`` request is a one-shot
        # moderation action, not the automatic keyword-recall switch.  It
        # must remain usable when automatic recall is disabled; otherwise the
        # command is silently ignored and looks as if the bot cannot recall.
        manual_recall_command = (
            cmd == "撤回" or cmd.startswith("撤回 ") or cmd.startswith("撤回@")
        )
        
        # 对于开启/关闭命令，只检查群管总开关和权限，不检查功能配置
        if cmd in ["开启撤回", "关闭撤回", "开启自身撤回", "关闭自身撤回"]:
            # 检查群管总开关
            if not getattr(self, 'qqadmin_enable_group_manage', True):
                return
            # 这些命令需要管理员权限，在处理函数中检查
        elif recall_configuration_command or manual_recall_command:
            if not getattr(self, 'qqadmin_enable_group_manage', True):
                return
        else:
            # 对于其他撤回命令，需要检查功能是否开启
            if not self._check_feature_cached(event, self.qqadmin_enable_recall, "recall_enabled"):
                return

        if cmd == "开启撤回":
            async for result in self._handle_enable_recall(event):
                yield result
            event.stop_event()
        elif cmd == "关闭撤回":
            async for result in self._handle_disable_recall(event):
                yield result
            event.stop_event()
        elif cmd == "开启自身撤回":
            async for result in self._handle_enable_self_recall(event):
                yield result
            event.stop_event()
        elif cmd == "关闭自身撤回":
            async for result in self._handle_disable_self_recall(event):
                yield result
            event.stop_event()
        elif cmd.startswith("添加撤回关键词"):
            async for result in self._handle_add_recall_keyword(event):
                yield result
            event.stop_event()
        elif cmd.startswith("删除撤回关键词"):
            async for result in self._handle_remove_recall_keyword(event):
                yield result
            event.stop_event()
        elif cmd.startswith("设置撤回模式"):
            async for result in self._handle_set_recall_mode(event):
                yield result
            event.stop_event()
        elif cmd == "查看撤回关键词":
            async for result in self._handle_list_recall_keywords(event):
                yield result
            event.stop_event()
        elif cmd.startswith("添加撤回正则"):
            async for result in self._handle_add_recall_regex(event):
                yield result
            event.stop_event()
        elif cmd.startswith("删除撤回正则"):
            async for result in self._handle_remove_recall_regex(event):
                yield result
            event.stop_event()
        elif cmd == "查看撤回正则":
            async for result in self._handle_list_recall_regex(event):
                yield result
            event.stop_event()
        elif cmd == "查看撤回消息"or cmd == "查看撤回记录":
            async for result in self._handle_view_recalled_messages(event):
                yield result
            event.stop_event()
        elif cmd.startswith("添加撤回白名单"):
            async for result in self._handle_add_recall_whitelist(event):
                yield result
            event.stop_event()
        elif cmd == "撤回" or cmd.startswith("撤回 ") or cmd.startswith("撤回@"):
            logger.debug(f"收到撤回命令: {event.message_str}")
            async for result in self._handle_recall_user_messages(event):
                yield result
            event.stop_event()
        elif cmd == "设置撤回时间" or cmd.startswith("设置撤回时间 "):
            async for result in self._handle_set_recall_time(event):
                yield result
            event.stop_event()
        elif cmd == "设置撤回数量" or cmd.startswith("设置撤回数量 "):
            async for result in self._handle_set_recall_max(event):
                yield result
            event.stop_event()
        elif cmd == "设置撤回范围" or cmd.startswith("设置撤回范围 "):
            async for result in self._handle_set_recall_scope(event):
                yield result
            event.stop_event()
        elif cmd == "开启撤回通知":
            async for result in self._handle_enable_recall_notification(event):
                yield result
            event.stop_event()
        elif cmd == "关闭撤回通知":
            async for result in self._handle_disable_recall_notification(event):
                yield result
            event.stop_event()
        elif cmd == "设置撤回通知" or cmd.startswith("设置撤回通知 "):
            async for result in self._handle_set_recall_notification(event):
                yield result
            event.stop_event()
        elif cmd == "撤回帮助":
            from .qqadmin.recall import get_recall_help_text
            yield self._yield_plain(event,get_recall_help_text())
            event.stop_event()
        elif cmd.startswith("查看自身撤回"):
            async for result in self._handle_view_self_recall(event):
                yield result
            event.stop_event()
        elif cmd.startswith("设置自身撤回时间"):
            async for result in self._handle_set_self_recall_time(event):
                yield result
            event.stop_event()
        elif cmd == "开启敏感词撤回":
            async for result in self._handle_enable_sensitive_recall(event):
                yield result
            event.stop_event()
        elif cmd == "关闭敏感词撤回":
            async for result in self._handle_disable_sensitive_recall(event):
                yield result
            event.stop_event()
        elif cmd in ("开启网址撤回", "关闭网址撤回", "开启名片撤回", "关闭名片撤回", "开启图片撤回", "关闭图片撤回"):
            yield self._yield_plain(event, "内容检测已整合到撤回系统中，/开启撤回 即自动检测敏感词/网址/名片/图片")
            event.stop_event()
        elif cmd == "查看内容检测状态":
            async for result in self._handle_view_content_recall_status(event):
                yield result
            event.stop_event()
        elif cmd == "查看敏感词":
            async for result in self._handle_view_sensitive_words(event):
                yield result
            event.stop_event()
        elif cmd.startswith("添加敏感词"):
            async for result in self._handle_add_sensitive_word(event):
                yield result
            event.stop_event()
        elif cmd.startswith("删除敏感词"):
            async for result in self._handle_remove_sensitive_word(event):
                yield result
            event.stop_event()

    # ==================== 关键词过滤系统命令 ====================
    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE)
    async def handle_keyword_filter_commands(self, event: AstrMessageEvent) -> None:
        message_str = event.message_str or ""

        if not message_str.strip():
            return

        cmd = message_str.lstrip('/').strip()

        # 检查是否是关键词过滤相关命令
        keyword_filter_commands = ["开启关键词过滤", "关闭关键词过滤",
                                   "添加过滤词", "删除过滤词", "查看过滤词列表",
                                   "添加过滤正则", "删除过滤正则", "查看过滤正则",
                                   "设置过滤动作", "设置过滤警告语"]

        is_kf_command = cmd in keyword_filter_commands or \
                        cmd.startswith("添加过滤词") or \
                        cmd.startswith("删除过滤词") or \
                        cmd.startswith("添加过滤正则") or \
                        cmd.startswith("删除过滤正则") or \
                        cmd.startswith("设置过滤动作") or \
                        cmd.startswith("设置过滤警告语")

        if not is_kf_command:
            return

        logger.debug(f"关键词过滤命令处理: message_str='{message_str}', cmd='{cmd}'")

        # 对于开启/关闭命令，只检查群管总开关和权限，不检查功能配置
        if cmd in ["开启关键词过滤", "关闭关键词过滤"]:
            if not getattr(self, 'qqadmin_enable_group_manage', True):
                return
        else:
            # These are configuration commands.  Keep them available while
            # filtering is disabled so administrators can edit rules before
            # enabling the runtime filter.
            if not getattr(self, 'qqadmin_enable_group_manage', True):
                return

        if cmd == "开启关键词过滤":
            async for result in self._handle_enable_keyword_filter(event):
                yield result
            event.stop_event()
        elif cmd == "关闭关键词过滤":
            async for result in self._handle_disable_keyword_filter(event):
                yield result
            event.stop_event()
        elif cmd.startswith("添加过滤词"):
            async for result in self._handle_add_filter_keyword(event):
                yield result
            event.stop_event()
        elif cmd.startswith("删除过滤词"):
            async for result in self._handle_remove_filter_keyword(event):
                yield result
            event.stop_event()
        elif cmd == "查看过滤词列表":
            async for result in self._handle_list_filter_keywords(event):
                yield result
            event.stop_event()
        elif cmd.startswith("添加过滤正则"):
            async for result in self._handle_add_filter_regex(event):
                yield result
            event.stop_event()
        elif cmd.startswith("删除过滤正则"):
            async for result in self._handle_remove_filter_regex(event):
                yield result
            event.stop_event()
        elif cmd == "查看过滤正则":
            async for result in self._handle_list_filter_regex(event):
                yield result
            event.stop_event()
        elif cmd.startswith("设置过滤动作"):
            async for result in self._handle_set_filter_action(event):
                yield result
            event.stop_event()
        elif cmd.startswith("设置过滤警告语"):
            async for result in self._handle_set_filter_warning(event):
                yield result
            event.stop_event()

    async def _escalate_severe_violation(
        self, event: AstrMessageEvent, group_id: str, user_id: str, reason: str
    ) -> bool:
        """Optionally remove the sender after a high-confidence violation."""
        from .qqadmin.group_config import get_group_feature_detail

        detail = get_group_feature_detail(group_id, "recall", self.config)
        if not bool(
            detail.get(
                "kick_on_severe_violation",
                getattr(self, "qqadmin_kick_on_severe_violation", True),
            )
        ):
            return False
        # 关键词过滤动作是本群明确的处置策略。警告、撤回或禁言不应被
        # 内容撤回模块的“严重违规”二次升级为踢出；只有管理员明确选
        # 择踢出/拉黑时才允许执行该升级。
        keyword_detail = get_group_feature_detail(group_id, "keyword_filter", self.config)
        if isinstance(keyword_detail, dict):
            keyword_enabled = keyword_detail.get("enabled", None)
            if keyword_enabled is None:
                keyword_enabled = bool(getattr(self, "qqadmin_enable_keyword_filter", False))
            keyword_action = str(
                keyword_detail.get("filter_action", "warn") or "warn"
            ).strip().lower()
            if keyword_enabled is True and keyword_action in {
                "warn", "delete", "delete_warn", "mute"
            }:
                logger.info(
                    "关键词过滤已设置为非踢出动作，跳过严重违规升级 group=%s action=%s reason=%s",
                    group_id,
                    keyword_action,
                    reason,
                )
                return False
        severe = any(
            marker in str(reason or "")
            for marker in ("黄色", "暴力", "违规卡片", "违规分享", "诈骗/赌博")
        )
        if not severe or not user_id or not str(user_id).isdigit():
            return False
        try:
            if await self._is_group_admin_or_owner_async(event):
                logger.info("严重违规升级跳过管理员/群主: group=%s user=%s", group_id, user_id)
                return False
        except Exception:
            pass
        try:
            platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
            if not platform:
                return False
            result = await platform.get_client().call_action(
                action="set_group_kick",
                group_id=int(group_id),
                user_id=int(user_id),
                reject_add_request=True,
            )
            if not self._api_result_succeeded(result):
                raise RuntimeError("QQ 平台拒绝了严重违规踢出请求")
            add_operation_log(
                group_id, user_id, "", "严重违规自动踢出", "", "kick", reason
            )
            logger.warning("严重违规已踢出发言人: group=%s user=%s reason=%s", group_id, user_id, reason)
            return True
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.warning("严重违规升级失败: group=%s user=%s error=%s", group_id, user_id, exc)
            return False

    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE)
    async def handle_recall_auto(self, event: AstrMessageEvent) -> None:
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            return

        if not self._can_send_group_message(group_id):
            return

        # 硬门检查：未授权群不处理任何消息
        if not self._check_group_authorized(event):
            return

        # 跳过命令消息，避免在命令处理时做耗时操作
        if self._is_command_message(event):
            return

        # 跳过机器人自己的消息
        user_id = self._get_sender_id_from_event(event)
        if await self._is_event_from_bot(event, user_id):
            logger.debug("[撤回系统] 跳过机器人自身消息 | 群:%s 用户:%s", group_id, user_id)
            return

        if not self._check_feature_cached(event, self.qqadmin_enable_recall, "recall_enabled"):
            return

        from .qqadmin.recall import get_recall_mode, get_recall_keywords, get_recall_regex_list
        recall_enabled = get_group_feature_setting(group_id, "recall_enabled", None, self.config)
        if recall_enabled is None:
            recall_enabled = self.qqadmin_enable_recall
        if not recall_enabled:
            return

        message = (event.message_str or "").strip()
        if not message:
            try:
                from astrbot.core.message.components import Plain

                message = "".join(
                    str(getattr(component, "text", "") or "")
                    for component in event.get_messages()
                    if isinstance(component, Plain)
                ).strip()
            except Exception:
                message = ""
        # Commands never enter automated moderation. A card/forward message
        # can have no Plain component, so do not reject it merely because the
        # visible text is empty.
        if self._is_command_message(event):
            return

        mode = get_recall_mode(group_id)
        user_id = self._get_sender_id_from_event(event)
        logger.debug(f"[撤回系统] 开始检查 | 群:{group_id} 用户:{user_id} | 消息:'{message[:80]}' | 模式:{mode}")

        should_recall = False
        recall_reason = ""

        # 获取raw_message用于CQ码检测
        raw_event = getattr(event.message_obj, "raw_message", None)
        if raw_event is None:
            raw_event = getattr(event, "raw_message", None)
        raw_message = ""
        if isinstance(raw_event, dict):
            raw_message = str(raw_event.get('raw_message', "") or "")
            raw_segments = raw_event.get("message", raw_event.get("messages", []))
            if raw_segments:
                raw_message += " " + self._moderation_segments_to_text(raw_segments)
        elif isinstance(raw_event, str):
            raw_message = raw_event
        try:
            component_text = self._moderation_segments_to_text(event.get_messages())
            if component_text:
                raw_message += " " + component_text
        except Exception:
            pass
        raw_message = await self._expand_forward_payload(event, raw_message)
        image_recall_enabled = False
        try:
            from .qqadmin.recall import is_image_recall_enabled

            image_recall_enabled = bool(is_image_recall_enabled(group_id))
        except Exception:
            image_recall_enabled = False
        has_image = self._moderation_contains_image(raw_event)
        try:
            has_image = has_image or self._moderation_contains_image(event.get_messages())
        except Exception:
            pass
        # Image URLs, filenames and CQ metadata are implementation details,
        # not visible text. Unless image moderation was explicitly enabled,
        # do not let them trigger a keyword/URL rule. Mixed image+text keeps
        # the visible message text for moderation.
        moderation_message = message
        moderation_raw_message = raw_message
        if has_image and not image_recall_enabled:
            import re

            moderation_message = re.sub(
                r"\[CQ:image[^\]]*\]", " ", moderation_message, flags=re.I
            ).strip()
            if moderation_message.casefold() in {"图片", "[图片]", "image", "[image]"}:
                moderation_message = ""
            if not moderation_message:
                moderation_raw_message = ""
            else:
                moderation_raw_message = re.sub(
                    r"\[CQ:image[^\]]*\]", " ", moderation_raw_message, flags=re.I
                )
        if not moderation_message.strip() and not moderation_raw_message.strip():
            return

        detection_text = " ".join(
            part for part in (moderation_message, moderation_raw_message) if str(part or "").strip()
        )

        if mode == "keyword":
            keywords = get_recall_keywords(group_id)
            logger.debug(f"[撤回系统] 关键词模式 | 列表: {keywords}")
            # Forwarded cards often put the actual text only in the expanded
            # payload.  Match both the visible message and that payload.
            detection_text = " ".join(
                part for part in (moderation_message, moderation_raw_message) if str(part or "").strip()
            )
            if keywords:
                for keyword in keywords:
                    if keyword in detection_text:
                        should_recall = True
                        recall_reason = f"包含关键词'{keyword}'"
                        logger.debug(f"[撤回系统] ✅ 命中 '{keyword}' | 群:{group_id} 用户:{user_id}")
                        break
        elif mode == "regex":
            import re
            patterns = get_recall_regex_list(group_id)
            if patterns:
                for pattern in patterns:
                    try:
                        if re.search(pattern, detection_text):
                            should_recall = True
                            recall_reason = f"匹配正则'{pattern}'"
                            logger.debug(f"[撤回系统] ✅ 正则命中 '{pattern}' | 群:{group_id} 用户:{user_id}")
                            break
                    except re.error:
                        continue
        elif mode == "all":
            # “全部” covers visible messages, but ordinary image-only posts
            # still require the dedicated image switch.
            if not has_image or image_recall_enabled or moderation_message.strip():
                should_recall = True
                recall_reason = "全部模式"

        # 内容类型检测是可选的高开销/高敏感规则；只有分群明确开启时
        # 才执行，避免默认配置把普通关键词/正则模式误当成违法检测。
        if not should_recall:
            from .qqadmin.group_config import get_group_feature_detail
            recall_detail = get_group_feature_detail(group_id, "recall", self.config)
            sensitive_enabled = recall_detail.get("enable_sensitive_detection")
            if sensitive_enabled is None:
                sensitive_enabled = recall_detail.get("recall_sensitive_enabled", self.qqadmin_enable_sensitive_detection)
            # Forwarded cards often have no plain text in the event itself;
            # their expanded node payload is the only useful signal. Always
            # run the built-in content classifier for that payload so a
            # forwarded explicit message is not treated as an empty message
            # merely because the group switch was left at its old default.
            if raw_message.strip() and raw_message.strip() != message.strip():
                sensitive_enabled = True
            if bool(sensitive_enabled):
                from .qqadmin.recall import (
                    detect_url,
                    inspect_urls_for_violations,
                    should_recall_by_content_type,
                )
                content_recall, content_reason = should_recall_by_content_type(group_id, moderation_message, moderation_raw_message, self.config)
                if content_recall:
                    should_recall = True
                    recall_reason = content_reason
                    logger.debug(f"[撤回系统] ✅ 内容检测触发: {content_reason} | 群:{group_id}")
                else:
                    # URL strings are not enough: a harmless-looking domain can
                    # serve a prohibited page after a redirect or JavaScript-free
                    # server render.  Fetch only public text pages with strict
                    # bounds; a failed fetch never blocks ordinary moderation.
                    urls = detect_url(f"{moderation_message}\n{moderation_raw_message}")
                    if urls:
                        try:
                            website_hits = await asyncio.wait_for(
                                asyncio.to_thread(
                                    inspect_urls_for_violations,
                                    urls[:2],
                                    group_id,
                                    self.config,
                                ),
                                timeout=4.5,
                            )
                        except Exception:
                            website_hits = []
                        if website_hits:
                            first_hit = website_hits[0]
                            categories = first_hit.get("categories", []) if isinstance(first_hit, dict) else []
                            labels = "、".join(
                                str(item.get("label", item))
                                for item in categories
                                if isinstance(item, dict) or item
                            ) or "网页内容违规"
                            should_recall = True
                            recall_reason = f"{labels}（网页实际内容）"
                            logger.warning(
                                "[撤回系统] 网页实际内容触发: 群=%s 用户=%s 分类=%s url=%s",
                                group_id,
                                user_id,
                                labels,
                                str(first_hit.get("url", ""))[:160],
                            )

        if not should_recall:
            logger.debug(f"[撤回系统] 未命中 | 群:{group_id} 用户:{user_id}")
            return

        # 强检查：如果是机器人自己的消息，不处理（由 after_message_sent 处理）
        if await self._is_event_from_bot(event, user_id):
            return

        # 检查是否是主人
        sender_id_str = str(user_id)
        if self._is_owner(event):
            return

        # Respect the configured manual/automatic scope.  Adapters that do
        # not put a role on the event are resolved through the short-lived
        # member-role cache instead of being treated as ordinary members.
        from .qqadmin.recall import get_recall_member_scope
        if get_recall_member_scope(group_id) != "all":
            if getattr(event, "role", "") in ["admin", "owner"]:
                return
            if await self._is_group_admin_or_owner_async(event):
                return

        # 检查白名单
        if user_id and is_user_whitelisted(group_id, user_id):
            logger.debug(f"handle_recall_auto: 用户{user_id}在白名单，跳过")
            return

        message_id = self._get_event_message_id(event)
        if message_id is None:
            logger.debug(f"handle_recall_auto: message_id无效={message_id}")
            return

        try:
            from .qqadmin.recall import _safe_int, log_recall
            from .qqadmin.message_cache import mark_message_recalled
            try:
                delete_result = await event.bot.delete_msg(
                    message_id=_safe_int(message_id, message_id)
                )
            except asyncio.CancelledError:
                raise
            except Exception as delete_error:
                # A failed recall must not abort the message pipeline.  QQ
                # adapters may raise ActionFailed for expired, unsupported,
                # or undecodable message IDs; the next message can still be
                # checked normally.
                logger.warning(
                    "自动撤回失败，已停止该消息的后续自动处罚（不禁言、不踢出） "
                    "group=%s message_id=%s error_type=%s retcode=%s",
                    group_id,
                    message_id,
                    type(delete_error).__name__,
                    getattr(delete_error, "retcode", None),
                )
                return
            if not self._api_result_succeeded(delete_result):
                logger.warning("自动撤回被平台拒绝: group=%s message_id=%s", group_id, message_id)
                return
            logger.debug(f"自动撤回: 群组 {group_id} 撤回消息 {message_id}, 原因: {recall_reason}")
            
            # Keep a readable representation for media-only messages.  The
            # plain event text is empty for images, which previously made a
            # recalled pair of pictures look like an unexplained deletion.
            recall_content = str(message or "").strip()
            if not recall_content or "[图片]" not in recall_content:
                try:
                    from .qqadmin.message_cache import build_message_record, format_cached_message

                    group_config = get_group_config(group_id, self.config)
                    cache_settings = self._get_message_cache_settings(group_config)
                    preview_record = build_message_record(group_id, user_id, event, cache_settings)
                    formatted = format_cached_message(preview_record, content_limit=280)
                    if formatted and formatted != "[空消息]":
                        recall_content = formatted
                except Exception:
                    logger.debug("构建撤回消息摘要失败 group=%s message_id=%s", group_id, message_id, exc_info=True)
            log_recall(
                group_id,
                user_id,
                str(message_id),
                recall_content or "[空消息]",
                reason=recall_reason,
            )
            await asyncio.to_thread(
                mark_message_recalled,
                group_id,
                message_id,
                recall_reason,
                "system",
            )
            await self._sync_recalled_message_cache(group_id, message_id, recall_reason)
            await self._escalate_severe_violation(event, group_id, user_id, recall_reason)
            
            # 检查是否需要发送通知
            from .qqadmin.group_config import get_group_feature_detail
            recall_config = get_group_feature_detail(group_id, "recall", self.config)
            notification = recall_config.get("notification", False)
            notification_message = recall_config.get("notification_message", "您的消息包含违规内容，已被撤回")
            
            if notification:
                yield self._yield_plain(event, str(notification_message).strip())
            
            event.stop_event()
                
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.error("自动撤回处理失败: group=%s error_type=%s", group_id, type(e).__name__)

    # ==================== 入群欢迎命令 ====================
    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE)
    async def handle_welcome_commands(self, event: AstrMessageEvent) -> None:
        message_str = event.message_str or ""
        cmd = message_str.lstrip('/').strip()
        
        # 检查是否是入群欢迎相关命令
        welcome_commands = ["开启欢迎", "关闭欢迎", "查看欢迎设置",
                            "开启退群通知", "关闭退群通知"]
        is_welcome_command = cmd in welcome_commands or \
                            cmd.startswith("设置欢迎语") or \
                            cmd.startswith("设置退群语") or \
                            cmd.startswith("设置艾特新人") or \
                            cmd.startswith("设置欢迎延迟")
        
        if not is_welcome_command:
            return
        
        # 配置命令必须能在模块关闭时执行，否则管理员无法通过命令开启欢迎。
        # 授权和开机仍由统一消息入口处理，群管总开关在这里显式保留。
        if not getattr(self, "qqadmin_enable_group_manage", True):
            return
        if not self._is_authorized(event) or not self._is_group_powered_on(event):
            return
        
        if cmd == "开启欢迎":
            async for result in self._handle_enable_welcome(event):
                yield result
            event.stop_event()
        elif cmd == "关闭欢迎":
            async for result in self._handle_disable_welcome(event):
                yield result
            event.stop_event()
        elif cmd == "开启退群通知":
            async for result in self._handle_enable_farewell(event):
                yield result
            event.stop_event()
        elif cmd == "关闭退群通知":
            async for result in self._handle_disable_farewell(event):
                yield result
            event.stop_event()
        elif cmd.startswith("设置欢迎语"):
            async for result in self._handle_set_welcome_message(event):
                yield result
            event.stop_event()
        elif cmd.startswith("设置退群语"):
            async for result in self._handle_set_farewell_message(event):
                yield result
            event.stop_event()
        elif cmd == "查看欢迎设置":
            async for result in self._handle_view_welcome_settings(event):
                yield result
            event.stop_event()
        elif cmd.startswith("设置艾特新人"):
            async for result in self._handle_set_at_new_member(event):
                yield result
            event.stop_event()
        elif cmd.startswith("设置欢迎延迟"):
            async for result in self._handle_set_welcome_delay(event):
                yield result
            event.stop_event()
