    async def _show_settings(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(event)
        if not ok:
            yield err
            return

        result_parts = []
        result_parts.append("群设置")
        result_parts.append("━━━━━━━━━━━━━━")

        # ========== 授权到期提醒（全局配置） ==========
        if self.enable_auth and self.enable_auth_expire_reminder:
            at_owner_str = "艾特群主"if self.auth_expire_reminder_at_owner else "不艾特"
            interval_min = self.auth_expire_reminder_check_interval // 60
            result_parts.append(f"到期提醒:  | 提前 {self.auth_expire_reminder_hours}h | {at_owner_str} | 每 {interval_min}分钟检查")
        else:
            result_parts.append(f"到期提醒: ")
        # 自动删除过期授权
        if self.enable_auth and self.auto_delete_expired_auth:
            days_str = f"{self.auto_delete_expired_auth_days}天后"if self.auto_delete_expired_auth_days > 0 else "立即"
            result_parts.append(f"自动删除过期:  | {days_str}")
        else:
            result_parts.append(f"自动删除过期: ")

        # ========== 全局配置更新检测 ==========
        try:
            from astrbot.core.utils.astrbot_path import get_astrbot_data_path
            config_path = os.path.join(get_astrbot_data_path(), "config", "astrbot_plugin_joker_config.json")
            global_updated_at = int(os.path.getmtime(config_path)) if os.path.exists(config_path) else 0
        except (OSError, TypeError, ValueError):
            global_updated_at = 0
        
        from .qqadmin.group_config import load_group_config
        group_config = load_group_config(group_id)
        cloned_at = group_config.get("updated_at", 0)
        
        if global_updated_at > cloned_at and global_updated_at > 0:
            result_parts.append("全局配置已更新，发送 /克隆全局 同步")
            result_parts.append("")
        
        # ========== 基础设置 ==========
        settings = load_group_settings()
        group_settings = settings.get(group_id, {})
        allow_slash = group_settings.get("allow_slash_prefix", self.allow_slash_prefix)
        
        from .qqadmin.group_config import get_group_data
        features = get_group_data(group_id, "features", {})
        power_status = features.get("power_status", "")
        
        result_parts.append(f"斜杠命令: {'✅️'if allow_slash else '❌️'}")
        result_parts.append(f"开机状态: {'开机'if power_status == 'on'else '关机'if power_status == 'off'else '未设置'}")
        
        # ========== 入群审核设置 ==========
        result_parts.append("")
        from .qqadmin.audit import get_max_verify_attempts, get_verification_timeout, get_audit_approval_mode, get_pending_verifications, get_whitelist_users
        max_attempts = get_max_verify_attempts(group_id)
        timeout = get_verification_timeout(group_id)
        approval_mode = get_audit_approval_mode(group_id)
        all_pending = get_pending_verifications()
        pending = [p for p in all_pending if p.get("group_id") == group_id]
        whitelist = get_whitelist_users(group_id)
        
        # 提前加载群配置，供后续多个模块使用（直接读取最新配置）
        from .qqadmin.group_config import get_group_config, is_feature_enabled
        group_cfg = get_group_config(group_id)
        
        # 从分群配置直接读取各功能状态
        audit_enabled = is_feature_enabled(group_id, "audit", self.config) if group_id else self.qqadmin_enable_audit
        reply_enabled = is_feature_enabled(group_id, "reply", self.config) if group_id else self.qqadmin_enable_reply
        mute_enabled = is_feature_enabled(group_id, "mute", self.config) if group_id else self.qqadmin_enable_mute
        kick_enabled = is_feature_enabled(group_id, "kick", self.config) if group_id else self.qqadmin_enable_kick
        blacklist_enabled = is_feature_enabled(group_id, "blacklist", self.config) if group_id else self.qqadmin_enable_blacklist
        stats_enabled = is_feature_enabled(group_id, "stats", self.config) if group_id else self.qqadmin_enable_stats
        welcome_enabled = is_feature_enabled(group_id, "welcome", self.config) if group_id else self.qqadmin_enable_welcome
        player_reply_enabled = is_feature_enabled(group_id, "player_reply", self.config) if group_id else self.qqadmin_enable_player_reply
        
        result_parts.append(f"入群审核: {'✅️'if audit_enabled else '❌️'}")
        result_parts.append(f"   模式: {approval_mode} | 尝试: {max_attempts}次 | 超时: {timeout}秒")
        result_parts.append(f"   待验证: {len(pending)}人 | 白名单: {len(whitelist)}人")
        
        # ========== 自定义回复设置 ==========
