        result_parts.append(f"   默认: {mute_settings.get('level', 5)}级/{mute_settings.get('duration', 300)}秒 | 禁言中: {len(muted_users)}人")
        if muted_users:
            muted_ids = [str(u.get('user_id', '')) for u in muted_users[:3]]
            result_parts.append(f"   {', '.join(muted_ids)}{'...'if len(muted_users) > 3 else ''}")
        
        # ========== 踢出系统设置 ==========
