        valid_global = [u for u in global_blacklist if str(u.get('user_id', '')).isdigit()]
        invalid_count = len(blacklist) - len(valid_blacklist)
        
        result_parts.append(f"黑名单: {'✅️'if blacklist_enabled else '❌️'}")
