    def _get_stats_help_context(self, event: AstrMessageEvent) -> tuple[str, str, dict, dict, dict]:
        group_id = self._get_group_id_from_event(event)
        user_id = str(getattr(getattr(event.message_obj, "sender", None), "user_id", ""))
        if not group_id:
            return "", user_id, {}, {}, {}
        status = get_signin_status(group_id, user_id)
        monthly = get_monthly_signin_summary(group_id, user_id)
        info = get_user_info(group_id, user_id)
        binding = get_steam_binding(group_id, user_id=user_id) or {}
        if binding.get("steam_id"):
            database_status = self._get_steam_database_status(
                group_id,
                str(binding["steam_id"]),
                self._get_signin_policy(group_id),
            )
            if database_status.get("success"):
                balance = database_status.get("balance", status.get("points", 0))
                status = dict(status)
                status.update(
                    {
                        "points": balance,
                        "database_balance": balance,
                    }
                )
                info = dict(info)
                info.update(
                    {
                        "points": balance,
                        "database_balance": balance,
                    }
                )
                if database_status.get("sign_log_available"):
                    status.update(
                        {
                            "signed_today": bool(database_status.get("signed_today")),
                            "total_days": database_status.get(
                                "total_signins", status.get("total_days", 0)
                            ),
                            "consecutive_days": database_status.get(
                                "consecutive_signins", status.get("consecutive_days", 0)
                            ),
                        }
                    )
                    monthly = dict(monthly)
                    monthly["signin_days"] = database_status.get(
                        "month_signins", monthly.get("signin_days", 0)
                    )
                    info.update(
                        {
                            "total_signins": database_status.get(
                                "total_signins", info.get("total_signins", 0)
                            ),
                            "total_signin_days": database_status.get(
                                "total_signins", info.get("total_signin_days", 0)
                            ),
                            "consecutive_days": database_status.get(
                                "consecutive_signins", info.get("consecutive_days", 0)
                            ),
                        }
                    )
        return group_id, user_id, status, monthly, info

    async def _show_signin_help(self, event: AstrMessageEvent) -> None:
        group_id, _, status, _, _ = self._get_stats_help_context(event)
        if not group_id:
            yield self._yield_plain(event, "签到只能在群聊中使用")
            return
        today = "已签到" if status.get("signed_today") else "未签到"
        commands = self._get_signin_command_settings(group_id)
        profile_lines = self._get_signin_profile_help_lines(group_id, limit=6)
        lines = [
            f"签到｜今日{today}｜连签 {status.get('consecutive_days', 0)}天｜{status.get('points', 0)}积分",
            "玩家指令：",
            f"  /{commands['signin']}：执行签到",
            f"  /{commands['status']}、/{commands['calendar']}、/{commands['ranking']}：查看数据",
            f"  /{commands['bind']} 17位SteamID：绑定账号",
            f"  /{commands['unbind']} QQ号或SteamID：管理员解绑",
        ]
        if profile_lines:
            lines.append("多签到方案：")
            lines.extend(f"  {line}" for line in profile_lines)
        yield self._yield_plain(event, "\n".join(lines))

