    async def _handle_power_on(self, event: AstrMessageEvent) -> None:
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            yield self._yield_plain(event,"此命令只能在群组中使用。")
            return
        
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event,"只有管理员或群主才能执行此操作。")
            return
        
        if not self._is_authorized(event):
            yield self._yield_plain(event,"当前群组未授权，请先激活卡密。")
            return
        
        from .qqadmin.group_config import update_group_data
        
        def _power_on(features):
            if features is None:
                features = {}
            features["power_status"] = "on"
            return features
        
        update_group_data(group_id, "features", _power_on)
        self._request_portal_sync()
        
        yield self._yield_plain(
            event,
            self._format_group_notice(
                getattr(self, "qqadmin_power_on_success", ""),
                self._POWER_ON_SUCCESS_TEXT,
                group_id,
            ),
        )

    async def _handle_power_off(self, event: AstrMessageEvent) -> None:
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            yield self._yield_plain(event,"此命令只能在群组中使用。")
            return
        
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event,"只有管理员或群主才能执行此操作。")
            return

        if not self._is_authorized(event):
            yield self._yield_plain(event,"当前群组未授权，请先激活卡密。")
            return

        if not self._is_group_powered_on(event):
            yield self._yield_power_off_status(
                event,
                self._format_group_notice(
                    getattr(self, "qqadmin_power_off_already", ""),
                    self._POWER_OFF_ALREADY_TEXT,
                    group_id,
                ),
            )
            return
        
        from .qqadmin.group_config import update_group_data
        
        def _power_off(features):
            if features is None:
                features = {}
            features["power_status"] = "off"
            return features
        
        update_group_data(group_id, "features", _power_off)
        self._request_portal_sync()

        yield self._yield_power_off_status(
            event,
            self._format_group_notice(
                getattr(self, "qqadmin_power_off_success", ""),
                self._POWER_OFF_SUCCESS_TEXT,
                group_id,
            ),
        )

