    async def _handle_add_sensitive_word(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="recall"
        )
        if not ok:
            yield err
            return
        message = (event.message_str or "").strip()
        message = message.lstrip('/')
        # The command payload starts after the first whitespace.  ``str.find``
        # rejects an empty separator, which previously made this command fail
        # before it could add a sensitive word.
        space_pos = next((index for index, char in enumerate(message) if char.isspace()), -1)
        if space_pos == -1:
            yield self._yield_plain(event,"用法: /添加敏感词 <词汇>")
            return
        word = message[space_pos+1:].strip()
        if not word:
            yield self._yield_plain(event,"用法: /添加敏感词 <词汇>")
            return
        from .qqadmin.recall import add_sensitive_word
        add_sensitive_word(group_id, word)
        yield self._yield_plain(event,f"已添加敏感词: {word}")

    async def _handle_remove_sensitive_word(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="recall"
        )
        if not ok:
            yield err
            return
        message = (event.message_str or "").strip()
        message = message.lstrip('/')
        space_pos = next((index for index, char in enumerate(message) if char.isspace()), -1)
        if space_pos == -1:
            yield self._yield_plain(event,"用法: /删除敏感词 <词汇>")
            return
        word = message[space_pos+1:].strip()
        if not word:
            yield self._yield_plain(event,"用法: /删除敏感词 <词汇>")
            return
        from .qqadmin.recall import remove_sensitive_word
        remove_sensitive_word(group_id, word)
        yield self._yield_plain(event,f"已删除敏感词: {word}")

    async def _handle_add_recall_keyword(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="recall"
        )
        if not ok:
            yield err
            return

        message = (event.message_str or "").strip()
        message = message.lstrip('/')
        # 找到第一个空格的位置，然后取后面的内容作为关键词
        space_pos = message.find(' ')
        if space_pos == -1:
            yield self._yield_plain(event,"用法: /添加撤回关键词 <关键词>")
            return
        keyword = message[space_pos+1:].strip()
        if not keyword:
            yield self._yield_plain(event,"用法: /添加撤回关键词 <关键词>")
            return

        add_recall_keyword(group_id, keyword)
        yield self._yield_plain(event,f"已添加撤回关键词: {keyword}")

    async def _handle_remove_recall_keyword(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="recall"
        )
        if not ok:
            yield err
            return

        message = (event.message_str or "").strip()
        message = message.lstrip('/')
        # 找到第一个空格的位置，然后取后面的内容作为关键词
        space_pos = message.find(' ')
        if space_pos == -1:
            yield self._yield_plain(event,"用法: /删除撤回关键词 <关键词>")
            return
        keyword = message[space_pos+1:].strip()
        if not keyword:
            yield self._yield_plain(event,"用法: /删除撤回关键词 <关键词>")
            return

        remove_recall_keyword(group_id, keyword)
        yield self._yield_plain(event,f"已删除撤回关键词: {keyword}")

    async def _handle_set_recall_mode(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="recall"
        )
        if not ok:
            yield err
            return
        
        message = (event.message_str or "").strip()
        parts = message.split()
        if len(parts) < 2:
            yield self._yield_plain(event,"用法: /设置撤回模式 <模式>")
            return
        
        mode = parts[1]
        if mode not in ["keyword", "regex", "all"]:
            yield self._yield_plain(event,"模式必须是 keyword/regex/all")
            return
        
        set_recall_mode(group_id, mode)
        yield self._yield_plain(event,f"已设置撤回模式为: {mode}")

