    async def _handle_add_recall_regex(self, event: AstrMessageEvent) -> None:
        """添加自动撤回正则规则。"""
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="recall"
        )
        if not ok:
            yield err
            return
        message = (event.message_str or "").strip().lstrip("/")
        space_pos = next((i for i, char in enumerate(message) if char.isspace()), -1)
        if space_pos < 0:
            yield self._yield_plain(event, "用法: /添加撤回正则 <Python正则>")
            return
        pattern = message[space_pos + 1:].strip()
        if not pattern:
            yield self._yield_plain(event, "用法: /添加撤回正则 <Python正则>")
            return
        import re
        try:
            re.compile(pattern)
        except re.error as exc:
            yield self._yield_plain(event, f"正则表达式无效: {exc}")
            return
        add_recall_regex(group_id, pattern)
        yield self._yield_plain(event, f"已添加撤回正则: {pattern}")

    async def _handle_remove_recall_regex(self, event: AstrMessageEvent) -> None:
        """按序号或完整规则删除自动撤回正则。"""
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="recall"
        )
        if not ok:
            yield err
            return
        message = (event.message_str or "").strip().lstrip("/")
        space_pos = next((i for i, char in enumerate(message) if char.isspace()), -1)
        if space_pos < 0:
            yield self._yield_plain(event, "用法: /删除撤回正则 <序号或完整规则>")
            return
        param = message[space_pos + 1:].strip()
        patterns = get_recall_regex_list(group_id)
        if not param:
            yield self._yield_plain(event, "用法: /删除撤回正则 <序号或完整规则>")
            return
        pattern = None
        if param.isdigit():
            index = int(param) - 1
            if 0 <= index < len(patterns):
                pattern = patterns[index]
            else:
                yield self._yield_plain(event, f"序号超出范围，共 {len(patterns)} 条规则")
                return
        elif param in patterns:
            pattern = param
        if pattern is None:
            yield self._yield_plain(event, f"撤回正则不存在: {param}")
            return
        remove_recall_regex(group_id, pattern)
        yield self._yield_plain(event, f"已删除撤回正则: {pattern}")

    async def _handle_list_recall_regex(self, event: AstrMessageEvent) -> None:
        """查看本群自动撤回正则规则。"""
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="recall"
        )
        if not ok:
            yield err
            return
        patterns = get_recall_regex_list(group_id)
        if not patterns:
            yield self._yield_plain(event, "当前没有撤回正则")
            return
        lines = ["撤回正则列表:"]
        lines.extend(f"{index}. {pattern}" for index, pattern in enumerate(patterns, 1))
        yield self._yield_plain(event, "\n".join(lines))

    async def _handle_view_cached_messages(
        self,
        event: AstrMessageEvent,
        *,
        recalled_only: bool,
        required_sub_admin_permission: str | None = None,
    ) -> None:
        record_name = "已撤回消息记录" if recalled_only else "群消息记录"
        if not await self._check_feature_permission_async(
            event,
            "message_cache",
            "use",
            required_sub_admin_permission=required_sub_admin_permission,
        ):
            yield self._yield_plain(event, f"权限不足，无法查看{record_name}。")
            return

        group_id = str(getattr(event.message_obj, "group_id", "") or "")
        if not group_id or group_id == "None":
            yield self._yield_plain(event, "此命令只能在群组中使用。")
            return

        message = (event.message_str or "").lstrip("/").strip()
        arguments = message.split()[1:]
        target_user_id = self._get_at_user_id(event)
        if not target_user_id:
            import re
            at_match = re.search(r"\[CQ:at,qq=(\d+)", message)
            if at_match:
                target_user_id = at_match.group(1)

        limit = 20
        numeric_arguments = [item for item in arguments if item.isdigit()]
        if not target_user_id and numeric_arguments:
            first_number = numeric_arguments.pop(0)
            # A lone small number is more naturally a count.  QQ identifiers
            # remain supported as the first of two numeric arguments or when
            # they exceed the display limit.
            if numeric_arguments or int(first_number) > 50:
                target_user_id = first_number
            else:
                limit = int(first_number)
        if numeric_arguments:
            try:
                limit = int(numeric_arguments[-1])
            except ValueError:
                pass
        limit = max(1, min(limit, 50))

        from .qqadmin.message_cache import format_cached_message, get_cached_messages
        records = await asyncio.to_thread(
            get_cached_messages,
            group_id,
            target_user_id,
            limit,
            recalled_only,
        )
        if not records:
            scope = f"用户 {target_user_id}" if target_user_id else "本群"
            yield self._yield_plain(event, f"{scope} 暂无{record_name}。")
            return

        title = f"{record_name}（{len(records)} 条）"
        if target_user_id:
            title += f"\n用户: {target_user_id}"
        lines = [title]
        max_output_length = 5000
        for index, record in enumerate(records, start=1):
            sender = record.get("sender", {})
            sender = sender if isinstance(sender, dict) else {}
            nickname = str(sender.get("nickname") or "未知用户")[:80]
            sender_id = str(record.get("user_id") or "")
            timestamp = str(record.get("datetime") or record.get("timestamp") or "未知时间")
            content = format_cached_message(record, content_limit=180)
            reason = str(record.get("recall_reason") or "")[:120]
            entry = f"\n{index}. [{timestamp}] {nickname} ({sender_id})\n{content}"
            if not recalled_only and record.get("recalled") is True:
                entry += "\n状态: 已撤回"
            if reason:
                entry += f"\n撤回原因: {reason}"
            if sum(len(line) for line in lines) + len(entry) > max_output_length:
                lines.append("\n其余记录过长，已省略。")
                break
            lines.append(entry)
        yield self._yield_plain(event, "\n".join(lines))

    async def _handle_view_recalled_messages(self, event: AstrMessageEvent) -> None:
        async for result in self._handle_view_cached_messages(
            event, recalled_only=True, required_sub_admin_permission="recall"
        ):
            yield result

    @filter.command("重置游戏配置", alias={"恢复默认游戏配置", "重置游戏功能"})
    async def reset_game_configuration_command(self, event: AstrMessageEvent) -> None:
        if not self._is_slash_prefix_allowed(event):
            return
        async for result in self._handle_reset_game_configuration(event):
            yield result

    async def _handle_view_group_messages(self, event: AstrMessageEvent) -> None:
        async for result in self._handle_view_cached_messages(event, recalled_only=False):
            yield result

