    async def _handle_add_filter_keyword(self, event: AstrMessageEvent) -> None:
        """添加过滤词"""
        ok, group_id, err = await self._check_admin_group(event)
        if not ok:
            yield err
            return

        message = (event.message_str or "").strip()
        message = message.lstrip('/')
        space_pos = message.find(' ')
        if space_pos == -1:
            yield self._yield_plain(event,"用法: /添加过滤词 关键词\n示例: /添加过滤词 加微信")
            return
        keyword = message[space_pos+1:].strip()
        if not keyword:
            yield self._yield_plain(event,"用法: /添加过滤词 关键词\n示例: /添加过滤词 加微信")
            return

        # 读取现有自定义关键词，添加新的
        from .qqadmin.group_config import get_group_data, set_group_data
