    async def _handle_list_filter_keywords(self, event: AstrMessageEvent) -> None:
        """查看过滤词列表"""
        ok, group_id, err = await self._check_admin_group(event)
        if not ok:
            yield err
            return

        from .qqadmin.group_config import get_group_data, get_group_feature_detail
        # 获取默认关键词
        feature_detail = get_group_feature_detail(group_id, "keyword_filter", self.config)
        default_keywords = feature_detail.get("filter_keywords", self.qqadmin_filter_keywords)
        # 获取自定义关键词
        custom_keywords = get_group_data(group_id, "custom_filter_keywords", [])
        # 合并
        all_keywords = list(dict.fromkeys(default_keywords + custom_keywords))  # 去重保序

        if not all_keywords:
            yield self._yield_plain(event,"当前没有过滤关键词")
            return

        result = "过滤词列表:\n"
        if default_keywords:
            result += "【默认】\n"
            for kw in default_keywords:
                result += f"  - {kw}\n"
        if custom_keywords:
            result += "【自定义】\n"
            for kw in custom_keywords:
                result += f"  - {kw}\n"
        result += f"共 {len(all_keywords)} 个过滤词"
        yield self._yield_plain(event, result.strip())

    async def _handle_add_filter_regex(self, event: AstrMessageEvent) -> None:
        """添加过滤正则"""
        ok, group_id, err = await self._check_admin_group(event)
        if not ok:
            yield err
            return

        message = (event.message_str or "").strip()
        message = message.lstrip('/')
        space_pos = message.find(' ')
        if space_pos == -1:
            yield self._yield_plain(event,"用法: /添加过滤正则 正则表达式")
            return
        pattern = message[space_pos+1:].strip()
        if not pattern:
            yield self._yield_plain(event,"用法: /添加过滤正则 正则表达式")
            return

        # 验证正则是否合法
        import re
        try:
            re.compile(pattern)
        except re.error as e:
            yield self._yield_plain(event,f"正则表达式无效: {e}")
            return

        from .qqadmin.group_config import get_group_data, set_group_data
        custom_regex = get_group_data(group_id, "custom_filter_regex", [])
        if pattern not in custom_regex:
            custom_regex.append(pattern)
            set_group_data(group_id, "custom_filter_regex", custom_regex)
        yield self._yield_plain(event,f"已添加过滤正则: {pattern}")

    async def _handle_remove_filter_regex(self, event: AstrMessageEvent) -> None:
        """删除过滤正则（按序号或按内容）"""
        ok, group_id, err = await self._check_admin_group(event)
        if not ok:
            yield err
            return

        message = (event.message_str or "").strip()
        message = message.lstrip('/')
        space_pos = message.find(' ')
        if space_pos == -1:
            yield self._yield_plain(event,"用法: /删除过滤正则 <序号或内容>")
            return
        param = message[space_pos+1:].strip()
        if not param:
            yield self._yield_plain(event,"用法: /删除过滤正则 <序号或内容>")
            return

        from .qqadmin.group_config import get_group_data, set_group_data, get_group_feature_detail
        feature_detail = get_group_feature_detail(group_id, "keyword_filter", self.config)
        default_regex = feature_detail.get("filter_regex_patterns", self.qqadmin_filter_regex_patterns)
        custom_regex = get_group_data(group_id, "custom_filter_regex", [])
        all_regex = list(default_regex) + list(custom_regex)

        # 尝试按序号删除
        if param.isdigit():
            idx = int(param) - 1
            if 0 <= idx < len(all_regex):
                pattern = all_regex[idx]
                if pattern in custom_regex:
                    custom_regex.remove(pattern)
                    set_group_data(group_id, "custom_filter_regex", custom_regex)
                    yield self._yield_plain(event,f"已删除过滤正则: {pattern}")
                else:
                    yield self._yield_plain(event,f"序号 {param} 是系统默认正则，无法删除")
            else:
                yield self._yield_plain(event,f"序号超出范围，共 {len(all_regex)} 条正则")
        else:
            # 按内容删除
            if param in custom_regex:
                custom_regex.remove(param)
                set_group_data(group_id, "custom_filter_regex", custom_regex)
                yield self._yield_plain(event,f"已删除过滤正则: {param}")
            elif param in default_regex:
                yield self._yield_plain(event,"该正则是系统默认，无法删除")
            else:
                yield self._yield_plain(event,f"正则不存在: {param}")

