    async def _handle_set_filter_action(self, event: AstrMessageEvent) -> None:
        """设置过滤动作"""
        ok, group_id, err = await self._check_admin_group(event)
        if not ok:
            yield err
            return

        message = (event.message_str or "").strip()
        message = message.lstrip('/')
        space_pos = message.find(' ')
        if space_pos == -1:
            yield self._yield_plain(event,"用法: /设置过滤动作 <warn/mute/kick/delete/delete_warn/blacklist>\n  warn=警告, mute=禁言, kick=踢出, delete=仅撤回, delete_warn=撤回并警告, blacklist=拉黑")
            return
        action = message[space_pos+1:].strip().lower()
        valid_actions = ["warn", "mute", "kick", "delete", "delete_warn", "blacklist"]
        if action not in valid_actions:
            yield self._yield_plain(event,f"无效动作: {action}\n可选: {', '.join(valid_actions)}")
            return

        # 保存到分群feature设置
        from .qqadmin.group_config import set_group_feature_setting
        set_group_feature_setting(group_id, "keyword_filter", "filter_action", action, self.config)
        action_names = {"warn": "警告", "mute": "禁言", "kick": "踢出", "delete": "仅撤回", "delete_warn": "撤回并警告", "blacklist": "拉黑"}
        yield self._yield_plain(event,f"已设置过滤动作为: {action_names.get(action, action)}")

