    async def _handle_remove_reply(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="reply"
        )
        if not ok:
            yield err
            return
        
        message = (event.message_str or "").strip().lstrip("/").strip()
        parts = message.split(maxsplit=2)
        if len(parts) < 2:
            yield self._yield_plain(
                event,
                "用法: /删除 <问题>\n"
                "也可指定类型: /删除 精确|模糊|正则 <问题>",
            )
            return

        type_aliases = {
            "精确": "exact",
            "精准": "exact",
            "exact": "exact",
            "模糊": "fuzzy",
            "fuzzy": "fuzzy",
            "正则": "regex",
            "regex": "regex",
        }
        requested_type = type_aliases.get(parts[1].lower())
        selected_index: int | None = None
        if requested_type:
            if len(parts) < 3 or not parts[2].strip():
                yield self._yield_plain(event, "请在匹配类型后填写要删除的问题或正则。")
                return
            keyword = parts[2].strip()
            reply_type = requested_type
            # A numeric argument after an explicit type addresses the
            # one-based item in that category.  Keep literal numeric keys
            # working when the requested index is outside the category.
            if keyword.isdigit() and int(keyword) > 0:
                selected_index = int(keyword)
        else:
            # Short form removes the keyword wherever it is stored.  This
            # fixes legacy fuzzy rules that `/删除` previously reported as
            # deleted without touching.
            keyword = message.split(maxsplit=1)[1].strip()
            reply_type = "all"
            if keyword.isdigit() and int(keyword) > 0:
                selected_index = int(keyword)

        # Resolve numeric forms against the exact list shown to operators.
        # This is intentionally done immediately before deletion so a stale
        # literal key cannot be mistaken for a successful removal.
        if selected_index is not None:
            if requested_type:
                entries = list(iter_reply_entries(group_id))
                candidates = [entry for entry in entries if entry[0] == requested_type]
                selected = (
                    candidates[selected_index - 1]
                    if selected_index <= len(candidates)
                    else None
                )
            else:
                selected = get_reply_by_index(group_id, selected_index)
            if selected is not None:
                reply_type, keyword = selected

        deleted = remove_reply(group_id, keyword, reply_type)
        if not deleted:
            yield self._yield_plain(event, f"未找到回复：{keyword}")
            return
        await asyncio.to_thread(cleanup_unused_reply_images, group_id)
        add_operation_log(group_id, self._get_sender_id_from_event(event), "",
                          "删除问答", keyword, reply_type, "")
        type_text = {
            "exact": "精确",
            "fuzzy": "模糊",
            "regex": "正则",
            "all": "匹配到的",
        }[reply_type]
        yield self._yield_plain(event, f"✅️ 已删除{type_text}回复：{keyword}")

    async def _handle_list_replies(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="reply"
        )
        if not ok:
            yield err
            return
        
        replies = list_replies(group_id)
        entries = list(iter_reply_entries(group_id))
        if not entries:
            yield self._yield_plain(event,"当前没有自动回复")
            return

        # Keep one global, one-based index across all rule kinds.  The same
        # ordering is consumed by ``/删除 N`` so operators can remove the
        # item they just saw without guessing which storage bucket it uses.
        type_labels = {"exact": "精确", "fuzzy": "模糊", "regex": "正则"}
        result = "自动回复列表：\n"
        result += "\n".join(
            f"{index}. [{type_labels.get(entry_type, entry_type)}] {keyword}"
            for index, (entry_type, keyword) in enumerate(entries, 1)
        )
        if replies.get("cooldown", 0) > 0:
            result += f"\n冷却时间: {replies['cooldown']} 秒"
        yield self._yield_plain(event,result.strip())

    async def _handle_clear_replies(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="reply"
        )
        if not ok:
            yield err
            return
        
        clear_replies(group_id)
        await asyncio.to_thread(cleanup_unused_reply_images, group_id, {})
        yield self._yield_plain(event,"已清空所有自动回复")

    async def _handle_set_reply_cooldown(self, event: AstrMessageEvent) -> None:
        ok, group_id, err = await self._check_admin_group(
            event, required_sub_admin_permission="reply"
        )
        if not ok:
            yield err
            return

        message = (event.message_str or "").strip()
        parts = message.split()
        if len(parts) < 2:
            yield self._yield_plain(event, "用法: /设置回复冷却 <秒数>")
            return

        try:
            seconds = int(parts[1])
            if seconds < 0:
                yield self._yield_plain(event, "冷却时间不能小于 0 秒。")
                return
            set_reply_cooldown(group_id, seconds)
            yield self._yield_plain(event, f"已设置回复冷却：{seconds}秒")
        except ValueError:
            yield self._yield_plain(event, "冷却时间必须是整数。")

    async def _check_keyword_filter(self, event: AstrMessageEvent) -> bool:
        """
        检查消息是否包含敏感关键词
        返回 True 表示消息被过滤，False 表示正常
        """
        message = self._get_event_message_text(event)
        if not message:
            return False
        # Some OneBot adapters include @ targets in the text projection. They
        # are metadata, not user content; filtering them can match a numeric
        # rule and unexpectedly execute a moderation action.
        filter_message = re.sub(
            r"(?:CQ:at,qq=|\[At:|\[at:|@)\d{5,20}\]?",
            "",
            message,
            flags=re.IGNORECASE,
        ).strip()
        if not filter_message:
            return False
        
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            return False
        
        user_id = self._get_sender_id_from_event(event)
        
        log_enabled = self.qqadmin_filter_enable_log
        if log_enabled:
            logger.debug(f"[关键词过滤] 开始检查 | 群:{group_id} 用户:{user_id} | 消息: '{filter_message[:80]}'")

        # ========== 1. 检查功能是否开启（分群feature配置，统一系统） ==========
        from .qqadmin.group_config import get_group_feature_detail, get_group_data
        kf_detail = get_group_feature_detail(group_id, "keyword_filter", self.config)
        group_enabled = kf_detail.get("enabled", None)
        if group_enabled is None or (isinstance(group_enabled, bool) and group_enabled is False):
            # 分群没有单独设置enabled字段，使用全局开关
            if not self.qqadmin_enable_keyword_filter:
                if log_enabled:
                    logger.debug(f"[关键词过滤] 跳过: 全局开关关闭，且分群未单独开启")
                return False
        else:
            if not group_enabled:
                if log_enabled:
                    logger.debug(f"[关键词过滤] 跳过: 分群单独关闭功能")
                return False

        # ========== 2. 检查管理员跳过 ==========
        admin_bypass = kf_detail.get("admin_bypass_filter", self.qqadmin_admin_bypass_filter)
        if admin_bypass:
            is_admin = await self._is_admin_or_owner_async(event)
            if is_admin:
                if log_enabled:
                    logger.debug(f"[关键词过滤] 跳过: 用户{user_id}是管理员/群主/主人")
                return False

        # ========== 3. 获取关键词列表 ==========
        default_keywords = kf_detail.get("filter_keywords", self.qqadmin_filter_keywords)
        custom_keywords = get_group_data(group_id, "custom_filter_keywords", [])
        # 合并去重（保序）
        seen = set()
        filter_keywords = []
        for kw in list(default_keywords) + list(custom_keywords):
            if kw not in seen:
                seen.add(kw)
                filter_keywords.append(kw)

        # ========== 4. 获取正则列表 ==========
        default_regex = kf_detail.get("filter_regex_patterns", self.qqadmin_filter_regex_patterns)
        custom_regex = get_group_data(group_id, "custom_filter_regex", [])
        seen2 = set()
        filter_regex_patterns = []
        for p in list(default_regex) + list(custom_regex):
            if p not in seen2:
                seen2.add(p)
                filter_regex_patterns.append(p)

        if log_enabled:
            logger.debug(f"[关键词过滤] 关键词:{len(filter_keywords)}个 正则:{len(filter_regex_patterns)}个 | 列表: {filter_keywords}")

        # ========== 5. 检查关键词匹配 ==========
        for keyword in filter_keywords:
            if not keyword:
                continue
            if keyword in filter_message:
                logger.debug(f"[关键词过滤] ✅ 命中 '{keyword}' | 群:{group_id} 用户:{user_id}")
                await self._handle_filter_action(event, keyword)
                return True

        # ========== 6. 检查正则表达式匹配 ==========
        for pattern in filter_regex_patterns:
            if not pattern:
                continue
            try:
                if re.search(pattern, filter_message):
                    logger.debug(f"[关键词过滤] ✅ 正则命中 '{pattern}' | 群:{group_id} 用户:{user_id}")
                    await self._handle_filter_action(event, pattern)
                    return True
            except re.error as e:
                logger.error(f"[关键词过滤] 无效正则 {pattern}: {e}")

        if log_enabled:
            logger.debug(f"[关键词过滤] 未命中 | 群:{group_id} 用户:{user_id}")
        return False

    async def _handle_filter_action(self, event: AstrMessageEvent, matched_content: str) -> None:
        """
        处理关键词过滤后的动作
        """
        group_id = self._get_group_id_from_event(event)
        user_id = self._get_sender_id_from_event(event)
        
        # 获取分群配置（优先使用分群feature设置）
        from .qqadmin.group_config import get_group_feature_detail
        kf_detail = get_group_feature_detail(group_id, "keyword_filter", self.config)
        # Destructive actions must be explicitly selected from the supported
        # set. A malformed/legacy web value falls back to a warning, never a
        # kick or blacklist operation.
        allowed_actions = {"warn", "mute", "kick", "delete", "delete_warn", "blacklist"}
        raw_filter_action = (
            kf_detail.get("filter_action")
            if isinstance(kf_detail, dict) and "filter_action" in kf_detail
            else getattr(self, "qqadmin_filter_action", "warn")
        )
        filter_action = str(raw_filter_action or "warn").strip().lower()
        if filter_action not in allowed_actions:
            logger.warning(
                "关键词过滤动作配置无效，已降级为警告 group=%s user=%s raw_action=%r matched=%s",
                group_id,
                user_id,
                raw_filter_action,
                str(matched_content)[:80],
            )
            filter_action = "warn"
        # A keyword hit alone is not proof that a member should be removed.
        # Only an explicit blacklist action (which records the user first) or
        # an already active blacklist entry may call the kick API.  Legacy
        # configs often contained ``kick`` while the UI displayed warning;
        # downgrade that unsafe mismatch to a warning instead of removing a
        # normal member.
        if filter_action == "kick":
            logger.warning(
                "关键词过滤动作 kick 已降级为 warn；只有明确拉黑的用户才允许踢出 "
                "group=%s user=%s matched=%s",
                group_id,
                user_id,
                str(matched_content)[:80],
            )
            filter_action = "warn"
        filter_mute_duration = kf_detail.get("filter_mute_duration", self.qqadmin_filter_mute_duration)
        fallback_warn_message = str(
            kf_detail.get("warn_message", self.qqadmin_warn_message)
            or self.qqadmin_warn_message
        ).strip()
        raw_warning_messages = kf_detail.get(
            "warning_messages", self.qqadmin_warning_messages
        )
        if isinstance(raw_warning_messages, str):
            warning_messages = [
                item.strip()
                for item in raw_warning_messages.splitlines()
                if item.strip()
            ]
        elif isinstance(raw_warning_messages, (list, tuple, set)):
            warning_messages = [
                str(item).strip() for item in raw_warning_messages if str(item).strip()
            ]
        else:
            warning_messages = []
        # The portal caps list fields at 200 entries; retain the same bound
        # for manually edited legacy JSON before choosing a random message.
        warn_message = random.choice((warning_messages or [fallback_warn_message])[:200])

        def render_notice(raw_value: object, fallback: str) -> str:
            """Render a per-group moderation message without blocking action."""
            value = str(raw_value or fallback).strip() or fallback
            try:
                return value.format(
                    user_id=user_id,
                    group_id=group_id,
                    keyword=matched_content,
                )
            except Exception:
                # Unknown variables in a customer template should not stop
                # the moderation action or disclose a formatting traceback.
                return value

        warn_message = render_notice(warn_message, fallback_warn_message)
        mute_message = render_notice(
            kf_detail.get("mute_message", self.qqadmin_mute_message),
            str(self.qqadmin_mute_message),
        )
        kick_message = render_notice(
            kf_detail.get("kick_message", self.qqadmin_kick_message),
            str(self.qqadmin_kick_message),
        )
        blacklist_message = render_notice(
            kf_detail.get("blacklist_message", self.qqadmin_blacklist_message),
            str(self.qqadmin_blacklist_message),
        )
        
        # 执行动作
        if filter_action == "warn":
            # 发送警告消息（带@用户）
            from astrbot.core.message.components import At, Plain
            chain = [At(qq=int(user_id)), Plain(" " + warn_message)]
            await self._send_group_msg_with_id(group_id, chain, context=self.context)
        elif filter_action in {"delete", "delete_warn"}:
            deleted = False
            try:
                message_id = self._get_event_message_id(event)
                if message_id is None:
                    raise RuntimeError("事件中没有消息 ID")
                platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                if not platform:
                    raise RuntimeError("AIOCQHTTP 平台不可用")
                delete_result = await platform.get_client().call_action(
                    action="delete_msg", message_id=int(message_id)
                )
                if not self._api_result_succeeded(delete_result):
                    raise RuntimeError("QQ 平台拒绝了过滤撤回请求")
                deleted = True
                logger.debug(
                    f"[关键词过滤] 已撤回用户 {user_id} 的消息，关键词:'{matched_content}'"
                )
            except Exception as e:
                logger.error(f"关键词过滤撤回失败: {e}")
            if filter_action == "delete_warn":
                # A warning remains useful even if a platform adapter cannot
                # expose the original message ID.  It identifies the matched
                # rule without echoing the user's potentially unsafe content.
                from astrbot.core.message.components import At, Plain

                chain = [At(qq=int(user_id)), Plain(" " + warn_message)]
                await self._send_group_msg_with_id(group_id, chain, context=self.context)
                logger.debug(
                    "[关键词过滤] 撤回并警告 group=%s user=%s deleted=%s",
                    group_id,
                    user_id,
                    deleted,
                )
        elif filter_action == "mute":
            try:
                platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                if platform:
                    api_result = await platform.get_client().call_action(
                        action="set_group_ban",
                        group_id=int(group_id),
                        user_id=int(user_id),
                        duration=filter_mute_duration
                    )
                    if not self._api_result_succeeded(api_result):
                        raise RuntimeError("QQ 平台拒绝了过滤禁言请求")
                    logger.debug(f"[关键词过滤] 已禁言用户 {user_id}，时长 {filter_mute_duration}s")
                    await self._send_group_msg(group_id, mute_message, context=self.context)
            except Exception as e:
                logger.error(f"禁言失败: {e}")
                # 禁言失败时仍然发送警告消息
                await self._send_group_msg(group_id, warn_message, context=self.context)
        elif filter_action == "kick":
            try:
                logger.warning(
                    "关键词过滤执行明确配置的踢出动作 group=%s user=%s matched=%s",
                    group_id,
                    user_id,
                    str(matched_content)[:80],
                )
                platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                if platform:
                    api_result = await platform.get_client().call_action(
                        action="set_group_kick",
                        group_id=int(group_id),
                        user_id=int(user_id),
                        reject_add_request=False
                    )
                    if not self._api_result_succeeded(api_result):
                        raise RuntimeError("QQ 平台拒绝了过滤踢出请求")
                    logger.debug(f"[关键词过滤] 已踢出用户 {user_id}，关键词:'{matched_content}'")
                    await self._send_group_msg(group_id, kick_message, context=self.context)
            except Exception as e:
                logger.error(f"踢人失败: {e}")
        elif filter_action == "blacklist":
            # 添加到黑名单
            blacklist_added = add_to_blacklist(
                group_id,
                user_id,
                f"关键词过滤: {matched_content}",
                operator_id="system",
                ban_type="permanent",
            )
            if not blacklist_added or not is_in_blacklist(group_id, user_id):
                logger.error(
                    "关键词过滤未确认黑名单写入，禁止踢出 group=%s user=%s matched=%s",
                    group_id,
                    user_id,
                    str(matched_content)[:80],
                )
                await self._send_group_msg(group_id, warn_message, context=self.context)
                return
            # 踢出群
            try:
                platform = self.context.get_platform(filter.PlatformAdapterType.AIOCQHTTP)
                if platform:
                    api_result = await platform.get_client().call_action(
                        action="set_group_kick",
                        group_id=int(group_id),
                        user_id=int(user_id),
                        reject_add_request=True
                    )
                    if not self._api_result_succeeded(api_result):
                        raise RuntimeError("QQ 平台拒绝了关键词过滤踢出请求")
                    logger.debug(f"[关键词过滤] 已拉黑并踢出用户 {user_id}，关键词:'{matched_content}'")
                    await self._send_group_msg(group_id, blacklist_message, context=self.context)
            except Exception as e:
                logger.error(f"拉黑并踢出失败: {e}")
        
        # 添加操作日志
        if self.qqadmin_filter_enable_log:
            add_operation_log(group_id, user_id, "", "关键词过滤", matched_content, filter_action, "")

    async def _sync_group_config(self, event: AstrMessageEvent) -> None:
        """
        同步全局配置到当前群
        """
        # 使用异步权限检查确保正确识别管理员身份
        if not await self._check_feature_permission_async(event, "group_config", "modify"):
            yield self._yield_plain(event,"权限不足，无法执行此操作。")
            return
        
        group_id = self._get_group_id_from_event(event)
        if not group_id or group_id == "None":
            yield self._yield_plain(event,"此命令只能在群组中使用。")
            return

        # ``get_nested`` used to live only inside ``__init__`` (and inside
        # the group-request handler), so this command raised ``NameError``
        # as soon as it reached the first configuration key.  Keep the
        # lookup local to the sync operation and accept the same schema
        # wrappers used by the startup loader (``items``/``default``).
        def get_nested(*keys, default=None):
            value = self.config
            for key in keys:
                if isinstance(value, dict) and "items" in value:
                    value = value["items"]
                if not isinstance(value, dict) or key not in value:
                    return default
                value = value[key]
            if isinstance(value, dict) and "items" in value:
                value = value["items"]
            if isinstance(value, dict) and "default" in value:
                value = value["default"]
            return default if value is None else value
        
        # 同步各个功能的配置
        config_keys = [
            # 全局群管设置
            "qqadmin.enable_group_manage",
            "qqadmin.enable_group_config",
            
            # 自定义回复配置
            "qqadmin.reply.enable_reply",
            "qqadmin.reply.default_reply_cooldown",
            "qqadmin.reply.enable_keyword_reply",
            "qqadmin.reply.enable_exact_match",
            "qqadmin.reply.max_reply_length",
            "qqadmin.reply.cache_reply_images",
            "qqadmin.reply.reply_image_max_mb",
            "qqadmin.reply.reply_image_download_concurrency",
            "qqadmin.reply.reply_image_retry_interval",
            "qqadmin.reply.use_permission",
            "qqadmin.reply.modify_permission",
            
            # 禁言系统配置
            "qqadmin.mute.enable_mute",
            "qqadmin.mute.default_mute_level",
            "qqadmin.mute.default_mute_duration",
            "qqadmin.mute.use_permission",
            "qqadmin.mute.modify_permission",
            
            # 踢出系统配置
            "qqadmin.kick.enable_kick",
            "qqadmin.kick.auto_blacklist_on_kick",
            "qqadmin.kick.default_kick_limit",
            "qqadmin.kick.use_permission",
            "qqadmin.kick.modify_permission",
            
            # 黑名单系统配置
            "qqadmin.blacklist.enable_blacklist",
            "qqadmin.blacklist.auto_kick_blacklisted",
            "qqadmin.blacklist.auto_blacklist_on_leave",
            "qqadmin.blacklist.auto_blacklist_on_verify_fail",
            "qqadmin.blacklist.use_permission",
            "qqadmin.blacklist.modify_permission",
            
            # 入群审核配置
            "qqadmin.audit.enable_audit",
            "qqadmin.audit.enable_invite_audit",
            "qqadmin.audit.default_approval_mode",
            "qqadmin.audit.default_verification_timeout",
            "qqadmin.audit.max_verify_attempts",
            "qqadmin.audit.kick_on_verification_failure",
            "qqadmin.audit.admin_bypass_verify",
            "qqadmin.audit.use_permission",
            "qqadmin.audit.modify_permission",
            
            # 撤回系统配置
            "qqadmin.recall.enable_recall",
            "qqadmin.recall.enable_self_recall",
            "qqadmin.recall.default_recall_time",
            "qqadmin.recall.default_recall_mode",
            "qqadmin.recall.recall_keywords",
            "qqadmin.recall.recall_regex_patterns",
            "qqadmin.recall.enable_admin_recall",
            "qqadmin.recall.recall_notification",
            "qqadmin.recall.recall_notification_message",
            "qqadmin.recall.use_permission",
            "qqadmin.recall.modify_permission",
            
            # 统计系统配置
            "qqadmin.stats.enable_stats",
            "qqadmin.stats.auto_update_on_join",
            "qqadmin.stats.abnormal_invite_threshold",
            "qqadmin.stats.signin_base_reward",
            "qqadmin.stats.signin_reward_3_days",
            "qqadmin.stats.signin_reward_7_days",
            "qqadmin.stats.signin_reward_14_days",
            "qqadmin.stats.signin_reward_30_days",
            "qqadmin.stats.use_permission",
            "qqadmin.stats.modify_permission",
            
            # 入群欢迎配置
            "qqadmin.welcome.enable_welcome",
            "qqadmin.welcome.enable_auto_welcome",
            "qqadmin.welcome.welcome_check_interval",
            "qqadmin.welcome.default_welcome_delay",
            "qqadmin.welcome.default_welcome_message",
            "qqadmin.welcome.enable_farewell",
            "qqadmin.welcome.default_farewell_message",
            "qqadmin.welcome.welcome_keywords",
            "qqadmin.welcome.auto_reply_enabled",
            "qqadmin.welcome.at_new_member",
            "qqadmin.welcome.use_permission",
            "qqadmin.welcome.modify_permission",
            
            # 关键词过滤配置
            "qqadmin.keyword_filter.enable_keyword_filter",
            "qqadmin.keyword_filter.filter_keywords",
            "qqadmin.keyword_filter.filter_regex_patterns",
            "qqadmin.keyword_filter.filter_action",
            "qqadmin.keyword_filter.filter_mute_duration",
            "qqadmin.keyword_filter.warn_message",
            "qqadmin.keyword_filter.enable_log",
            "qqadmin.keyword_filter.admin_bypass_filter",
            "qqadmin.keyword_filter.use_permission",
            "qqadmin.keyword_filter.modify_permission",
            
            # 配置管理权限
            "qqadmin.group_config.use_permission",
            "qqadmin.group_config.modify_permission",
            "qqadmin.global_config.use_permission"
        ]
        
        synced_count = 0
        for config_key in config_keys:
            value = get_nested(*config_key.split("."), default=None)
            if value is not None:
                set_group_setting(group_id, config_key, value)
                synced_count += 1
        
        yield self._yield_plain(event,f"已同步 {synced_count} 项配置到当前群")

