    @filter.command("设置专属回复艾特")
    @filter.event_message_type(filter.EventMessageType.GROUP_MESSAGE)
    async def handle_set_player_reply_at(self, event: AstrMessageEvent) -> None:
        if not await self._is_admin_or_owner_async(event):
            yield self._yield_plain(event, "只有管理员或群主才能执行此操作。")
            return
        group_id = str(getattr(getattr(event, 'message_obj', None), 'group_id', '') or '')
        if not group_id or group_id == "None":
            yield self._yield_plain(event, "此命令只能在群组中使用。")
            return
        message = (event.message_str or "").strip()
        parts = message.split()
        if len(parts) < 2:
            yield self._yield_plain(
                event,
                f"用法: /设置专属回复艾特 <开/关>\n当前状态: {'开 'if self.player_reply_enable_at_user else '关 '}"
            )
            return
        flag = parts[1]
        if flag in ["开", "开启", "true", "True", "1", "on"]:
            new_value = True
            msg = "✅️ 用户专属回复艾特已开启"
        elif flag in ["关", "关闭", "false", "False", "0", "off"]:
            new_value = False
            msg = "❌️ 用户专属回复艾特已关闭"
        else:
            yield self._yield_plain(event, "参数错误，请输入 开 或 关")
            return

        # 更新内存配置
        self.player_reply_enable_at_user = new_value
        if "qqadmin"not in self.config:
            self.config["qqadmin"] = {}
        if "player_reply"not in self.config["qqadmin"]:
            self.config["qqadmin"]["player_reply"] = {}
        self.config["qqadmin"]["player_reply"]["enable_at_user"] = new_value

        # 写入磁盘，确保重启后不丢失
        try:
            from astrbot.core.utils.astrbot_path import get_astrbot_data_path
            config_path = os.path.join(get_astrbot_data_path(), "config", "astrbot_plugin_joker_config.json")
            self._write_json_atomic(config_path, self.config)
            logger.debug(f"用户专属回复艾特设置已保存: {new_value}")
        except Exception as e:
            logger.warning(f"保存配置到磁盘失败: {e}")

        yield self._yield_plain(event, msg)

    @filter.command("添加专属回复")
    async def handle_add_player_reply(self, event: AstrMessageEvent) -> None:
        if not await self._is_admin_or_owner_async(
            event, required_sub_admin_permission="reply"
        ):
            yield self._yield_plain(event,"只有管理员或群主才能执行此操作。")
            return
        
        if not self.qqadmin_enable_player_reply:
            yield self._yield_plain(event,"❌️ 用户专属回复功能已关闭")
            return

        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event,"此命令只能在群组中使用")
            return

        message = (event.message_str or "").strip()
        parts = message.split(None, 2)
        if len(parts) < 3:
            yield self._yield_plain(event,"用法: /添加专属回复 <QQ> <消息>")
            return

        # 解析用户ID（支持 @QQ 格式或直接 QQ 号）
        user_id_raw = parts[1]
        user_id = self._extract_user_id(user_id_raw)
        
        if not user_id or not user_id.isdigit():
            yield self._yield_plain(event,"请输入正确的QQ号或@用户")
            return

        reply_message = parts[2]

        from .qqadmin.player_reply import get_player_reply, add_player_reply

        existing = get_player_reply(group_id, user_id)
        if existing:
            messages = existing.get('messages', [])
            messages.append(reply_message)
            add_player_reply(group_id, user_id, messages, existing.get('at_user', True), existing.get('enabled', True))
            yield self._yield_plain(event,f"已添加用户 {user_id} 的专属回复\n 当前共 {len(messages)} 条消息，触发时随机发送一条")
        else:
            add_player_reply(group_id, user_id, [reply_message], self.player_reply_default_at_user)
            yield self._yield_plain(event,f"已为用户 {user_id} 设置专属回复\n 可继续使用 /添加专属回复 添加更多消息")

    @filter.command("删除专属回复")
    async def handle_remove_player_reply(self, event: AstrMessageEvent) -> None:
        """删除指定用户的专属回复（不填序号则删除所有）"""
        if not await self._is_admin_or_owner_async(
            event, required_sub_admin_permission="reply"
        ):
            yield self._yield_plain(event,"只有管理员或群主才能执行此操作。")
            return

        if not self.qqadmin_enable_player_reply:
            yield self._yield_plain(event,"❌️ 用户专属回复功能已关闭")
            return

        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event,"此命令只能在群组中使用")
            return

        message = (event.message_str or "").strip()
        
        # 解析命令，支持 @用户 或 QQ号 格式
        # 格式: /删除专属回复 <用户> [序号]
        # 不填序号则删除该用户的所有回复
        parts = message.split(None, 2)
        if len(parts) < 2:
            yield self._yield_plain(event,"用法: /删除专属回复 <QQ> [序号]\n 不填序号则删除该用户所有回复")
            return

        # 解析用户ID（支持 @QQ 格式或直接 QQ 号）
        user_id_raw = parts[1]
        user_id = self._extract_user_id(user_id_raw)
        
        if not user_id or not user_id.isdigit():
            yield self._yield_plain(event,"请输入正确的QQ号或@用户")
            return

        from .qqadmin.player_reply import remove_player_reply, remove_player_reply_message, get_player_reply

        # 检查用户是否有专属回复
        player_reply = get_player_reply(group_id, user_id)
        if not player_reply:
            yield self._yield_plain(event,f"用户 {user_id} 没有专属回复配置")
            return

        # 如果没有指定序号，或者序号不是纯数字，则删除所有
        if len(parts) < 3 or not parts[2].isdigit():
            message_count = len(player_reply.get('messages', []))
            if remove_player_reply(group_id, user_id):
                yield self._yield_plain(event,f"已删除用户 {user_id} 的所有专属回复（共 {message_count} 条）")
            else:
                yield self._yield_plain(event,f"删除失败，请重试")
            return

        # 指定了序号，删除指定的回复
        index = int(parts[2])
        messages = player_reply.get('messages', [])
        if index < 1 or index > len(messages):
            yield self._yield_plain(event,f"序号无效，当前有 {len(messages)} 条回复消息")
            return

        removed_msg = messages[index - 1][:30] + ('...'if len(messages[index - 1]) > 30 else '')
        remove_player_reply_message(group_id, user_id, index)

        # 检查是否还有剩余消息
        player_reply_after = get_player_reply(group_id, user_id)
        remaining = len(player_reply_after.get('messages', [])) if player_reply_after else 0

        if remaining > 0:
            yield self._yield_plain(event,f"已删除第 {index} 条回复: {removed_msg}\n 剩余 {remaining} 条回复")
        else:
            yield self._yield_plain(event,f"已删除第 {index} 条回复: {removed_msg}\n 该用户已无回复配置")

    @filter.command("删除用户专属回复")
    async def handle_remove_all_player_reply(self, event: AstrMessageEvent) -> None:
        """删除指定用户的所有专属回复"""
        if not await self._is_admin_or_owner_async(
            event, required_sub_admin_permission="reply"
        ):
            yield self._yield_plain(event,"只有管理员或群主才能执行此操作。")
            return

        if not self.qqadmin_enable_player_reply:
            yield self._yield_plain(event,"❌️ 用户专属回复功能已关闭")
            return

        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event,"此命令只能在群组中使用")
            return

        message = (event.message_str or "").strip()
        parts = message.split()
        if len(parts) < 2:
            yield self._yield_plain(event,"用法: /删除用户专属回复 <QQ>")
            return

        # 解析用户ID（支持 @QQ 格式或直接 QQ 号）
        user_id_raw = parts[1]
        user_id = self._extract_user_id(user_id_raw)
        
        if not user_id or not user_id.isdigit():
            yield self._yield_plain(event,"请输入正确的QQ号或@用户")
            return

        from .qqadmin.player_reply import remove_player_reply, get_player_reply

        # 先检查用户是否有专属回复
        player_reply = get_player_reply(group_id, user_id)
        if not player_reply:
            yield self._yield_plain(event,f"用户 {user_id} 没有专属回复配置")
            return

        message_count = len(player_reply.get('messages', []))
        if remove_player_reply(group_id, user_id):
            # 验证删除是否成功（强制重新加载配置）
            from .qqadmin.group_config import _config_cache
            _config_cache.pop(group_id, None)  # 清除缓存强制重新加载
            check_reply = get_player_reply(group_id, user_id)
            if check_reply is None:
                yield self._yield_plain(event,f"已删除用户 {user_id} 的所有专属回复（共 {message_count} 条）")
            else:
                yield self._yield_plain(event,f"删除可能未完全生效，请稍后刷新或检查配置")
        else:
            yield self._yield_plain(event,f"删除失败，请重试")

    def _extract_user_id(self, user_raw: str) -> str:
        """从 @用户 或 QQ号 格式中提取用户ID"""
        import re
        if not user_raw:
            return ""
        # 处理 [At:QQ] 格式 (AstrBot内部格式)
        match = re.search(r'\[At:(\d+)\]', user_raw)
        if match:
            return match.group(1)
        # 处理 @用户(QQ) 格式 (QQ显示格式)
        match = re.search(r'@.+?\((\d+)\)', user_raw)
        if match:
            return match.group(1)
        # 处理 @QQ 格式 (纯数字@)
        match = re.search(r'@(\d+)', user_raw)
        if match:
            return match.group(1)
        # 处理 CQ码格式 [CQ:at,qq=QQ]
        match = re.search(r'\[CQ:at,qq=(\d+)\]', user_raw)
        if match:
            return match.group(1)
        # 直接是纯数字
        if user_raw.isdigit():
            return user_raw
        # 尝试提取字符串中的第一个数字序列
        match = re.search(r'(\d{5,})', user_raw)
        if match:
            return match.group(1)
        return ""

    @filter.command("设置专属回复")
    async def handle_set_player_reply(self, event: AstrMessageEvent) -> None:
        if not await self._is_admin_or_owner_async(
            event, required_sub_admin_permission="reply"
        ):
            yield self._yield_plain(event,"只有管理员或群主才能执行此操作。")
            return
        
        if not self.qqadmin_enable_player_reply:
            yield self._yield_plain(event,"❌️ 用户专属回复功能已关闭")
            return

        group_id = self._get_group_id_from_event(event)
        if not group_id:
            yield self._yield_plain(event,"此命令只能在群组中使用")
            return

        message = (event.message_str or "").strip()
        parts = message.split(None, 2)
        if len(parts) < 3:
            yield self._yield_plain(event,"用法: /设置专属回复 <QQ> <消息>")
            return

        # 解析用户ID（支持 @QQ 格式或直接 QQ 号）
        user_id_raw = parts[1]
        user_id = self._extract_user_id(user_id_raw)
        
        if not user_id or not user_id.isdigit():
            yield self._yield_plain(event,"请输入正确的QQ号或@用户")
            return

        reply_message = parts[2]

        from .qqadmin.player_reply import get_player_reply, add_player_reply

        existing = get_player_reply(group_id, user_id)
        old_count = len(existing.get('messages', [])) if existing else 0
        add_player_reply(group_id, user_id, [reply_message], existing.get('at_user', True) if existing else self.player_reply_default_at_user, existing.get('enabled', True) if existing else True)
        if old_count > 1:
            yield self._yield_plain(event,f"已覆盖用户 {user_id} 的专属回复\n 原 {old_count} 条消息已被替换为 1 条")
